window.READER_DATA={"title": "Yakan Lubnaniyya", "slug": "yakan-lubnaniyya", "pages": [{"n": 1, "paras": ["النجيب يكن المسألة اللبنانية من منظمة السلامة"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0001.png"}, {"n": 2, "paras": ["فتحى يكن", "المسألة اللبنانية من منظور اسلامي", "المؤسسة الاسلامية للطباعة والصحافة والنشر بيروت"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0002.png"}, {"n": 3, "paras": ["جميع الحقوق محفوظة الطبعة الاولى", "١٣٩٩ ه - ١٩٧٩ م", "الأهداء", "* إلى اللبنانيين الذين يفتشون عن حل جذري يخرجهم من دوامة الشقاء ..", "* إلى كل إنسان له قلب أو ألقى السمع وهو شهيد .. أقدم هذه الدراسة فتحي يكن"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0003.png"}, {"n": 4, "paras": ["تمهيد", "تناولت القضية اللبنانية بالتحليل والدرس أقلام شتى طوال الأزمة الأخيرة وعلى مدار الأزمات التي مر بها هذا البلد وما أكثرها ..", "تناولتها أقلام اليمين واليسار .. اليمين المعتدل واليمين المتطرف .. كذلك اليسار بكل فئاته وتنظيماته ..", "ولقد بقيت كل تلكم التحليلات والدراسات - على ما بينها من تناقض - تدور في إطار المرئيات القريبة والخلفيات المرئية دون أن تلامس جوهر القضية الحضاري وخلفياتها العقيدية المتحكمة في جذور البنية اللبنانية على مدار التاريخ ..", "وحتى لا نقع فيما وقع فيه غيرنا ... فتأتي دراسة القضية اللبنانية مرتهنة لما هو مطروح في ساحة الصراع اللبناني والعربي والعالمي ، وجدنا أن تعالج القضية في ضوء الأطر التالية :", "(١) البنية اللبنانية على مدار التاريخ .", "(٢) تركيب البنية اللبنانية .", "(٣) آراء في خلفيات الأزمة اللبنانية .", "(٤) حجم الحرب اللبنانية .", "(٥) الحلول المطروحة للمسألة اللبنانية .", "(٦) الحل من منظور إسلامي .", "V"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0004.png"}, {"n": 5, "paras": ["لبنان على مدار التاريخ", "الفصل الاول"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0005.png"}, {"n": 6, "paras": ["لبنان على مدار التاريخ الحاضر لا يمكن أن يفهم فهماً صحيحاً إلا في ضوء الماضي بالإضافة إلى المستجدات . وتاريخ الدول والشعوب والأمم سلسلة من حلقات متداخلة متشابكة لا انفكاك لأحداها عن الأخرى ، وإلا انقطع التاريخ وتعتعت الرؤيا وقصر النظر .. فلنستعرض أحوال البنية اللبنانية عبر التاريخ القديم والحديث . أجمع الجغرافيون على أن لبنان جزء من الشام البلد الذي أطلق عليه اسم سوريا .. وعلى أن العرب جاؤوا إلى سورية قبل ثلاثة آلاف سنة من ولادة السيد المسيح (١) . وسنة ٦٤ قبل الميلاد احتل الرومان لبنان بعد انتصارهم على الدولة السلوقية وجعلوا مدينة ( انطاكية ) مركزاً للولاية التي كانت تضم سورية ولبنان .. ولقد منح الرومان بعض المدن اللبنانية امتيازات خاصة ، جعلت أهلها وكأنهم ( مواطنون رومانيون ) يدفعون ضريبة أقل من غيرهم ولهم الحق في الوصول إلى أعلى الوظائف في الدولة الرومانية ..", "(١) رواية روبنسر في كتابه ( تاريخ اسرائيل ) ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0006.png"}, {"n": 7, "paras": ["سنة ٣٩٥ خضع لبنان للبيزنطيين .. فقسموه قسمين قسم ساحلي وقسم داخلي ، وظلوا فيه حتى الفتح الإسلامي . وفي عهد الخلفاء الراشدين تمكن المسلمون من إجلاء البيزنطيين عن سوريا وفلسطين ولبنان ومصر ، كما تمكنوا من القضاء على دولة الفرس في العراق وإيران قضاء ساحقاً . ولقد كان البيزنطيون يحكمون أهل تلك البلاد - مع أنهم على دينهم - بالحديد والنار .. يسومونهم سوء العذاب ويفرضون عليهم من القوانين ما يشقيهم ويعنتهم في أنفسهم وأموالهم .. وهذا ما دفع بأهل البلاد إلى أن يكتبوا إلى المسلمين الفاتحين كتاباً يوقعه رهبانهم وقساوستهم يقولون فيه ( أنتم أحب إلينا من الروم - وإن كانوا على ديننا - لأنكم أرأف بنا وأرحم لنا ) . وفي عهد الخلفاء الأمويين حاول الجراجمة (١) بالتعاون مع الدولة البيزنطية غزو سوريا والإيقاع بدولة الأمويين ، وكان الأسطول البيزنطي يقدم لهم العون من الساحل لاشعال الفتن في الدولة الإسلامية . ولكن هذا العدوان كان وبالاً عليهم ، إذ حمل عليهم مسلمة بن عبد الملك في خلافة أخيه الوليد بن عبد الملك ( ٨٦ - ٩٦ ه = ٧٠٥ - ٧١٤ م ) فأفنى من أفنى منهم ، وعندها استسلم المردة في جبال لبنان للدولة الأموية . ويقول عبد الكريم الدندشي في كتابه ( العروبة في لبنان ) صفحة ٥٥ : ( ويظهر أن عملية إجلاء الأجانب من السواحل كانت من الأمور التي اهتم لها الأمويون . فجميع النصوص التي تعنى بفتح السواحل تخبرنا عن جلاء هذه الثغور .", "فلم يبق والحالة هذه سوى السكان الأصليين والعرب الفاتحين وبعض العناصر الفارسية التي أسكنها معاوية في بعض مدن الساحل . وهكذا نرى أن وجود المردة في أنحاء لبنان كان من الأسباب التي دعت العرب إلى التوغل فيه للخلاص منهم ، فلم يقتصر دخولهم على الساحل ، بل وصلوا إلى قممه العالية ) . وفي عهد الخلافة العباسية حاول الموارنة سنة ١٤٢ ه ٧٥٩ م الخروج على الدولة وإثارة الفتن من جديد ولكن فتنتهم أخمدت في مهدها (١) .. ثم عمد العباسيون إلى إسكان كثير من العوائل الإسلامية في السواحل اللبنانية لتقاوم غزوات البيزنطيين ومؤامرات الجراجمة .. في عهد الصليبيين في القرون الوسطى كانت ذكريات فلسطين مؤلمة لدى الفرنجة كما هي الآن عند العرب والمسلمين .. وكانوا يتحينون الفرص لغزو البلاد الإسلامية .. فلما استفحل العراك بين الفاطميين والسلاجقة في بلاد الشام اغتنم الصليبيون الفرصة ووجه البابا أوربانوس نداءه المشهور لتحرير فلسطين من أيدي المسلمين عام ١٠٩٥ ثم كانت أولى الحملات الصليبية عام ١٠٩٦ . ولقد استقر الأمر للصليبيين نحو نصف قرن ثم بدأت المقاومة الإسلامية تحرر البلاد المستعمرة بلداً بلداً .. ففي عام ١١٤٤ استعاد آل زنكي الرها .. وفي عام ١١٧٨ استعاد صلاح الدين القدس .. وفي عام ١٢٩١ أجلى المماليك الصليبيين عن هذه البلاد ..", "(١) قال البلاذري في فتوح البلدان صفحة ١٦٢ ( في هذه المناسبة ثار في لبنان قوم فصالحه بن علي ابن عبد الله بن عباس من قتل مقاتليهم ، واقر من بقي منهم على دينهم ، فردهم الى قراهم ، وأجلى قوماً من أهل لبنان ) .", "(١) طائفة الجراجمة سموا كذلك نسبة الى قرية (جراجومة ) الواقعة في جبل اللكام شمالي سوريا ، وهناك أقوال بأن الجراجمة هم الموارنة ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0007.png"}, {"n": 8, "paras": ["بعد الحروب الصليبية استقرت الأمور في لبنان استقراراً منقطع النظير .. جاء في كتاب «لبنان» (١) وبقي لبنان في سكينته فتوفرت فيه الراحة . وقصده الناس حباً بالأمن والطمأنينة لا سيما الموارنة المتفرقون في الأماكن البعيدة . وفي ذلك الوقت بنيت عدة كنائس وأديرة وأرسل رسوليون إلى لبنان من الرهبان الصغار ) . في عهد آل عثمان عندما سقطت القسطنطينية بأيدي العثمانيين عام ٨٥٧ ه = ١٤٥٣ م تحولت أنظارهم إلى بلاد الشام الواقعة يومئذ تحت حكم المماليك . وفي سنة ١٥١٦ تمكن السلطان سليم الأول من احتلال سوريا وبعدها مصر .. كان لبنان طوال الحكم العثماني مصدراً للفتن من قبل النصارى .. يقول الدكتور مشاقة في كتابه «مشهد عيان» وأخذوا يعقدون الجلسات خصوصاً أهالي كسروان ومن جاورهم ، وأكثروا من الشكوى . وبلغت القحة والجهالة بهم إلى تهديد الدولة بالعصيان ، وخصوصاً بعد تصريحهم بأنهم ينتمون إلى دولة أجنبية ) . هذه الفتن الطائفية أفضت إلى حل جديد اقترحه «أسعد باشا» ويقضي بتقسيم لبنان إلى قائمقاميتين : قائمقامية الموارنة وقائمقامية الدروز . وقد كرس هذا التقسيم وأثار فتناً بين النصارى والدروز سنة ١٨٤٣ و ١٨٤٤ و ١٨٦٠ وكانت الأخيرة أعظمها حيث دفعت فرنسا إلى غزو سوريا واحتلالها باسم الدول الأوروبية . وهكذا أصبحت قضية لبنان قضية دولية . عهد المتصرفية يتلخص نظام المتصرفية بأن يتولى حكم جبل لبنان متصرف مسيحي من غير أهله ينصب من قبل الباب العالي العثماني ويعاونه مجلس إدارة مؤلف من إثني عشر عضواً من طوائفه . ولقد تولى شؤون المتصرفية ثمانية ، كان أولهم داود باشا (١٨٦١-١٨٦٨) وآخرهم أوهانس قيومجيان (١٩١٢-١٩١٥) .", "وعندما نشبت الحرب العالمية الأولى ألغى العثمانيون البروتوكول السابق ونصبوا على التوالي ثلاثة متصرفين منهم كان آخرهم ممتاز بك الذي غادر البلاد في ٣٠ أيلول ١٩١٨ . عهد الانتداب في سنة ١٩٢٠ أعلن الجنرال غورو دولة لبنان الكبير في حين كان لبنان حتى عهد الانتداب الفرنسي جزءاً من سورية . يقول المؤرخ المرحوم محمد جميل بيهم في كتابه «عروبة لبنان» صفحة ٢٠٠ : ( أن اسم لبنان في معجم السياسة لم يكن له وجود قبل البروتوكول الذي وضعته الدول في أعقاب ثورة ١٨٦٠ ، وكذلك فهو لم يتمتع بشيء يسمى الاستقلال الناجز إلا في سنة ١٩٤٣ ) . وفي معرض التدليل على ( أن لبنان جزء متمم لسورية لا يتجزأ منها ) قال ندرة المطران في كتابه «سورية الغد» المطبوع في باريس سنة ١٩١٦ : ( أول ما نبدأ به القول أن سوريا ولبنان حكمها على التتابع ملوك آشور وبابل ، ثم الفرس ، فالاسكندر الأكبر ، فالسلوقيون ، فالأنابطسة ، وأخيراً الرومان . أما بعد المسيح فقد تعاقب عليها البيزنطيون فالأمويون فالعباسيون فالطولونيون ، فالسلاجقة ، فأتابكة سورية ، فالصليبيون ، فالأيوبيون ثم قلاوون وسلالته ، فالمماليك البحرية ، ثم سلاطين بني عثمان ) . لبنان الكبير ! في سنة ١٩٢٤ أصدر المستعمر الفرنسي قراراً بمقتضاه بلاد الشام حيث أعطى المواطنين حرية اختيار الجنسية اللبنانية أو السورية .. وبهذا القرار تكون", "(١) اسم كتاب ألفته لجنة بأمر متصرف لبنان اسماعيل حقي بك سنة ١٩١٧ ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0008.png"}, {"n": 9, "paras": ["الكيان المصطنع وتكون بالتالي شعب لبنان ، بعد أن فصل عن الجسم الكبير ليعيش هذه التجربة الجديدة !! ودولة لبنان هذه تضم الجبل الذي يشكل بأكثريته الطائفة المارونية ، والساحل والبقاع اللذين يتشكلان بأكثريتهما من المسلمين . ولقد قامت معارضة عنيفة من السوريين في وجه هذا الإجراء ، إلا أنها تلاشت بعد البروتوكول الذي صدر في الإسكندرية والذي أقرت فيه الدول العربية حدود لبنان وكيانه الجديد عام ١٩٤٤ . وهكذا قام الكيان اللبناني بإرادة استعمارية ليواجه في تاريخه القصير والقصير جداً عشرات الفتن والكوارث لأنه في الواقع يفقد مبررات الحياة ككيان منفصل ، ويحوي من المتناقضات ما لا يحصيه عد كما سيتيبن لنا في الفصول اللاحقة ..", "تركيب البنية اللبنانية", "* التركيب الطائفي", "* التركيب الحزبي", "الفصل الثاني"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0009.png"}, {"n": 10, "paras": ["تركيب البنية اللبنانية", "ليس من قبيل المبالغة القول بأن الكيان اللبناني تركيبة عجيبة وفريدة لا تماثلها تركيبة دولة في العالم .. أ الطوائف يبلغ عدد الطوائف المعترف بها في لبنان سبعة عشر طائفة هي :", "١ الطائفة السنية .", "٢ الطائفة الشيعية الجعفرية .", "٣ الطائفة الدرزية .", "٤ الطائفة العلوية .", "٥ الطائفة الإسماعيلية .", "٦ الطائفة المارونية .", "٧ طائفة الروم الأرثوذكس .", "٨ طائفة الروم الكاثوليك .", "٩ الطائفة الأرمنية الغريغورية الأرثوذكسية .", "١٠ الطائفة الأرمنية الكاثوليكية .", "١١ الطائفة السريانية الأرثوذكسية .", "١٢ الطائفة السريانية الكاثوليكية .", "١٣ الطائفة الشرقية النسطورية .", "١٤ الطائفة الكلدانية ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0010.png"}, {"n": 11, "paras": ["١٥ - الطائفة اللاتينية .", "١٦ - الطائفة الانجيلية .", "١٧ - الطائفة الإسرائيلية . هذا وقد ذكرت احصاءات صدرت مؤخراً عن مصادر رسمية أن عدد سكان الطوائف اللبنانية أصبح كما يلي :", "٩٧٠ ألف نسمة شيعة .", "٦٩٠ ألف نسمة سنة .", "٣٤٨ ألف نسمة دروز .", "٤٦٩ ألف نسمة موارنة .", "٢٣٠ ألف نسمة أرثوذكس .", "٢١٣ ألف نسمة كاثوليك .", "٣٦٠ ألف نسمة أرمن .", "( ب ) الأحزاب أما عن الأحزاب الموجودة في لبنان فعجيبة أخرى من عجائب هذا الكيان .. ويمكن القول بأن في لبنان نسخاً مصغرة لكل ما في العالم من أحزاب بالإضافة إلى الأحزاب اللبنانية والزعامية المحلية .. وفيما يلي أبرز هذه الأحزاب :", "- حزب الاتحاد الدستوري : وهو حزب تقليدي يحرص على استمرار التعايش وفق الميثاق الوطني والدستور .", "- حزب الكتائب اللبنانية : وهو حزب مسيحي يؤمن ببقاء لبنان ذي الوجه المسيحي بحجة ( عقدة الخوف ) .", "- حزب الكتلة الوطنية : وهو حزب مسيحي لا يختلف كثيراً من حيث معتقده اللبناني وإن كان يبدو أنه أكثر مرونة من الكتائب !!", "- الحزب التقدمي الاشتراكي : حزب اشتراكي قاعدته درزية ، يتبنى العلمانية للخلاص من الطائفية ..", "- حزب النجادة : جماهيره مسلمة ، يؤمن بعروبة لبنان ويدعو إلى إلغاء الطائفية السياسية .", "- حزب الهيئة الوطنية : حزب تقليدي له مواقف وتطلعات إسلامية لبنانية كانت أبرز نشاطاته فترة ما قبل الأحداث اللبنانية الأخيرة ( ١٩٧٥ - ١٩٧٦ ) .", "- الحزب الديمقراطي : حزب جديد للشباب الساعي لإبعاد الطائفية عن طريق طروحات علمانية .", "- حزب الاستقلال : قاعدته شيعية ويعمل من أجل حقوقها المختلفة .", "- الحزب القومي السوري : حزب عقائدي علماني له فلسفة ( مدرحية ) عجيبة . كان معروفاً بميوله الغربية وميوله اليمينية ثم أخذ يتجه نحو الاشتراكية !", "- الحزب الشيوعي اللبناني : وهو امتداد للتنظيم الشيوعي الرسمي العالمي وهدفه تحويل المجتمع إلى مجتمع اشتراكي ..", "- حزب البعث العربي الاشتراكي : حزب اشتراكي الأفكار والميول والسياسة بشقيه السوري والعراقي .", "- حزب الوطنيين الأحرار : حزب مسيحي زعامي طائفي له ارتباطات أجنبية ..", "- اتحاد الشباب الديمقراطي في لبنان : من اهتماماته تأصيل الروح الوطنية في الشباب والعمل على رفع مستواهم الثقافي والفكري الخ ..", "- حركة السلم اللبنانية : تنادي بالعمل على توطيد السلم العالمي وتأييد حق الشعوب في التحرر والاستقلال ، وتقرير مصيرها والعمل من أجل التعايش السلمي بين الدول ذات الأنظمة المختلفة ، ونزع السلاح ..", "- حركة التوعية الشعبية : وتعمل على تعبئة جميع اللبنانيين مقيمين ومغتربين وخاصة أبناء الجنوب لتحمل مسؤولياتهم بالنسبة للقضايا المصيرية ..", "- حزب الشبيبة العاملة اللبنانية : ومن أهدافه توطيد استقلال لبنان والمحافظة على سيادته وكيانه والتعاون العربي إلى أوسع مدى ضمن نطاق ميثاق جامعة"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0011.png"}, {"n": 12, "paras": ["الدول العربية ..", "- حركة العمل الوطني : وتهدف إلى تحقيق التنمية الاقتصادية والعدالة الاجتماعية وتأمين الخدمات التربوية والإنسانية ..", "- حركة الوعي اللبناني : وتهدف إلى إيقاظ الوعي في المواطن اللبناني لما فيه خير الوطن ..", "- اتحاد القوى الوطنية : ويهدف إلى تنمية روح المودة والإخاء بين الناس وترسيخ قواعد الوحدة الوطنية وبناء تكتل عربي موحد تسوده العدالة والرفاهية والحرية ..", "- الاتحاد النسائي السياسي اللبناني : ويهدف إلى توجيه المرأة اللبنانية لتفهم مسؤوليتها ، وتقوم بواجبها في كافة الميادين ، وتعزيز الكيان اللبناني ، وتدعيم علاقته مع الدول العربية ..", "- حركة الاتحاد الوطني الديمقراطي : وتهدف إلى تجميع العناصر التقدمية من اللبنانيين والعمل على توفير مجتمع لبناني أفضل ..", "- حزب الشعب الاشتراكي : ويهدف إلى المحافظة على سيادة لبنان واستقلاله وعروبته ..", "- الحركة اللبنانية للتجمع الوطني : وتهدف إلى إصلاح المجتمع اللبناني وجعل مصلحته فوق كل اعتبار وضمان حقوق المواطنين ..", "- حزب العمال اللبناني : ويهدف إلى المحافظة على سيادة واستقلال لبنان ..", "- حزب الهشناق : حزب أرمني يساري ويعتبر الخصم التقليدي لحزب الطاشناق .", "- حزب الطاشناق : حزب سياسي أرمني يميني انتشر بين اللاجئين الأرمن في الشرق الأوسط ، وينتهج سياسة موالية للغرب معادية للشيوعية .", "- حزب التحرير الإسلامي : حزب إسلامي سري التنظيم سياسي والتوجيه يركز على ضرورة إقامة الدولة الإسلامية .", "- الجماعة الإسلامية (١) : وهي حركة إسلامية ، رسالتها الإسلام وغايتها تعبيد الناس لربهم أفراداً وجماعات بإقامة المجتمع الإسلامي الذي يستمد أحكامه وتعاليمه من كتاب الله تعالى وسنة رسوله صلى الله عليه وسلم . والجماعة تنظم حركي يدعو الجميع إلى الإسلام وإلى تبني منهجه في الحياة لأنه منهج العليم الحكيم .. والجماعة الإسلامية تعتمد لتحقيق ذلك على تبليغ مبادئ الإسلام إلى الناس ، ودعوتهم إليها ، وإلى تربيتهم وتنظيمهم على أساسها .. ومن مقتضيات هذه الدعوة كذلك مكافحة الاستعمار وأفكاره ومخلفاته - شرقياً كان أم غربياً - حتى تعود للأمة شخصيتها المستقلة الأصيلة . وقياماً بواجب انقاذ المجتمع من كل مظاهر التناقض والانحراف .. والتزاماً بواجب دعوة الأمة إلى النهج الذي ارتضاه لها الله حين قال « اليوم أكملت لكم دينكم وأتممت عليكم نعمتي ورضيت لكم الإسلام دينا » ، وتأكيداً على أن الإسلام هو المنهج الذي لا صلاح للأمة بغيره .. من أجل ذلك ، قامت الجماعة الإسلامية في لبنان تستهدف ما يلي : أولاً : تبليغ دعوة الإسلام إلى الناس ، نقية صافية ، متصلة بالعصر ومشكلاته ، والحاضر ومتطلباته ، وإعادة صلة المسلمين به فهماً وإيماناً وعملاً . وإحياء روح الجهاد في سبيله ، وتجديد الثقة به انه سبيل الخلاص لهم ولسائر البشرية ، وانه الطريق الوحيد لما ينشدونه من أمن وعدالة وكرامة . ثانياً : تنظيم الذين استجابوا للدعوة إلى الإسلام . وتثقيفهم به وتربيتهم عليه وتأهيلهم ليكونوا الطليعة التي تؤمن بالحق وتعيشه ، وتستقطب الجماهير لتكوين رأي عام إسلامي . ثالثاً : مواجهة تحدي الحضارة الغربية ، والفلسفات الالحادية والوجودية ،", "(١) راجع نشرة مبادئ وأهداف الجماعة الاسلامية ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0012.png"}, {"n": 13, "paras": ["وموجات التهتك والاباحية ، بالدعوة إلى تقييم الأوضاع والتصورات والأفكار والنظم على أساس من نظرية الإسلام للكون والإنسان والحياة . رابعاً : السعي لبناء مجتمع جديد يكون فيه الإسلام هو الميزان الوحيد لتصرفات الفرد ، وهو الأساس الوحيد لعلاقات الأسرة ، وهو الضابط الوحيد للمعاملات بين الناس . وتقوم فيه كل المؤسسات على قواعد متينة من مبادئ هذا الدين الخالد . خامساً : السعي لجمع شمل المذاهب والفرق الإسلامية بالرجوع إلى أصول الإسلام .. سادساً : العمل على محاربة الطائفية الذميمة . ولقد حرصت الجماعة - من أول يوم - على أن تزيل عن الإسلام ركام البدع والخرافات ، وتقدمه للناس بصورته الصافية المشرقة التي توافق طبيعته ومحتواه . فهي تؤمن بأن أحكام الإسلام وتعاليمه شاملة .. تنتظم شؤون الناس على كل صعيد . وتعتبر الجماعة الإسلامية أن القاعدة الأساسية التي يقوم عليها الإسلام على مدار التاريخ البشري هي قاعدة « لا اله الا الله » أي افراد الله سبحانه في الألوهية والحاكمية ، افراده بها اعتقاداً في الضمير .. وعبادة في الشعائر .. وشريعة في واقع الحياة .. والجماعة تؤمن بالإسلام قوة أساسية لنهضة العرب والمسلمين . وتؤمن بضرورة تبني مبادئه وأحكامه في كل الخطى الاصلاحية - الاجتماعية والاقتصادية والسياسية -.. والاعتماد على روحه الثائرة في وجه الاستعمار والصهيونية .. وترى في تبني النظم الرأسمالية ، والدعوة إلى تطبيق الاشتراكية العلمية ، سيراً على غير هدى ، وتخبطاً بدون طائل ، واستنفاداً للجهود واضاعة للزمن ، وطمراً للتراث الإسلامي العظيم ، وتنكرأ لهذا الدين القيم .", "آراء في خلفيات الحرب اللبنانية", "* كونها نتيجة مخطط أميركي - إسرائيلي ..", "* كونها نتيجة مخطط روسي - فلسطيني ..", "* كونها نتيجة نزاع لبناني - لبناني ..", "* كونها نتيجة مخطط يساري ..", "* كونها نتيجة حرمان اجتماعي ..", "الفصل الثالث"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0013.png"}, {"n": 14, "paras": ["آراء في خلفيات الحرب اللبنانية", "تعدّدت الآراء وتباينت في تحديد خلفيات الحرب اللبنانية (٩٧٥ - ٩٧٩) . فبينما تعتبر بعض الآراء أن الخلفية الرئيسية للحرب هي القضية الفلسطينية ، تعتبر بعض الآراء الأخرى أن الخلفيات لبنانية صميمة وقديمة .. جاء في مقدمة كتاب ( حوادث لبنانية ) ١٩٧٥ لمؤلفه انطوان خويري ما يلي :", "تقديم لقد عرف تاريخ الشعوب حروباً أهلية ، وأخرى طبقية ، وأخرى دينية ، ولكنها كانت حروباً واضحة المعالم ، بيّنة الأهداف ، جلية الأبعاد ، يخوض المتقاتلون غمارها وهم على علم بما يفعلون وبما يريدون . أما الحرب التي اندلعت نيرانها على ارض لبنان ، في خلال عام ١٩٧٥ ، وامتدت بلهيبها إلى حد الشمول الجامع ، فإنها مجموعة أخلاط يتعذر أن نجد لها إسماً في معجمات الحروف عبر الزمان والمكان حتى أن أبطالها أنفسهم يعجزون عن بيان أسبابها ودوافعها ، ويعجزون العجز نفسه عن تحديد مراميها وأهدافها . من أجل ذلك نعتوا معاركها الضارية « بالجنون » لأن القتيل فيها مجرد قتيل ضحية وليس شهيداً في سبيل قضية ، والدمار الذي أشاعته في مختلف أرجاء البلاد مجرد تخريب وليس لشق طريق لمواكب النصر على عدو ظالم . ولما كان ذلك امرها انقلبت في عشوائيتها « ازمة مصيرية » تهدد الوجود"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0014.png"}, {"n": 15, "paras": ["اللبناني في حاضره وفي مستقبله بأوخم المغبات ، وتدفعه دفعاً ، من حيث يدري المتقاتلون أو لا يدرون ، إلى نسف الأسس الكيانية التي بُني عليها بنسف وحدته الجغرافية والاثنية ، ونسف حضارته الفذة التي انصهرت فيها الحضارتان العظيمان ، الحضارة المسيحية والحضارة الإسلامية ، وجعلت من لبنان ، في تقدير الشعوب والمؤسسات الدولية ، واقعاً فريداً يُضرب به المثل في التواجد النيّر والتعايش الخير بين الأديان المختلفة ، مكفولة لها الحريات الوجدانية ، متكاملة في التراثات الحضارية ، متكافلة في المصالح الوطنية والقومية الجامعة .", "وفي مجالات التحليل لهذه الأزمة المرة سواء كان في منطلقاتها ، أم في أهدافها وأبعادها ، ذهب الناس مذاهب شتى تتباين في عناصرها ، أو تلتقي متداخلة بعضها في بعض ، نتيجة تباين الزوايا التي يُنظر منها إليها ، وبتأثير النوازع والمشارب . وإذ نقف نحن موقف الحياد من كل تحليل وتعليل مقتصرين ، بحكم الغاية التي نقصد إليها ، على سرد الوقائع التي تعاقبت في الساحة اللبنانية ، في كل يوم من أيام الأزمة ، مساهمة منا في كتابة هذا الفصل القائم من تاريخ لبنان المديد ، نكتفي في مجال تحليل الأسباب والأهداف ، بإيراد ما ذهب إليه بعض الجهات موجزين وجهات نظرهم بكل تجرد وموضوعية وأمانة ، تاركين للقارئ الكريم أن يحكم هو نفسه في مقدار قيمتها .", "أولاً - الأزمة نتيجة مخطط « أميركي - إسرائيلي » : ذهب بعضهم إلى أن الأزمة في أسبابها وأهدافها وليدة مخطط أميركي - إسرائيلي غايته فرض الحل السلمي في منطقة الشرق الأوسط . وذلك بإنشاء دولة فلسطينية متاخمة لدولة إسرائيل ، يكون بعضها جزءاً من أرض لبنان ، ولكنها مجردة تماماً من السلاح . والطريق إلى تنفيذ هذا المخطط تقسيم لبنان وسوريا إلى دويلات طائفية مستقلة ، بحدود تكونها الفوارق المذهبية . وبهذه العملية الجراحية ، جغرافياً وإنسانياً ، تنتهي المعضلة المستعصية الضاربة جذورها في رقعة هذا الشرق ، فتعيش إسرائيل على الزمن حدود آمنة ، ويبقى النفوذ الأميركي مسيطراً في المنطقة كلها جمعاء .", "وعلى ضوء هذا الواقع ، يقول أصحاب هذا التحليل ، نفهم لماذا بدت حكومة الولايات الأميركية راضية كل الرضى ، في الباطن على أقل تقدير ، عما انتهت إليه الأحداث من بالغ التأزم والحدة ، في حدود المنطقة العربية ، وفي حدود لبنان خصوصاً . ذلك بأن إسرائيل التي ترفض جازماً عودة الفلسطينيين اللاجئين إلى أرض آبائهم وأجدادهم ، والتواجد معهم على هذه الأرض أياً كان نظام هذا التواجد ووجهه ، أقنعت الولايات المتحدة الأميركية باخفاق كل صيغة للتعايش بين الأديان المختلفة إخفاقاً جذرياً ، بدليل التجربة اللبنانية وما انتهت إليه من ضروب التناحر والدمار .", "ومن ثم فمن العبث البحث في الحل المقترح القائم على إنشاء دولة ديمقراطية تتواجد فيها الديانات الثلاث اليهودية والمسيحية والإسلام . وهو الحل الذي طرحه الرئيس اللبناني ، سليمان فرنجية ، في الأمم المتحدة ، باسم الدول العربية بأجمعها ، وباسم المقاومة الفلسطينية نفسها ، وأيده أكثر الدول الأعضاء في تلك الهيئة الدولية .", "وعلى هذا الأساس بالذات بدأت الولايات المتحدة الأميركية عملية توزيع الخريطة العربية على هذا وذاك من الفرقاء . فكانت الأزمة في لبنان ، وكانت أحداثها .", "ثانياً - الأزمة نتيجة مخطط « روسي - فلسطيني » : (١) ورأى فريق آخر أن الأزمة اللبنانية وليدة مخطط روسي - فلسطيني ، غايته المباشرة ، أن يستثير الاتحاد السوفياتي عناصر « الرفض » العربية والفلسطينية", "(١) رأي المنظمات اليمينية الطائفية"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0015.png"}, {"n": 16, "paras": ["التي ترفض الحل السلمي والتقسيم الطائفي، بحجة الاعتراف بحقوق الفلسطينيين المشروعة، وفرض وجودهم دولياً، تمهيداً لاسترداد فلسطين. وسبيل الاتحاد السوفياتي في تنفيذ مخططه هذا هو أولاً وبطبيعة الحال عملاؤه الشيوعيون وجبهة «اليسار الذكي»، وثانياً توفير السلاح والمال «للمنظمات التخريبية» بطريق السفارات الشيوعية وبعض السفارات العربية، وثالثاً ضرب القوى الاجتماعية بعضها ببعض وقلب الأنظمة في العالم العربي.", "وغاية موسكو الوراثية الاستفادة من الأزمة اللبنانية أولاً بطريق بيع الأسلحة وقبض أثمانها نقداً وعداً بالعملة الصعبة. وما من مطلع يجهل حاجة الاتحاد السوفياتي الماسة إلى العملة الصعبة لمواجهة التكنولوجيا الأميركية من جهة، ولشراء المواد الغذائية كالمح ق مثلاً، والمواد الأولية للصناعات المتعددة من الجهة الأخرى. ثم متى تمكن الاتحاد السوفياتي من تركيز قدمه في لبنان انطلق منه، بطريق لعبة اليسار الدولي، لقلب الأنظمة القائمة في رقعة هذا الشرق واستبدالها بالنظام الشيوعي الماركسي، أو الاشتراكي على أقل مطلب، للوصول بطريقة إلى «الكنز العربي».", "ثالثاً - الأزمة نتيجة مخطط «فلسطيني» (١) : ويرى فريق ثالث أن الأزمة اللبنانية وليدة مخطط فلسطيني على الأرض اللبنانية، تقصد منه المنظمات الفلسطينية إلى إقامة دولة ضمن الدولة في لبنان بحجة «الطابع المقدس» ل «قضية عربية» عادلة تكافح تحت لوائها انطلاقاً من «أرض عربية».", "على هذا الأساس مضت المنظمات الفلسطينية تتسلح بأخطر الأسلحة على غير رقابة من جانب الدولة اللبنانية وفي غفلة من هذه الدولة، ثم انتزعت منها اتفاقاً دولياً يبيح لها «في سبيل قضيتها» استيراد السلاح جهراً متجاوزة في النوع والكمية الحدود المتفق عليها، كما أنها تجاوزت في استخدام هذا السلاح وفي نطاق تحركاتها المتفق عليه، حدود السيادة اللبنانية إذ راحت تتحدى السلطات الشرعية والجيش اللبناني بالذات ساعية إلى فرص وجودها دولة ضمن الدولة بل دولة نداً للدولة إن لم يكن فوق الدولة بدليل انتزاعها السيادة، في خلال الأحداث الدامية، على مناطق متعددة من أرض لبنان كصيدا والجنوب، وطرابلس والبقاع، ثم بيروت التي حاولت المستحيل في احتلالها كلها بعد أن سيطرت على المنطقة الغربية منها وعلى بعض ضواحيها.", "وقد استعانت على هذا «الاحتلال» بالضغوط والأموال والأسلحة من بعض الدول العربية واليسار الدولي، علاوة على بعض القادة اللبنانيين الذين انجرفوا في تيارها لبلوغ بعض «المطالب»، وتنفيذ بعض النيات المتعارضة مع الوجود اللبناني كما أراده واتفق عليه بناة الاستقلال الأولون. وما وعى أولئك القادة اللبنانيون مغبة الازدواجية في قيادة هذه الفوضى التي انتهت إلى تسخين الجبهة العربية حتى الغليان فبات بالإمكان فرز المعادلات الدولية إلى «يمين ويسار»، بعيداً عن كل مطلب وحق وقضية، فيضيع لبنان كما ضاعت فلسطين، ويزيد الفلسطينيون إمعاناً في الضياع ويبقى «العز والمجد للعرب»!", "ولما كان الاتحاد السوفياتي أبداً في المرصاد لكل سانحة يستغلها في إطار أغراضه ورأى أن الوضع الذي وصلت إليه القضية الفلسطينية على الصعيد السياسي، ولا سيما صعيد ما بعد اتفاقية سيناء، يدعو إلى مزيد من القلق والخوف على القضية الفلسطينية برمتها، بادر إلى احتضان جبهة الرفض في صفوف أصدقائه العرب، وخصوصاً في صفوف المقاومة الفلسطينية، لتنفيذ مخططاته الهدامة، ولم يجد معها لتفجير عمليات النقمة والحقد، أرضاً أخصب من الأرض اللبنانية السائبة التي ما بسط نفوذه عليها هان عليه التسرب منها إلى منطقة الشرق العربي وثرواته الضخمة.", "(١) رأي المنظمات اليمينية الطائفية."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0016.png"}, {"n": 17, "paras": ["رابعاً - الأزمة نتيجة نزاع « لبناني - لبناني » : وحصر بعضهم أسباب الأزمة وأهدافها بين اللبنانيين أنفسهم . فالغاية منها تفجير الصراع السياسي الذي ظل كالنابض المضغوط طوال الثلاثين سنة من تاريخ الاستقلال ، وكان متجسداً في عقدة نفسية مزدوجة تلازم كلا الفريقين اللذين يؤلفان الشعب الواحد في حكم النظام الواحد : عقدة الخوف على الكيان اللبناني والمصير المسيحي من جانب الفريق المسيحي ، وهو خوف له جذوره ومبرراته التاريخية ؛ وعقدة الشعور بالغبن السياسي من جانب الفريق الإسلامي ، وهو ما ينعته « بالامتيازات » المسيحية ، بل مارونية ؛ ثم عقدة « عروبة » لبنان التي ينادي بها ويتهم الفريق الآخر برفضها لعدم إيمانه بها ولاقتناعه بأنها لا تعني في المفهوم الاسلامي سوى الاسلام .", "ومضى الفريق الإسلامي الذي لم يرضَ عن الاستقلال إلا مكرهاً - على حدّ قول البعض - ولم ينظر إلى الصيغة التي اتفق عليها الأولون ، وأسموها « بالميثاق الوطني » نظره إلى كيان نهائي بل إلى ما يشبه وجوداً آنياً مرحلياً تعقبه « وحدة عربية » أو « وحدة سورية » على أقل مطلب ، يوالي المطالبة بتغيير تلك الصيغة والنظام تحت شعار مماشاة التطور والتطلعات المستقبلية . فكانت من هنا ، في الأزمة الأخيرة ، مجموعة « المطالب الإسلامية » المعروفة وأخصها التحرر من قيود الميثاق الوطني ، وتعديل الدستور بحيث يتساوى ، في الدرجة ومسؤوليات الحكم ، رئيس الحكومة السنّي ورئيس الدولة الماروني ، بحكم كون الأول يمثل الفريق الإسلامي ، كما يمثل الآخر الفريق المسيحي ، ولا سيما وان إحدى مواد الدستور تنصّ على المساواة بين اللبنانيين في تولّي الوظائف العامة ولا تميز فيها بينهم إلا الكفاية والجدارة .", "وأما الفريق الآخر ، أي الفريق المسيحي ، فقد تمسك بالصيغة والنظام على نحو ما ارتضاه صانعو الاستقلال من كلا الطرفين المسيحي والإسلامي ، أساساً بل شرطاً لا بدّ منه للوجود اللبناني ووحدة الشعب اللبناني ، وإلا لما كان لبنان ولا كانت الوحدة اللبنانية . ويشدّد الفريق المسيحي على أن ما ينعته الفريق الآخر « بالامتيازات » لم يكن ، في حكم الرعيل الأول ، إلا محض « ضمانات » لاستمرار لبنان وطناً مستقلاً نهائياً ، واستمرار الجانب المسيحي بكامل شخصيته وحقوقه وحرياته في محيط الدول الإسلامية النازعة إلى تذويب لبنان في « الأمة الإسلامية » . وكان الإصرار من كلا الطرفين فكان الانفجار المسلح الذي جرّ على لبنان وأهله من مسلمين ومسيحيين القتل والخراب .", "خامساً - الأزمة نتيجة تخطيط « إسلامي - فلسطيني - يساري » : ويرى فريق من المحللين أن المحنة القاسية التي اجتازها لبنان وراكمت فيه الدمار ، إنما هي في أسبابها وأهدافها ، « إسلامية - فلسطينية - يسارية » . فالمسلمون من اللبنانيين لم يروا في استقلال لبنان ، عام ١٩٤٣ ، إلا مرحلة انتقالية تنتهي بلبنان ، عاجلاً أو آجلاً ، إلى الذوبان في « الوطن العربي الكبير » ، أي « الأمة الاسلامية » ، ولا سيما وأنه « لا يجوز تولي أمر المسلمين الا مسلم » ، كما صرح في إبان الأزمة مدير الافتاء العام الأستاذ حسين القوتلي ، « و لا يتم للمسلم إسلامه إلا بسيادة إسلامية » .", "وانطلاقاً من هذا المبدأ الديني يضاف إليه ويعزّزه اعتقادهم بأن المسلمين قد أصبحوا في لبنان أكثر عدداً ، مضوا يحاولون ، بكل وسيلة وفي كل فرصة سنحت ، انتزاع الرئاسة الأولى ، يساندهم في محاولاتهم بعض الدول العربية على الصعيدين المادي والمعنوي . فكان من أبرز تلك المحاولات ما اعتمد العنف سبيلاً كالمحاولة « الناصرية » عام ١٩٥٨ ، والمحاولة الأخيرة عام ١٩٧٥ ، التي اعتمدوا فيها السلاح الفلسطيني والسلاح اليساري أيضاً برغم إيمانهم في السر والجهر بأن الشيوعية هي عدوّ الإسلام الأكبر والأخطر . وأما الفلسطينيون ، في نظر هؤلاء المحللين ، فإنهم بعد إخفاقهم في جعل"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0017.png"}, {"n": 18, "paras": ["الأردن وطناً بديلاً عن فلسطين تحوّلوا إلى لبنان . وأنشأوا المقاومة المسلحة . وقوي ساعدهم بعد اتفاق القاهرة . وشرعوا يوالون التجاوزات على الشرعية وعلى الجيش . وساندهم المسلمون حتى في تجاوزاتهم بل مكنوهم من تجميد الجيش بالذات بدافعي الوحدة في الدين من جهة ، وبلوغ أغراضهم من الجهة الأخرى . وانتصر لهم اليساريون أيضاً ، ولليسار الدولي أهدافه المعلومة .", "واليساريون ، ويدخل تحت هذه التسمية « الأحزاب التقدمية » على أنواعها ، وأبرزهم الشيوعيون والاشتراكيون ، ولهم في المقاومة الفلسطينية أتباع كثيرون ، وجدوا في الجيش الفلسطيني وفي الجبهة الإسلامية معاً مطية لبلوغ أهدافهم من لبنان فيقلبون نظامه الديمقراطي البرلماني الحر ويفرضون عليه النظام الماركسي .", "فتتكون من هذه الجبهات الثلاث جبهة واحدة لاحتلال لبنان بالحديد والنار وإشاعة الموت والدمار في جميع جنباته . فيستسلم لإرادة المسلمين من لبنانيين وفلسطينيين . ثم يتدبّر اليسار أمره .", "سادساً - الأزمة نتيجة « انكماش مسيحي وضيق إسلامي » : ويذهب فريق آخر من المحللين ، إلى أن أسباب الأزمة اللبنانية وأهدافها وليدة الانكماش المسيحي تجاه الزحف العروبي الإسلامي من داخل ومن خارج . فالمسلمون من خارج يضيقون ذرعاً بقيام بلد صغير كلبنان بوجه مسيحي بارز في خضم الشرق العربي والإسلامي . والمسلمون من داخل ما يزالون يعتبرون ، منذ التحاقهم بدولة « لبنان الكبير » ، أنهم من بعض الوجوه ، خارج السرب العربي الإسلامي فيحاولون الالتحاق بالثورة يحدوهم عليها ويشد أزرهم العرب المسلمون من خارج .", "وأما المسيحيون فلا يبرحون يحنّون إلى وطن كانوا ينعمون به ويرون أنهم فقدوا تدريجياً ، بتعايشهم مع المسلمين ، أهم ما كافحوا في سبيله طوال قرون على الصعيدين الثقافي والوطني . فقد اضطروا إلى التضحية شيئاً فشيئاً ، على مذبح هذا التعايش ، بمقومات ثقافتهم لأن شركاءهم يرفضون كل ما يحمل طابعاً مسيحياً فيسمونه « استعماراً » ، وكل ما يحمل طابعاً لبنانياً فيسمونه « انعزالية » . ويرون أيضاً ، في المجال السياسي ، أنهم « فقدوا كل مبادرة منذ ارتباط مصيرهم بمصير العروبة ، وكثيراً ما سويت مشاكل العالم العربي على حسابهم » . فانكمشوا على أنفسهم فكان من نتائج هذا الانكماش الاصطدام المروّع الذي أشاع الخراب والدمار في البلاد .", "سابعاً - الأزمة نتيجة « حرمان اجتماعي » : ورأى البعض أخيراً أن أسباب الأزمة وغايتها نتيجة « حرمان اجتماعي » . فالحرمان في تقديرهم يشمل بعض المناطق اللبنانية ، فيما المغانم من حظ بعض المناطق الأخرى ، فحمل بعض النافذين لواء الكفاح في سبيل إزالة هذا الحيف ، وبسط سلطان المساواة بين المناطق كلها ، وبين اللبنانيين جميعاً ، ولو قضى ذلك بتحكيم السلاح . وكان من الطبيعي أن يتحرك اليسار بقوة ، وراء هذا الشعار البراق ، الذي يلوح به على الدوام أمام عيون الطبقات الكادحة والفئات الفقيرة من الشعب . ومضوا كلهم يتهمون الحكام ويخطئون النظام ويدعون إلى الثورة .", "غير أن معظم أهل الرأي لا يرون في ادعاء هذا الحرمان إلا غلالة شفافة تستر وراءها أغراضاً ما كانت قط ولن تكون في مصلحة لبنان واللبنانيين جميعاً ، إذ أن معالجة الحرمان ، في حال وجود الحرمان ، لا يمكن أن تكون بطريق تدمير المؤسسات والمرافق الاقتصادية في البلاد إذ لا يجني منه « المحرومون » إلا مزيداً من الحرمان ! وإذا كانت الحكومات المتعاقبة قد وقعت في أخطاء كثيرة وبددت الكثير من أموال الشعب في الكثير من الطرق المعوجة ، فإنما أخطاؤها لم تنحصر بنتائجها في فئة من اللبنانيين دون سواها ، بل كانت جامعة شاملة . وإذا ظهرت على أرض لبنان ، مناطق مزدهرة فإنما ذلك نتيجة طموح الأفراد بمعزل عن الدولة ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0018.png"}, {"n": 19, "paras": ["تلك هي أبرز وجوه التحليل والتعليل للأزمة ، عرضناها باقتضاب وكنا على أمانة في عرضها . فقد يكون بعضها أصوب من بعض ، وقد يكون بعضها مكملاً لبعض ، وقد يكون لها كلها سهم في انفجار الأزمة .", "خلفيات اساسية للمسألة اللبنانية", "* التناقض الطائفي", "* التناقض الاقتصادي", "* التناقض في الانتماء الحزبي", "* التناقضات العربية", "* التناقض الدولي والقضية الفلسطينية", "الفصل الرابع"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0019.png"}, {"n": 20, "paras": ["خلفيات أساسية للمسألة اللبنانية", "إن اعتبارنا أن الفراغ العقائدي هو العامل الأساسي للأزمة اللبنانية ولغيرها من الأزمات لا ينفي وجود عوامل وخلفيات أخرى مساعدة .. وفي مفهومنا العقائدي أن هذه العوامل والخلفيات الأخرى هي كذلك من مفرزات الفراغ العقائدي ..", "فما هي هذه الخلفيات ؟.", "١ - التناقض في الانتماء الطائفي : إن بلداً كلبنان في صغر مساحته وتعدد انتماءات المواطنين الطائفية فيه - على نحو ما ذكرنا في فصل سابق - عامل من عوامل الصراع والشقاق بحد ذاته فكيف إذا كان هنالك تسلط من طائفة على أخرى ..", "إن التناقض في الإنتماء الطائفي جعل لبنان على مدار تاريخه قابلاً للتفجر ، عرضة للتمزق لدى أدنى احتكاك . ولقد شهد الكيان اللبناني من جراء ذلك سلسلة متتابعة من الأحداث والفتن والحروب كان آخرها حرب السنتين ١٩٧٥ - ١٩٧٦ . لقد أعطى الانتداب الفرنسي إلى الموارنة القوامة على الطوائف الأخرى ، واختصهم بامتيازات منذ الاستقلال ، ثم تكرست هذه الفوقية وأصبحت عرفاً في كل مجالات الدولة ، حتى غدا للموارنة حصة الأسد في كل شأن . جاء في كتاب ( المسلمون في لبنان مواطنون لا رعايا ) للأستاذ محمد علي ضناوي ما يلي :"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0020.png"}, {"n": 21, "paras": ["١ - رئاسة مجلس القضاء الأعلى .", "٢ - رئاسة النيابة العامة التمييزية .", "٣ - رئاسة مصرف لبنان .", "٤ - رئاسة مجلس الخدمة المدنية .", "٥ - رئاسة الجامعة اللبنانية .", "٦ - رئاسة تعاونية الموظفين .", "٧ - رئاسة الجمارك العليا .", "٨ - رئاسة مجلس البورصة .", "٩ - رئاسة الأمن العام .", "١٠ - رئاسة مجلس السياحة .", "١١ - رئاسة الريجي .", "١٢ - رئاسة التنظيم المدني .", "١٣ - رئاسة المشروع الأخضر .", "١٤ - رئاسة الانعاش الاجتماعي .", "١٥ - رئاسة كهرباء لبنان .", "١٦ - رئاسة مشروع الليطاني .", "١٧ - رئاسة المجلس الوطني للبحوث العلمية .", "١٨ - رئاسة المجلس التأديبي .", "وظائف كبرى محظورة على المسلمين فإذا تركنا ، وظيفة الوظائف ، رئاسة الجمهورية ومستشاريها ومديرييها ، جانباً ، فإننا سننتقل بشكل طبيعي إلى قيادة الجيش ، وقيادة الدرك ، ولن نتعرض هنا إلى الترقيات التي تكون بلا حساب للبعض وتكون بحساب شديد ، بل يمتنع على بعض الضباط الآخرين الترقي ، لذلك لم نسمع في يوم من الأيام أن مسلماً في لبنان أصبح جنرالاً ، ربما لأن الجنرالية كانت في يوم من الأيام سبباً لرئاسة الجمهورية !! وبعد أن نترك قيادة القوى العسكرية وأركانها ومجالسها العليا ومصالحها الرئيسية وشعبها المهمة وكلها لغير المسلمين (١) نعود إلى السلك المدني فنرى أن أهم وزارات الدولة ليس فيها توازن بين المسلمين وغيرهم ، فهذه مديريات وزارة التربية والخارجية والدفاع والاعلام والداخلية والمالية والبرق والبريد ، فنكاد لا نرى فيها مسلماً ، حتى أن السفراء المسلمين في الخارجية اللبنانية لا يتجاوز عددهم ربع عدد السفراء ، ومؤخراً جرى التوظيف بالتعاقد في أكثر وزارات الدولة والجيش والإعلام ، فكان الحرمان المطلق نصيب المسلمين . ثم لو عدنا إلى رئاسات عامة لوجدنا أن الرئاسات التالية هي لغير المسلمين ومحظر على المسلمين تسلمها :", "(١) في جلسة الثقة بحكومة الرئيس « تقي الدين الصلح » بتاريخ ٢٦-٧-١٩٧٣ . أذاع رئيس لجنة الدفاع في المجلس النيابي النائب العقيد فؤاد لحود - بشكل تساؤل - تدعم ما ذكرناه وتشير بوضوح إلى حرمان المسلمين من قيادات الجيش والقوى العسكرية . قال العقيد : « هل يجوز أن يكون القاده في الوحدات العسكرية ٨٥ في المئة من الطوائف المسيحية و١٥ في المئة من الطوائف المحمدية ؟ إنني أعارض هذا التوزيع » ( تراجع صحف يوم الجمعة ٢٧-٧-١٩٧٣ ) ومن المؤسف أن النواب ، وخاصة المسلمين ، لم يتحركوا حتى أن فتح لهم الباب على مصراعيه مع أنهم كانوا يحضرون الجلسة الأولى النيابية بعد ركوبهم موجة المشاركة . فتأمل ! ؟", "ولا بد ونحن في صدد طائفية الوظيفة أن نسجل الاستقراء التالي ، وهو أنه ، في حال شغور منصب من مناصب ومراكز الإدارة اللبنانية ، ويكون هذا المنصب لمسلم ، على قلة تلك المناصب ، فإنه في الغالب تبقى هذه الوظيفة شاغرة فترة من الزمن ، وتوجه خلال فترة الشغور وكالة إلى موظف غير مسلم ، حتى إذا جدّ الجد ووجب التوظيف عين غير المسلم فيها ، وهكذا تكون الطائفة قد خسرت"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0021.png"}, {"n": 22, "paras": ["مركزاً مهماً على قلة تلك المراكز - كما أسلفنا - (١) ومن العجيب والوضع كما هو مبين ومفصل أعلاه أن تعقد الدراسات وتشتد المطالبات بإلغاء طائفية الوظيفة بتحريرها من المناصفة وبإطلاق العنان للمسؤولين مجدداً بالتعيين الاعتباطي والأعجب من ذلك أن تعتبر تلك الدراسات أن إلغاء طائفية الوظيفة السبيل الأول والهام نحو إلغاء الطائفية من النفوس ومن النظام والأغرب من ذلك كله أن ينخدع بعض السياسيين بهذا الوهم الكاذب وهذا البريق المزيف والأنكى من كل ما تقدم أن تدرج هذه الفكرة في مجمع بعبدا المشؤوم حيث تم الاتفاق ، ولو لم يُعلن ذلك رسمياً ، على ضرورة إلغاء طائفية الوظيفة والمجمع ، وإن لم يصدر قراره بشأن إلغاء طائفية الوظيفة ، فإن القناعات لا تزال متوفرة عند المعنيين ، وذلك بعد أن ضاقوا ذرعاً بمبدأ المناصفة مع سوء تطبيق هذا المبدأ ومع ما وجدنا من حيف ومن هضم لحقوق المسلمين فيه فالمكاسب البسيطة التي جنتها الطائفة في لبنان من مبدأ المناصفة أزعج ويزعج من بيدهم الأمر ، لأنهم لا يريدون أن يكون المسلمون وهم ، في الوظيفة سواء من هنا فقد راح البعض محاولاً تفسير المناصفة بأن العدد في كل وزارة من الوزارات ، يجب أن يتساوى مع ما للطائفة الأخرى ، فبالتالي يمكن ، في عرفهم ، أن يعين رئيس مصلحة مثلاً غير مسلم وبالمقابل يعين لتحقيق التوازن الطائفي كاتب من المسلمين ولا ريب أن هذا التفسير اعتباطي وغير قانوني وهو مردود شكلاً وأساساً ومرفوض بكل أبعاده ومراميه مؤامرة إلغاء المعادلات : وعندما اصطدم المعنيون بصعوبة ما يخططون له ، خاصة وأن الطائفة الإسلامية غدت تمتلك أعداداً ضخمة من المثقفين وحملة الشهادات العليا يوازي عدد أبناء الطوائف الأخرى ، إن لم نقل يزيد ، راح هؤلاء المعنيون يخططون بذكاء ملحوظ ولكنه مكشوف مفضوح ،", "فدرسوا أسباب تزايد حملة الشهادات العليا فوجدوا أن الجامعات العربية وبالذات الستينات الجامعة العربية في بيروت ، راحت تقذف المجتمع اللبناني بآلاف من المتخرجين المسلمين الذين درسوا في معاهدها تأسيساً على شهادات مدرسية ، كالمقاصد في بيروت ودار التربية في طرابلس ، أو على شهادات معادلة للبكالوريا القسم الثاني اللبنانية أعني الموحدة السورية والتوجيهية المصرية . وبعد وقوفهم على هذا النبع الثري الذي يفيض بالدراسات الجامعية والثانوية قرروا وقف المعادلات ومنعوا بعض الدراسات الجامعية إلا لحملة البكالوريا اللبنانية كالحقوق مثلاً ، ونصوا على إعطاء الأفضلية لحملة الإجازات والشهادات العليا إذا كانت مؤسسة على البكالوريا اللبنانية واعتبروا حملة الشهادات المعادلة مواطنين من الدرجة الثانية لأن هؤلاء يأتون دوماً بعد حملة البكالوريا اللبنانية", "(١) في جواب للأستاذ أمين العريسي رئيس اللجنة التنفيذية للهيئات الإسلامية في المؤتمر الصحفي بتاريخ ١١-٩-١٩٧٣ ، ذكر المراكز التالية التي انتقلت من يد المسلمين إلى يد المسيحيين : « مديرية المالية » وكانت سابقاً لمسلم . مديرية التربية ، وكانت سابقاً لمسلم . مديرية البريد والبرق والهاتف ، وكانت سابقاً لمسلم .. رئاسة الأطفائية ، وكانت في السابق لمسلم . محافظة بيروت ، وكانت في السابق لمسلم .. وطبعاً كان هذا الإنتقال بدون عوض ومن المعروف أن أهم سبب في لجوء الطلاب المسلمين - بصورة خاصة - إلى الشهادات المعادلة هو الضعف الواضح في إتقان اللغة الأجنبية ، فالمدارس الرسمية في لبنان - سبعون بالمائة من طلابها مسلمون - تهمل اللغة الأجنبية ولا تضمن إتقانها كما هو الحال في المدارس الأجنبية والإرساليات والمعاهد الخاصة « نسبة"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0022.png"}, {"n": 23, "paras": ["الطلاب المسيحيين فيها ٧٠ بالمئة تقريباً . ولا يعني هذا أن حملة البكالوريا هم من غير المسلمين فقط ، فالمسلمون وسواهم سواء إزاء امتحاناتها وللطائفة الإسلامية نسبة محترمة من حملتها ، بالرغم مما نوهنا عنه من ضعف اللغة الأجنبية في المدارس الرسمية ، إلا أننا قصدنا مما قدمنا أن حملة الشهادات الجامعية المصرية والعربية وحملة الشهادات الثانوية المعادلة ، هم في غالبيتهم العظمى من الطائفة الإسلامية ، فيغدو حرمانهم وتصنيفهم فئات بعد البكالوريا اللبنانية كما يغدو حرمانهم من دراسات جامعية معينة افتئاتاً على حق الطائفة في لبنان وهضماً لحقوقها لأن ذلك يقلل من فرص الوظيفة والعمل العام بالنسبة لها .", "إن الوظيفة في لبنان خدمة عامة ، وهي تشكّل القطاع الأهم ، في بلد قائم على الخدمات ، لذلك فيجب أن تصان حقوق الطائفة الإسلامية بشكل نهائي ، وحلّ الثورة اللبنانية اعتمد المناصفة سبيلاً لتحقيق العدالة والذي جاء جزئياً وناقصاً ينبغي أن يستكمل صورته باعتماده على كل صعيد ولمختلف الوظائف الكبرى المدنية وغير المدنية ، وذلك إلى أن تُلغى الطائفية السياسية من كل النصوص والنفوس ابتداء من رئاسة الجمهورية (١)", "(١) أذاعت الهيئات الإسلامية في مؤتمرها المنعقد في ١١-٩-١٩٧٣ في بيروت بياناً جاء فيه : « اننا عندما نرى أبناءنا لا يستطيعون دخول الجامعات التبشيرية المسيطرة نتيجة وجود تفرقة فئوية ، وكذلك لا يمكنهم تسلم المراكز المفاتيح في الدولة ولا في المؤسسات المالية والاقتصادية ، وعندما تصعقنا الاحصاءات الادارية ، بفئة هي نصف البلاد وأكثر تتراوح نسبتها بين ٨٠ و ٩٠ ٪ عندما نجد أن التسهيلات المالية والمصرفية تؤمن لفئة واحدة أكثر بكثير من الاخرى ، عندما نجد أن مجالس الإدارات العامة والخاصة في البلاد تكاد تكون مطلقاً ، عندما نرى أبناءنا في الأزقة والشوارع ومناطقنا مهملة بينما تصرف الملايين على مناطق من بيدهم السلطة الفعلية في البلاد ، عندئذ لا يمكننا أن نقبل بالشعارات لأنها لا تطعمنا خبزاً ولا تحمي أبناءنا من غوائل الدهر ..", "الامتيازات المارونية عبر التاريخ إن الذي رسخ ( عقدة الاستعلاء والفوقية ) في نفسية الموارنة هي تلكم الامتيازات التي كانت تمنح إليهم على فترات طويلة عبر التاريخ ، بحيث جعلتهم يفكرون ويخططون ويتصرفون وكأنهم أصحاب البلاد وأسيادها بدون منازع .. وفيما يلي مقتطفات من سجل الامتيازات نسوقها بين يدي الموضوع :", "- سنة ١٢٥٠ أرسل لويس التاسع رسالة شهيرة إلى موارنة لبنان قال فيها ( إننا موقنون أن هذه الأمة التي قامت تحت اسم القديس مارون هي جزء من الأمة الفرنسية ) .", "- سنة ١٦٤٩ أرسل لويس الرابع عشر رسالة إلى الطائفة المارونية يقول فيها ( ليكن معلوماً أننا بنصيحة من المملكة الوصية نضع تحت حمايتنا وبرعايتنا بطريرك ورعايا واكليروس المارونية المسيحية الذين يعيشون ويعملون في جبل لبنان ) .", "- سنة ١٨٦٠ وفي أعقاب المجازر التي قامت بين النصارى والدروز أرسل الجنرال ( بوفور ) قائد الحملة الفرنسية إلى لبنان - بالاتفاق مع الدولة العثمانية - كتاباً إلى فرنسا يقول فيه : ( أنصح بإقامة إمارة مسيحية في جبل لبنان وضم الساحل إليه وصيدا وبيروت وطرابلس ) . ولقد تحقق ذلك تقريباً في معاهدة سايكس بيكو .", "- وفي عام ١٩٤٣ عثر في أحد أديرة لبنان على منشور مكتوب باللغة الفرنسية موجه من فرنسا إلى الموارنة ويتضمن عشر وصايا هذه ترجمتها : من الدولة الأم إلى أبنائها المخلصين ..", "١ - قد رتبنا لكم أهم الأشياء التي تضمن لكم معيشة حسنة على هذه المنطقة ، مثل تمليك الأراضي والوكالات الأجنبية والوضع السياسي وشؤون النقد ، ويبقى عليكم أن تحافظوا على هذه المكاسب ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0023.png"}, {"n": 24, "paras": ["٢ - إن هذا الوطن لم يخلق إلا لكم ، حتى تجمعوا شملكم وتباشروا حريتكم بعد الحروب الأخيرة التاريخية . فاعلموا جيداً أن كلمة لبناني معناها مسيحي ، أما العرب الذين جاؤوا من الصحراء فيجب أن يعودوا إليها ..", "٣ - جاهدوا للسيطرة على المصايف وأمور السياحة وامتلاك ساحل البحر ، وأخرجوهم من قراهم كلما أصبحتم أغلبية ، ولا تنسوا تجهيز ميناء احتياطي في مدينة غير بيروت لا يكون فيها مسلمون وذلك عندما تسنح لكم الفرص .", "٤ - عليكم بأسباب القوة من رياضة وسلاح وتنظيمات للشباب ، واهتموا بالجيش وعليكم بكتمان أموركم .", "٥ - احرصوا على الزعامة الأبدية مثل نشر الكتب والسيطرة على النقابات والاتحادات ، ولا تعترفوا بأن تراث لغتكم وتاريخكم ملك للمسلمين ، وحاربوا ( بلا هوادة ) الأفكار والأشخاص الذين يعاكسون اتجاهاتكم .", "٦ - إن الاختلافات المذهبية بينكم يجب أن لا تخرج عن النظرة السطحية لأن حياتكم مرهونة باتحادكم أمام العدو الكافر من حيث أنكم أبناء يسوع الذي علمنا المحبة .", "٧ - ادرسوا دائماً مخططات الآخرين وتدخلوا معهم لكي تعرفوا ما عندهم ، ولا مانع للبعض من التظاهر بتأييدهم عند الضرورة ، ولكن على كل واحد منكم أن يبقى مرتبطاً برؤسائه وكنيسته ..", "٨ - ارفعوا شعائركم وكنائسكم في كل مكان مرتفع ، واعلموا بأن كل القوى الجبارة في العالم الحر تساعدكم وتقف لجانبكم في أسرع وقت . ولكن عليكم أن تتصرفوا كأنكم لا تعرفون ذلك .", "٩ - اجتهدوا بالتقرب من ملوك العرب ورؤسائهم بالخدمات الشخصية ، وهذا شيء سهل جداً ، ولكنه يفتح لكم مجالات واسعة للعمل ، ويدر عليكم أموالاً هائلة ونفوذاً أكبر ، حتى في البلدان المستعصية عليكم .", "١٠ - إن الجنسية اللبنانية شديدة الأهمية ، فدققوا كثيراً في ذلك ، واهتموا باخوانكم المغتربين والذين نزلوا عليكم من البلدان الأخرى ، لتحتفظوا بحقوق الأغلبية المقررة لكم ، وإلا ضاعت كل الجهود .", "كل ماروني جندي : وبتاريخ ٨ شباط ١٩٧٧ ألقى الأب بطرس ضو في كنيسة ( مار عبدا ) بعبدا ، محاضرة بمناسبة عيد مار مارون هذا نصها : توطدت أركان عهد المردة ، أو عهد الوطن القومي الماروني المستقل على دعائم قوة الموارنة الذاتية ، الروحية والعسكرية . استمد هذا العهد قوته من الأهداف التي وضعها الموارنة نصب أعينهم وأخصها حريتهم بكل أشكالها . الحرية الدينية والحرية الفكرية ، وحرية القول والعمل والعبادة وحرية الفلسفة والعلم والفن والحضارة .. حرية المثل العليا والقيم الإنسانية السامية . كان هدفهم انقاذ الحرية والحضارة في الشرق الأوسط من الطغيان ، ونظام القهر ، والظلم والتمييز والاستعباد ، والخراب والبداوة الهدامة .. فالحرية أساس الحضارة والكرامة الإنسانية . وكل نظام لا يقر حرية الآخرين هو نظام هدام للحضارة والكرامة الإنسانية . وعليه فإن وقفة الموارنة ، كانت انقاذًا للإنسان وحضارته وكرامته في هذه البقعة من العالم . هذه الأهداف والمثل العليا كانت قوة الموارنة ومنبع الهامهم ، ومصدر حماسهم واندفاعهم واستماتتهم في إنشاء وصيانة وطنهم القومي اللبناني . واعتمدوا أيضاً على قوتهم العسكرية .. الشعب الماروني خلاصة الشعب الآرامي والشعب الكنعاني والشعب الأموري الذي عرف ( بالمردة ) . كل هؤلاء وخاصة الأموريون المردة الذين منهم ( الجراجمة ) . كلهم اتصفوا بشموخ القامة ، وشدة البأس ، وقوة الشكيمة ، والمهارة في الحروب .."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0024.png"}, {"n": 25, "paras": ["أطلق الكتاب المقدس على الأموريين أجداد الموارنة اسم الجبابرة والعمالقة ، ووصفهم بأنهم مثل قامات الأرز قاماتهم ، وصلابتهم كالسنديان ، وألساورة العرب بالجبال شموخاً ، ودعوهم الحضارمة لمقدرتهم على العظائم ، والأساورة لبراعتهم في فن الحرب ، وبني الأحرار لعنفوانهم وعشقهم الحرية والاستقلال . وأشاد الكتاب المقدس بقوتهم العسكرية فقال : « إن مدنهم عظيمة ، وحصونهم تكاد تبلغ السماء ، واسمهم بالسريانية ( الجراجمة ) يعني الأبطال » . واشتهروا في الحروب بانقضاضهم الصاعق كالبرق ، وسرعتهم الخاطفة في التحرك والهجوم القاصم الساحق على العدو.", "هؤلاء هم الموارنة المردة . وكان كل واحد منهم كبيراً أو صغيراً أو امرأة جندياً بطلاً بارعاً ..", "أقاموا على كل تلة وقمة من وطنهم حصناً أو قلعة أو برجاً فشملوا الجبل كله بشبكة متماسكة من القلاع والحصون ، فكان لبنان كله من أقصاه إلى أقصاه كأنه حصن واحد متماسك لا يُقهر . ضمن هذا الوطن المنيع رصوا صفوفهم ، فكانوا كلهم كأنهم رجل واحد في الحرب والسلم مما جعل لهم سطوة عظيمة ..", "ونشطوا ضمن سياج وطنهم المنيع ، إلى تنظيم شؤونهم الروحية والدنيوية ، فرفعوا مستوى الأخلاق عالياً في قلب الشرق وفوق أعلى قممه . فكثر بينهم القديسون وازدهرت الفضائل ، وانصرفوا إلى نقب جبلهم فحولوه إلى فردوس مليء بالخيرات ونعموا بهناء لا مثيل له ، بينما كان الشرق يتخبط في الحروب والمحن ، وكافة أنواع الظلم والضيق والبؤس . وازدهرت علومهم وانفتحوا على الشرق والغرب ، وأنشأوا صداقات متينة مع الخلفاء المسلمين وأمبراطورية بيزنطيا والغرب معاً .", "ونعموا بأمان داخلي متين . وكان همهم خارجياً صد غارات الارسلانيين الذين أرسلهم الخلفاء المسلمون ليحاصروا الموارنة ، فحصل مناوشات بين الفريقين برهة . ولكن ما أن طال الأمر حتى استحكمت العلاقات الطيبة بين الارسلانيين والموارنة ..", "هذا كان عهد لبنان والموارنة الذهبي بدون شك ، خاصة إذا قابلناه بالعهود التي تلته .. تتميز العهود التي تعاقبت منذ تصدع الوطن الماروني بتوق مستمر متصاعد إلى تحقيق الاستقلال عن الدولة الاسلامية ، هذا التوق كان الحافز الأكبر الناهض بالموارنة نحو الحرية . وشاركهم به الدروز في عهد الإمارة ، فتحقق الاستقلال جزئياً وخاصة في زمن المير فخر الدين الثاني والأمير بشير شهاب الثاني .", "ولكن حلت بلبنان في عهد الإمارة فاجعتان : الأولى سقوط فخر الدين وما تلاه من الاضطهاد الفظيع الذي تعرض له اللبنانيون ، وخاصة الموارنة من قبل الدولة العثمانية . والثانية سقوط المير بشير الثاني وما تبعه من فتن داخلية ومذابح فظيعة ، وما سبقه من الحروب والتمزيق الذي حل بلبنان بسبب تنازعه بين محورين : محور الدولة المصرية من جهة ومحور الدولة العثمانية من جهة ثانية ، مع ما تخلل ذلك من مداخلات الدول الأوروبية ..", "وهاتان الفاجعتان أنزلتهما الدولة التركية بلبنان واللبنانيين بسبب توقهم إلى الاستقلال . وبين هاتين الفاجعتين كم حل باللبنانيين من ضروب الظلم والتعسف والاضطهاد والبؤس بسبب جور الدولة العثمانية واضطراب الحكم فيها .", "بالرغم من كل ذلك تمكن الموارنة في هذه الحقبة المظلمة من التفلت من الكابوس العثماني بقوة شكيمتهم وسجية انفتاحهم الحضاري ، فوثقوا ووسعوا الاتصالات مع العالم الغربي ومراكز الحضارة الإنسانية ، فلمع علماؤهم وفتحوا على الشرق أبواب الحضارة والعلم اللذين عرفوهما من منابع الغرب خاصة منذ تأسيس المدرسة المارونية في روما .", "فالانفتاح على الغرب واعتمادهم على قوتهم الذاتية العسكرية وتعاونهم مع"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0025.png"}, {"n": 26, "paras": ["بعض الأسر والعشائر وخاصة الدروز ، كل هذا مكن الموارنة من اجتياز مرحلة الظلم العثماني الذي خيم على الإمارة مدة طويلة .. كان مطلب اللبنانيين وعلى رأسهم البطريرك الحويك ومجلس الإدارة ، كان مطلب اللبنانيين ، عند نهاية الحرب الكونية الأولى وسقوط الدولة العثمانية ، وصيغة استقلال لبنان الناجز تحت إشراف وضمانة فرنسا وبمساعدتها . وسعى فيصل شريف مكة بدعم من بريطانيا لإنشاء امبراطورية عربية تخلف الامبراطورية العثمانية يرتبط لبنان بها ، ولكنه يتمتع ضمن إطارها باستقلال ذاتي ، ولكن وقوف الموارنة بقوة منع الحاق لبنان بعجلة الامبراطورية العربية التي على كل حال لم تتحقق آنذاك ..", "وفي ١٩٤٣ وضع الميثاق الوطني ، وكان من صميم الميثاق أن يبقى لبنان بمعزل عن التسلط العربي غير مرتبط بعجلة العروبة كما كان مرتبطاً « بعجلة العثمانية » وأن ينظم علاقاته مع الدول العربية ميثاق الجامعة العربية الذي شدد على احترام سيادة لبنان المطلقة ، كما شدد على ذلك البيان الوزاري الأول في عهد الاستقلال ..", "ولكن سرعان ما ضرب بالميثاق الوطني وبميثاق جامعة الدول العربية عرض الحائط ، وانصبت جهود العرب في الداخل والخارج على ابتلاع لبنان ، وجره وراءهم ، وتقييد سياسته الداخلية والخارجية وقطع المدد عنه من المصادر الدولية إلى غير ذلك ..", "وأثبتت الوقائع منذ (١٩٤٣) إلى الآن أن العروبة ليست أفضل من العثمانية على الإطلاق .", "بالواقع إن الدولة العربية الراشدية ، فالأموية ، فالعباسية ، والدولة الأيوبية ، والدولة المملوكية ، والدولة العثمانية ، ومجموعة الدول العربية حالياً هي كلها أشكال متنوعة ومتعاقبة لجوهر واحد هو الحكم الإسلامي ..", "وليس العرب أفضل من الأتراك في حكم الشعوب ، إذ أن تصنيف الناس إلى مسلمين وأهل ذمة ومؤمنين وكفار ليس من وضع الأتراك .. الأتراك طبقوا شرائع وضعها العرب . فالعرب هم الأصل والأتراك فرع . المدرسة عربية والتلامذة أتراك أو مماليك . وليست الحال اليوم أفضل منها في الماضي ، لأن هذه الشرائع تعتبر بنظر أصحابها ( منزلة ) ومن أصل ( إلهي ) لا يجوز تبديل حرف واحد منها .", "والذين محقوا ( الدامور والمتين وعينطورة وترشيش وغيرها ) من العرب ، فعلوا ذلك باسم العروبة ، وتحت شعار ( الله أكبر ) وأمعنوا في التنكيل أكثر مما فعله الأتراك طوال ٤٠٠ سنة ..", "حاولوا فرض العثمانية ، والآن يحاولون فرض العروبة كهوية على شعب يتمسك بهويته الأصيلة ويرفض هوية غريبة تفرض عليه بالإكراه ..", "والإصرار على إلغاء الطائفية من جهة وعلى العروبة من جهة ثانية إن هو إلا طائفية باتجاه واحد ، إذ ليست العروبة سوى لون من الطائفية كما هو ثابت من أنظمة الدول العربية كلها بدون إستثناء . وأن يتمسك شعب بهويته وحريته واستقلاله لا يجب اعتباره عداء لأحد ، ولكن حق مقدس تقره شرعة حقوق الإنسان وحق تقرير المصير . ومن الأمور النادرة في التاريخ والمستغربة أن يحاول شعب فرض هويته على شعب آخر ..", "ومن المقابلة بين مختلف العهود التي اختبرها الموارنة طوال ١٣٠٠ سنة ، يتضح أن عهد الوطن القومي الماروني المستقل عن الدولة الإسلامية كانت أم غير عربية هو العهد الذهبي الأمثل ..", "المستقبل مثلما أن العلة الأساسية في الماضي منذ فقد الموارنة استقلالهم في عهد المماليك ،"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0026.png"}, {"n": 27, "paras": ["كانت ارتباط لبنان ( وطن الموارنة ) بالدولة الإسلامية المملوكية فالعثمانية ، هكذا اليوم ، العلة الأساسية هي ارتباط لبنان بالمجموعة العربية والسياسة العربية . هذا الارتباط أفرغ لبنان من استقلاله الحقيقي ، وحرمه حرية التصرف داخلياً وخارجياً ، وعرقل مسيرته في طريق التقدم والرقي والازدهار الاقتصادي والحضاري . ومما يجعل الوضع أكثر صعوبة وتعقيداً كون المسلمين في داخل لبنان يؤلفون مع المسلمين في الخارج وخاصة في الدول العربية أمة واحدة ووطناً واحداً .. فعبثاً تعقد الاتفاقات والمواثيق معهم . إنهم لا يعترفون بلبنان ( وطناً مستقلاً ) نهائياً ، ولكنهم يعتبرونه جزءاً من وطن أكبر هو الوطن العربي .. فيجب أن يكون هدفنا إعادة استقلالنا التام الناجز عن الدولة الإسلامية الممثلة الآن في العروبة أو المجموعة العربية ، وذلك :", "١ - بالتمسك بما لنا من سلطات ، وخاصة رئاسة الجمهورية التي أرادها الميثاق الوطني ضمانة لاستقلال لبنان .. إنها ضمانة وطنية لاستقلال لبنان الذي أراده الميثاق الوطني مستقلاً ( عن الشرق والغرب معاً ) اتفق على أن يتولى الموارنة الرئاسة الأولى كضمانة لاستقلال لبنان ضد طغيان الأكثرية العربية . فاختصاص الرئاسة الأولى بالموارنة له طابع وطني لا طائفي ، وغايته تعزيز استقلال لبنان وديمومة هذا الاستقلال .. في الواقع ، يمكن التأكيد أن خطر الطغيان العربي من الخارج والشارع الإسلامي من الداخل لم يزل منذ وضعت الضمانة ، ولم ينقص بل زاد وتعاظم مما يتوجب التمسك أكثر بالضمانات ودعمها بقوى فاعلة ذاتية داخلية ، وخارجية عربية ودولية .. وما تأكيد المسلمين أكثر فأكثر على عروبة لبنان .. وتلاحمهم مع الفلسطينيين الغرباء لدك سيادة لبنان وتعريبه ، وابدال نظامه الذاتي المستقل بنظام يحكم السيطرة العربية عليه ، إلا الدليل المحسوس على حقيقة وتزايد الخطر الذي لأجله وضعت الضمانة المذكورة .", "٢ - مارونية الرئاسة الأولى ضمانة لا للكيان اللبناني فحسب ولكن للوجود المسيحي والماروني أيضاً ..", "٣ - عندما اتفق واضعوا الميثاق الوطني على تخصيص الرئاسة الأولى بالموارنة ، كان القصد من ذلك توفير ضمانة للموارنة تؤمن لهم الاطمئنان على أرواحهم وممتلكاتهم ، وتقوم في ذلك مقام الانتداب والحماية الغربية . والأخطار التي استعين عليها بالحماية الغربية والانتداب لا تزال قائمة ولا يتوقع زوالها في المستقبل المنظور وذلك لأسباب كثيرة منها :", "- إن العروبة تعني - لا نظرياً ولكن واقعياً - الإسلام . ففي دساتير كل الدول العربية ، دين الدولة الإسلام ، وليس هناك أي اتجاه للتخلي عن هذا الارتباط بين الدين الإسلامي والدولة العربية .", "- إن الإسلام يميز بين المسلم والذمي على الصعيد السياسي والمدني والاجتماعي .. والذمي لا حق له بالحياة أصلاً .. ولكن يسمح له بالاحتفاظ بالحياة لقاء الجزية . والحقوق التي تقرها شرعة حقوق الإنسان وكل دساتير الأرض لا يقرها الشرع الإسلامي للذمي كما هو معروف ، وخاصة حرية الضمير والعبادة وغير ذلك مما يطول شرحه (١) ..", "- وهذا التمييز بين المسلم والذمي أو المؤمن والكافر ، مع ما يتبعه من الطبقية والحرمان الذي أشرنا إليه بالنسبة للذمي نابع - لا من أنظمة وقوانين بشرية المصدر - يمكن اصلاحها وتعديلها ، ولكن من نصوص قرآنية لها قدسية الوحي بنظر المسلمين ، ولا يجوز مسها بأي شكل من الأشكال . هذا التشريع - الهي", "(١) اقرأ الرد على هذا الكلام في مكان آخر من هذا الكتاب ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0027.png"}, {"n": 28, "paras": ["الأصل - حسب اعتقادهم ، أدى على ممر الأجيال إلى تصفية المسيحيين في البلدان التي تغلب عليها العرب والدول الإسلامية ، كآسيا الصغرى والعراق ومصر وإفريقيا الشمالية وغيرها . ومن خطط شطر كبير من العرب والمسلمين في الوقت الحاضر تصفية المسيحيين في لبنان ، وخاصة الموارنة . والأحداث الأخيرة دلالة محسوسة واضحة على ذلك . وجرت محاولات كثيرة في الماضي بهذا الصدد .", "أما القول أن الظروف تغيرت ، والعقول تطورت فهذا يكذبه الواقع والأحداث التي نشهدها الآن ، والخطط المعلنة وغير المعلنة والتيارات التعصبية التي تجتاح العالم الإسلامي والعربي ...", "فليس من الحكمة والمسؤولية التخلي عن الضمانات التي بيدنا لنلقي بأنفسنا وبالشعب الموكول إلينا والتراث والرسالة في خضم المجهول ، تحت رحمة السين الإسلامي ..", "يجب التمسك بما لدينا من ضمانات والعمل على الاستزادة منها على صعيد القوة الذاتية والعلاقات العربية والدولية ..", "الاعتراضات على مارونية رئيس الجمهورية", "إن لبنان بفضل نظامه هذا ذي الرأس المسيحي ، أكثر تطوراً من كل البلدان العربية والإسلامية ، وأكثر ازدهاراً وأرفع مستوى من الناحية الثقافية والحضارية والاجتماعية والاقتصادية من أي منها ، مع العلم أنه أفقرها جميعاً من حيث الموارد الأرضية الطبيعية . وإبدال النظام ذي الرأس المسيحي بنظام إسلامي من شأنه أن يعيد البلاد إلى الوراء ..", "والنظام المسيحي هو لا طائفي وعلماني بالواقع ، لأنه مستوحى من الانجيل ، والإنجيل لا يميز في التعامل بين الناس ، بين مؤمن وكافر وقريب وعدو ، بينما هذا التمييز من صميم الدين الإسلامي ..", "والروح المسيحية بنيت على العدل والمحبة والمساواة ومنها انبثقت التشريعات الإنسانية المعاصرة كالدستور الإفرنسي والأميركي وشرعة الأمم المتحدة وشرعة حقوق الإنسان وغيرها . فلا يمكن التعبير عن العلمانية بآية أوضح من هذه (أعطوا ما لقيصر لقيصر وما لله لله) و(أحبوا أعداءكم وأحسنوا إلى من يبغضكم ويضطهدكم) .", "وبالواقع إن النظام اللبناني ذا الرأس المسيحي كانت منافعه للمسلمين أكثر منها للمسيحيين كما يتضح ذلك من وقائع جمة . فوازنة الدولة يغذي أغلبية مواردها المسيحيون بينما تنفق أكثريتها على المسلمين (١) ..", "وماذا في حال تصلب الفريق الإسلامي ومطالبته بالتغيير ..", "لا يجب في هذه الحالة التراخي على الإطلاق .. فالمسلمون يتبعون مخططاً هدفه تعريب لبنان واسلمته .. وهو بنظرهم لا يكون وطناً مستقلاً إلى أن يذوب تماماً في الوطن العربي الإسلامي الشامل .", "والصمود أمام هذا الرمل المتحرك ، والتمسك بالميثاق هو الحل الحكيم الأوحد ، والتزحزح هو الخطأ ، لأنك إذا أعطيت المسلمين اليوم شبراً يطالبون غداً بمتر ..", "خمس ملاحظات :", "١ - فضلاً عن تخصيص الرئاسة الأولى بالموارنة في الميثاق المتفق عليه سنة ١٩٤٣ فإن الرئاسة حق مكتسب للموارنة منذ الفتح العربي وعهد المردة - أي الموارنة الأولين - بموجب مواثيق مع الخلفاء المسلمين ، حتى المتصرفية - إذ كان المتصرف مسيحياً كاثوليكياً - مروراً بعهد الأميرين اللذين كانا مارونيين أي فخر الدين وبشير الكبير ..", "(١) هذا الكلام مغلوط بالكلية وغير صحيح ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0028.png"}, {"n": 29, "paras": ["٢ - التمسك بالقضية والحق الأساسي - أي الرئاسة - لا يعني العنف أو الفظاظة بالأسلوب .. يجب اعتماد القدر الأكبر من اللباقة والنعومة والحكمة والإقناع واللطف في الأسلوب عند المجاهرة بهذا الحق والتمسك به دون ضعف ..", "٣ - يجب أن يكون الهدف مع التمسك بالرئاسة - كحق للموارنة - العمل الحثيث على لبننة الفريق العروبي غير المؤمن بلبنان ، كما فعل أجدادنا مع العشائر التي أرسلت من قبل الخلفاء والدول الإسلامية إلى لبنان للقضاء على استقلاله وعلى المسيحية فيه مثل بني ارسلان وأبي اللمع وتلحوق وعبد الله وعماد وحرفوش وحمادة وغيرهم منذ القرن الثامن عشر .. فهؤلاء بعد أن ناصبوا الموارنة العداء قروناً طويلة ، تمورنوا أو تلبننوا أي اندمجوا في العقيدة والولاء اللبناني .", "والعمل على لبننة الفريق الآخر يكون خاصة بالاصلاحات الجذرية في الإدارة ، من حيث تطهيرها من الرشوة والفساد والكسل وسائر الآفات . وفي المجال الاجتماعي برفع مستوى المعيشة والرفاهية للطبقات الفقيرة ، وتلبية حاجات الشعب في الطب والعمل والخدمات الاجتماعية ، وفي المجال الاقتصادي والأخلاقي والثقافي بتربية العقيدة اللبنانية في النشء والشبيبة خاصة في مدارسنا الخاصة . وفي المجال الثقافي لا بد من التنويه بفصل الآداب اللبنانية والفلسفة اللبنانية والفنون وسائر فروع الحضارة عن الآداب والفلسفة العربية . وتدريس الآداب اللبنانية والفلسفة وما يليها مستقلة في مدارسنا المارونية عن الآداب والفلسفة العربية ، لانماء روح الولاء الوطني ، والتربية الوطنية .. ويمكن تدريس الآداب العربية كغيرها من الآداب الأجنبية مثلاً ..", "٤ - التذكير بأنه إذا افترضنا جدلاً أن المسيحيين أصبحوا أقلية في لبنان بالنسبة إلى المسلمين - الأمر الذي يبدو أن المعلومات الاحصائية تدحضه - فالرئاسة الأولى التي اتفق أن تكون ضمانة للمسيحيين عندما كان هؤلاء أكثرية ، يجب ومن باب أولى أن تبقى لهم وتعزز بضمانات جديدة في حال يصبح هؤلاء أقلية .", "٥ - إذا كان الذين ينادون باللاطائفية السياسية صادقين فلماذا لا يبدأون بالمناداة باللاطائفية السياسية في سائر البلدان العربية والإسلامية - حيث يشددون ويقيمون الثورات لينص الدستور على أن يكون دين الدولة الإسلام - لماذا الطائفية بنظرهم مدعاة للتخلف واللاديمقراطية في لبنان ، بينما هي ملازمة للتقدم والديمقراطية في سائر البلدان العربية والإسلامية . بالواقع إن المناداة باللاطائفية في لبنان من وحي طائفي محض وغايتها انتزاع السلطة من الموارنة لتعريب لبنان واسلمته . فالخطة تدريجية ، وتقوم بتصفية حقوق المسيحيين أولاً وأهمها الرئاسة الأولى ، ثم تصفية المسيحية والمسيحيين بالابادة (١) .", "كسب الرأي العام الدولي والعالمي : قبل كل شيء يجب التخلص من الوهم المسيطر على بعض العقول ، والموحي بأن قضيتنا خاسرة حتماً على الصعيد الدولي والعالمي ، لأن مصالح الدول مرتبطة بنفط العرب ولا نفط عندنا . لتبديد هذا الوهم يجب أن نأخذ بعين الاعتبار بعض الحقائق : من العوامل الرئيسية في العلاقات الدولية الصداقة ، وقوة الحق إذا ظهرت بوضوح ومنطق ، والقوة الذاتية في المجال العسكري ، والمصالح .", "- الصداقة : بين موارنة لبنان والدول الكبرى خاصة فرنسا والولايات المتحدة صداقة راسخة الجذور .", "(١) كلام تدحضه الوقائع التاريخية ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0029.png"}, {"n": 30, "paras": ["أما مع الولايات المتحدة فصداقتنا متينة خاصة بسبب المهاجرين من الموارنة ، ولكن يجب أن نكون من هؤلاء المغتربين أداة فعالة لترسيخ هذه الصداقة بتمتين الروابط بينهم وبين الوطن الأم وتنظيمها .", "وما ينطبق على دور المهاجرين الموارنة في الولايات المتحدة من حيث تمكين الصداقة بيننا وبين هذه الدولة الكبرى ينطبق على المهاجرين في كل أقطار العالم وخاصة في الدول اللاتينية الأمريكية .", "قوة الحق : النظام السائد في الدول الإسلامية والعربية هو نظام ثيوقراطي إسلامي لا ديمقراطي ، والنظام الثيوقراطي قائم على التمييز بين المسلم وغير المسلم وما يتبع ذلك من اضطهاد وظلم صامت أحياناً وصارخ أحياناً أخرى . وتقصي الحقائق بصورة موضوعية يبين كم هو بالغ الاجحاف بحقوق المسيحيين وكرامتهم في الدول العربية والإسلامية . فهم مواطنون من الدرجة الثانية وبالأحرى ليسوا معتبرين كمواطنين . يمارس ضدهم التمييز في الوظائف والأشغال والمدارس وسائر المرافق العامة . والمضايقات مستمرة . وهذا ينطبق على الدول الإسلامية العلمانية كتركيا وغير العلمانية . وإجراء التحقيق والإحصاء بهذا الموضوع يثبت ذلك .", "فلبنان هو في الشرق المعقل الوحيد للديمقراطية بسبب نظامه ذي الرأس المسيحي والأسس المسيحية . وتغيير هذا النظام هو تحطيم لأحد أهم مراكز الديمقراطية في العالم وخاصة في العالم الثالث المتخلف . هذا ما يجب بيانه وإبرازه بالوقائع للعالم الحر وللأمم المتحدة وغيرها .", "القوة الفكرية هي من أقوى المؤثرات في العلاقات الدولية : القوة الذاتية العسكرية : قوة الحق لا يمكن أن تأخذ المكانة اللائقة بها في العالم ما لم تدعمها القوة الذاتية العسكرية . لا يجب في هذا الموضوع أن نهمل الدفاع عن أنفسنا بسبب الاتكال على الحماية الأجنبية . التاريخ يثبت ذلك بصورة قاطعة . وفي الأحداث الأخيرة لو لم نصمد ونحسن الدفاع عن أنفسنا لما كان تحرك العالم العربي لصالحنا في مؤتمري الرياض والقاهرة . لو كان سحقنا الفلسطينيون والأعداء لما كان سأل عنا أحد على الإطلاق لا في الغرب ولا في الشرق ولكنا الآن في خبر كان . القوة العسكرية ضرورية لكسب احترام الناس وللاستمرار في الوجود . كانت سوريا والعراق ومصر وآسيا الصغرى كلها مسيحية وكانت المسيحية على غاية الازدهار فيها . ولكن لأن هذه الشعوب لم تحسن الدفاع عن نفسها واتكلت في ذلك على الدولة البيزنطية فإنها انهارت حالاً أمام الاجتياح الإسلامي وانقرضت المسيحية والمسيحيون فيها مع أنها مهد المسيحية .", "ولحيازة قوة عسكرية ذاتية تمكننا من الاحتفاظ باستقلالنا وحقوقنا وكرامتنا يجب العودة إلى شعار الآباء والجدود في عهد المردة والوطن الماروني . وهذا الشعار هو « كل ماروني جندي » .", "بالواقع كان كل ماروني من سن ١٥ حتى يبلغ السبعين من العمر جندياً مدرباً مثل أحسن جندي في الجيوش الأوروبية كما تقول تقارير القناصل الأوروبيين .", "وبالإضافة إلى التدريب البشري ، يجب وضع خطة شاملة أو استراتيجية كاملة تشمل الجبل اللبناني الماروني كله بشبكة من التحصينات والتجهيزات العسكرية ، كما كانت الحال ، أيضاً ، في عهد الوطن الماروني المستقل . من النادر أن تجد قرية مارونية ليس فيها محل يدعى الحصن أو القلعة أو البرج . الكنائس والأديار كانت حصوناً تبنى بشكل قلاع فيها الاستحكامات والمرامي والجدران الضخمة والأبواب الحصينة . يجب أن يعود الجبل كله كأنه حصن واحد منيع مجهز بأحسن الوسائل الحربية . هذا طبعاً يتطلب جهوداً وأموالاً ولكنه ليس مستحيلاً نظراً لطاقات المقيمين والمغتربين والصداقات الدولية . والتنفيذ يتم بموجب خطة طويلة المدى ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0030.png"}, {"n": 31, "paras": ["والاعتماد في ذلك على الجبهة والقوات اللبنانية إذا توسعت بحيث تضم كل الموارنة وفقاً للشعار « كل ماروني جندي » .", "- على الصعيد الدولي العالمي : يجب أن تنصب جهود الكنيسة في الشرق عامة والكنيسة المارونية خاصة ، على أن يبقى لبنان معقل الديموقراطية والحرية والإنسانية في هذه البقعة من العالم ببقاء نظامه ذي الرأس المسيحي وذي الأسس المسيحية وذلك صيانة للحقوق والحريات والكرامة الإنسانية فحسب ، ولكن للوجود المسيحي ذاته والرسالة المسيحية . فلبنان بنظامه المشار إليه حصن وملجأ المسيحية في الشرق وبانهيار نظامه تنهار المسيحية ذاتها .", "وكانت الكنيسة المارونية ولا تزال بنظر العالم الحر تعتبر المركز الرئيسي والدعامة الكبرى للبنان ومن ثم للديموقراطية والحرية في هذا المقلب من العالم . ولكن يجب ترميم نفوذ وعلاقات الكنيسة المارونية لدى الدول الغربية الكبرى ولا سيما فرنسا وأمريكا وغيرها ، ولدى المؤسسات الدولية الكبرى وخاصة الأمم المتحدة بإنشاء علاقات منتظمة مع هذه الدول والمؤسسات سواء بالاتصال المباشر وسواء بواسطة الفاتيكان والكنائس المسيحية المنتشرة في العالم وخاصة فرنسا والولايات المتحدة وذلك عن طريقة الصداقات الشخصية والبعثات والمراسلات وسائر أنواع الاتصال ، وسواء بواسطة المغتربين الموارنة والمسيحيين المخلصين للبنان .", "ولا بد لأجل ذلك من أن تكون لدى الكنيسة المارونية خطة مدروسة تشمل السياسة الخارجية والداخلية ، وخطة متماسكة ومستمرة لا تزول وتتغير بزوال الأشخاص ، ولكن تبقى مستمرة وفاعلة في جوهرها مع ما يلزم من التطور والتكييف . ولدى الكنيسة المارونية من الوثائق والأرشيف ما يساعدها على وضع هذه الخطة المتكاملة . وللكنيسة المارونية في هذا الموضوع فضلاً عن وثائق أرشيفها واختباراتها على مدى العصور مجموعات المهاجرين الموارنة الذين يمكن الاستعانة بهم كقوة عالمية .", "وعندما تكتمل هذه الخطة الشاملة المتكاملة البعيدة المدى مستقبلاً والمستوحاة من تراثنا الماروني اللبناني العميق الجذور ، يمكن عندئذ جمع الأسرة المارونية حول هذه الخطة المدروسة ورص الصفوف تحت رايتها . وهذا دور فريد للكنيسة المارونية لا يمكن لأية هيئة أخرى القيام به . ومن الضروري ، أيضاً ، النهوض بالرسالة المارونية إلى سابق ازدهارها ومجدها في الأزمان الغابرة .", "٢ - التناقض في الانتماء الحزبي والسياسي والمجتمع اللبناني على ضيقه وصغره يموج بعشرات الاتجاهات والأحزاب والقوى والمنظمات والولاءات والانتماءات الحزبية والسياسية اللبنانية والعربية والعالمية .. ففي لبنان يمين ويسار .. يمين من كل الألوان ، ويسار من كل الأصناف ..", "- فيه صراع بين الرأسمالية والشيوعية .", "- وفيه صراع بين الشيوعية والإسلام .", "- وفيه صراع بين القومية والشعوبية والأممية .", "- وفيه صراع بين التقدمية والرجعية .", "- وفيه صراع بين الأحزاب الزعامية والأحزاب العقائدية .", "- وفيه صراع بين النظرة اللبنانية والنظرة العربية .", "- وفيه صراع بين القوى اليمينية نفسها كما أن فيه صراعاً بين التنظيمات اليسارية كذلك .", "وهذا ما جعل ولاء اللبناني لغير لبنان ابتداءً .. وهذا ما جعل الدولة غير قادرة على بسط نفوذها على اللبنانيين ، لأنها - أي الدولة - نفسها كتلة من ٦١"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0031.png"}, {"n": 32, "paras": ["المتناقضات لا تكاد تتجمع حتى تتصدع ، ولا تلبث أن تقوم حتى تهوي وتسقط ..", "٣ - التناقض الاقتصادي يضاف إلى الخلفيات الكامنة وراء الأزمات اللبنانية المتلاحقة خلفية لا تقل عن غيرها أثراً .. ذلكم هو التناقض الاقتصادي الملحوظ في المجتمع اللبناني .. ففي لبنان تناقض اقتصادي عام ، وتناقض اقتصادي بين الطوائف نفسها .. ولما كانت الطائفة المارونية ذات امتيازات سياسية خاصة ، فقد أتاح لها ذلك أن تصبح ذات امتيازات اقتصادية كذلك .. جاء في مجلة ( المجتمع ) الكويتية العدد ٢٨٤ تاريخ ٢٧ كانون الثاني ١٩٧٦ ما يلي : ( ولنعد إلى ما سلكه الصليبيون في لبنان من تخطيط للسيطرة على الاقتصاد في لبنان ، حسب رغبة اخوانهم الفرنسيين التي جاءت في الوصايا العشر .. وإذا كان الناس في عصرنا يرغبون بلغة الأرقام فهاكم جدولاً لمجموعة من نصارى لبنان وما يملكون ونوعية هذه الشركات :", "١ - جوزيف شادر : عضو المكتب السياسي لحزب الكتائب اللبنانية ، ونائب الأرمن الكاثوليك عن دائرة بيروت الأولى ، وهو محام لعدة شركات منها :", "- شركة ( كوبان ترايدنغ ) تعمل في كوبا ..", "- هو عضو مجلس إدارة ( شركة لبنان العقارية ) وهي تعمل في المضاربة العقارية ..", "- ويتعاطى شادر تجارة السلاح بعد أن حاز على وسام إيراني من درجة عالية . وقد جنى في الفترة الأخيرة مع بعض التجار الآخرين في المكتب السياسي أموالاً ضخمة في حملة التسليح التي جرت في لبنان ..", "- وهو رئيس اللجنة البرلمانية المالية ، وأحد كبار المدافعين من بين أركان ( الكتائب ) عن مشروع ضمان الرساميل الأجنبية ..", "٢ - انطوان جزار : محام وعضو المكتب السياسي لحزب ( الكتائب اللبنانية ) .", "- رئيس مجلس إدارة ( شركة الخطوط البحرية للشرق الأوسط ) ، وهي شركة تعمل في النقل البحري ..", "- عضو مجلس إدارة ( شركة أورباكو ) العقارية التي تتعاطى المضاربة بالأراضي وعمليات الرهن والسمسرة واستيراد المواد الخام للبناء ..", "- عضو مجلس إدارة ( شركة جاك منهاسي ) وهي شركة وكالات تجارية مؤسسوها من الفرنسيين والألمان ..", "- عضو مجلس إدارة ( شركة انفستور أوفرسيز سرفيس ) فرع الشرق الأوسط . وهي شركة أميركية تمثل مصالح عدة شركات احتكارية مالية ..", "- عضو مجلس إدارة ( محلات لويس صباغ ) وهي تهتم بالتجارة والوكالات وخاصة البحرية منها ..", "٣ - انطوان خليفة : عضو مجلس بلدية بيروت ..", "- شريك في شركة ( ميتس للشرق الأوسط المحدودة ) وهي شركة مقاولات بناء وخدمات ..", "- عضو ومحام في شركة التأمين ( اندريا انشورنس كومباني ) ..", "- أمين الصندوق سابقاً في حزب الكتائب ..", "- صاحب مطبعة خليفة ..", "- مدير وشريك في الشركة الألكترونية للطباعة والتجارة ..", "٤ - بطرس الخوري وأولاده :", "- سليم بطرس الخوري شريك ادمون رزق في مستودعات التبريد في بكفيا .."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0032.png"}, {"n": 33, "paras": ["- صهر بطرس الخوري ( يوسف ضاهر ) المسؤول عن الكتائب في محافظة لبنان الشمالي ويجري بواسطته تمويل حزب الكتائب ..", "- بطرس الخوري شريك جان سكاف في معمل السكر ..", "- خليل بطرس الخوري شريك إلياس ربابي في بنك بيبلوس ..", "- يملك بطرس الخوري وأولاده مع شركائهم الشركات التالية : الشركة اللبنانية لتكرير السكر . مصرف التسليف الزراعي والصناعي والعقاري . شركة قاديشا لكهرباء لبنان الشمالي . بنك لبنان والمهجر . شركة زيوت أسعد جبر . شركة مصنع السكر في لبنان . بنك الصناعة والعمل . شركة كنسروة لبنان . الشركة الصناعية للشرق . مئات الأسهم في شركة الترابة اللبنانية . الشركة اللبنانية للتأمين . بنك بيبلوس . شركة مستودعات التبريد في بكفيا . شركة نقل الطاقة الكهربائية . شركة كهرباء البارد . ايتون امبورت اكسبورت . شركة انتركوت . شركة الخشب المضغوط للبناء . شركة الحديد اللبنانية . شركة الفنادق العصرية .", "ه - جورج أبو عضل : شريك انطوان جزار في شركة الفن التقني .", "- رئيس نقابة أرباب العمل الجديدة التي يشغل كريم بقرادوني أمين سرها الإداري .", "- من كبار مستوردي الأدوية ..", "- يملك محلات جورج أبو عضل وشركاه لاستيراد الأدوية وأدوات التجميل والساعات والولاعات والسجاير .", "- الشركة الدولية لصنع أدوات التجميل .", "- الشركة اللبنانية للإنماء الزراعي ( سوليدار ) .", "- شركة توزيع المستحضرات الصيدلية .", "- شركة تأمينات الشرق .", "- شركة انتر بودو للأدوات المكتبية .", "- الشركة العامة للمنتوجات الغذائية .", "- شركة المنشورات الشرقية وتصدر عنها مجلة ( ماغازين ) بالفرنسية ، والأسبوع العربي .", "- الوكالة الشرقية للدعاية والريبورتاج المصور .", "- شركة ميدل إيست ميديا .", "- الشركة اللبنانية الحديثة للملبوسات .", "- شركة انترناشيونال براندس .", "- الشركة اللبنانية لتوزيع الصحف والمطبوعات .", "- شركة مخازن ( اى . ب . رقم ٨ ) .", "٦ - آل الصباغ : وهؤلاء هم شركاء انطوان جزار في شركات عديدة ويملكون الشركات التالية :", "- الخطوط البحرية للشرق الأوسط .", "- محلات لويس صباغ .", "- شركة نقل الفحم الحجري البحرية .", "- شركات أوفر سيز للملاحة البحرية .", "- شركة لا بريفيدانس للملاحة البحرية .", "- شركة تأمين تورينو المغفلة .", "٧ - آل صحناوي : وهؤلاء على علاقة وثيقة مع الكتائب اللبنانية ، وفي طليعتهم أنطوان صحناوي الذي كان مرشحاً للانتخابات في لوائح الحزب التي قام بتمويلها ، وهو يملك مع شركائه الشركات التالية :", "- البنك البلجيكي اللبناني .", "- الشركة الوطنية للأنابيب .", "- مئات الأسهم مع شركة الترابة اللبنانية وشركة اترنيت ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0033.png"}, {"n": 34, "paras": ["- كتانة ( الفرد وهنري )", "- شركاء ادمون رزق في شركة مستودعات التبريد في بكفيا ويملكون الشركات التالية :", "- شركة كوماتسو أوفرسيز كومباني", "- الشركة اللبنانية للمكائن والتجهيزات", "- شركة الملاحة البحرية اللبنانية", "- شركة الفنادق السياحية في لبنان", "- شركة جل الديب للتنمية", "- شركة كبريت الشرق", "- شركة كهرباء البارد", "- بنك بيروت يونيفرسال", "- شركة الإنتاج اللبناني", "- شركة نقل الطاقة الكهربائية", "- شركة الدهمية", "- شركة التوزيع الشرقية", "- محلات فرنسيس وألفرد كتانة", "- الشركة العقارية للفرز والبناء وبعد فهذه نماذج تدل على مدى سيطرة نصارى لبنان على الاقتصاد اللبناني جاءت على سبيل المثال لا الحصر وهذا غيض من فيض من الواقع", "٤ - التناقضات العربية ولبنان - المسرح المفتوح دائماً - للصراعات العربية وتناقضاتها .. فيه تتجسد التناقضات الأيديولوجية والسياسية ، وإليه تنتقل صراعات النظم القريبة والبعيدة ، بعداواتها وتشنجاتها وأحياناً باغتيالاتها وتصفياتها الدموية .. فإلى أعماقه يمكن أن تمتد أية يد لتزرع الخراب والدمار حتى في وضح النهار .. وإلى أية مؤسسة يمكن أن تصل أصابع النسف والتخريب .. وعلى أي مواطن أو لاجئ أو ضيف يمكن أن يطلق الرصاص ويحكم بالموت .. وهذا ما جعل الكيان اللبناني في اهتزاز دائم تبعاً لانعكاس ما يجري هنا وهناك وهنالك ..", "- فالصراع بين أنظمة الحكم المختلفة انعكس عليه", "- والصراع بين الثوريين والرجعيين انعكس عليه", "- والصراع بين الناصريين وأعدائهم انعكس عليه", "- والصراع بين الأحزاب العربية انعكس عليه", "٥ - التناقض الدولي والقضية الفلسطينية إذا كانت صراعات العرب تنعكس على الوضع اللبناني كان من الطبيعي أن يكون انعكاس ( القضية الفلسطينية ) عليه أشد وأكبر .. فالدول الكبرى - على اختلاف الأدوار السياسية التي تمثلها - ومن ورائها إسرائيل تعمل جاهدة على إيجاد حل ينهي القضية الفلسطينية لمصلحة الوجود الإسرائيلي ولمصلحة الصهيونية العالمية .. هذا الحل بات مرتهناً بتصفية ظاهرة العمل العسكري المسلح للفلسطينيين أي ( المقاومة ) .. ولم تكن حوادث ( أيلول الأسود ) في الأردن إلا مؤشراً على هذه الغاية المبيتة لضرب وتصفية الروح الجهادية المتمثلة بالعمل الفدائي .. ولبنان .. اختير كمسرح نهائي لهذه المؤامرة وكمخندق أخير للمقاومة .."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0034.png"}, {"n": 35, "paras": ["لقد حيكت خيوط المؤامرة بمكر ودهاء بقصد لتجميع قوى المقاومة الفلسطينية في لبنان تمهيداً لاستنزافها وتصفيتها .. وكانت الميليشيات اليمينية الطائفية المنفذ لهذه الاستراتيجية الماكرة .. وإسرائيل ، كانت تعتمد بشكل رئيسي على لبنان وعلى الفوقية والامتيازات التي يتمتع بها النصارى بشكل عام والموارنة بشكل خاص .. جاء في يوميات ( بن جوريون ) اليومية ٢١ مايو : ( أن نقطة الضعف في التحالف العربي هو لبنان ، وأن نفوذ المسلمين يمكن اسقاطه بسهولة ، ثم تقوم هناك دولة مسيحية تنتهي حدودها عند نهر الليطاني ، وتتحالف مع إسرائيل ) . وبتاريخ ١٢ / ٤ / ١٩٧٥ سئل رئيس وزراء إسرائيل في الكنيست : لماذا لم تردوا على عملية ( سافوي ) فأجاب : ( إذا رددنا على الفدائيين الفلسطينيين فسوف نخلق ردة فعل في لبنان ، ولكننا سنترك المهمة لعناصر لبنانية من داخل لبنان ) . من هنا يمكن اعتبار ( القضية الفلسطينية ) وما يُعد لها في مطابخ الاستعمار ، وما ترتب عليها من خطوات خيانية في ( كامب دايفيد ) الفتيل الصاعق الذي فجر الأزمة اللبنانية ، ولا يزال يفجرها حتى كتابة هذه السطور .. أنه مما لا شك فيه أن حل القضية اللبنانية قد ارتهن محلياً وعربياً ودولياً بحل القضية الفلسطينية وإلى أمد قد يطول ولا يقصر ..", "حجم الحرب اللبنانية", "حجم الحرب اللبنانية ٧٥ - ٧٦ لقد فاقت الحرب اللبنانية في ضراوتها وشراستها كل الحروب .. ولم يبق في معاجم الحروب والمذابح زيادة لمستزيد في فن القتل وسفك الدماء وتشويه الجثث واحراق الأحياء وتقطيع الأوصال إلا وشهدته ساحات الحرب في لبنان .. ولقد كشفت هذه الممارسات عن مدى الزيف الحضاري الذي يختفي وراءه إنسان القرن العشرين ..", "فحجم الحرب اللبنانية ليس في المساحة الجغرافية التي غطتها الحرب ونضحتها الدماء ، وإن كانت الحرب وآثارها قد غطت كل شبر من أرض لبنان .. كما أن حجم هذه الحرب ليس في وسائل الدمار التي استخدمت في هذه الحرب ، وإن كانت هذه الحرب قد شهدت كل منتجات الدمار ، واستعمل فيها كل ما في العالم من سلاح .. ويكفي أن يعلم القارئ أن عدد التنظيمات العسكرية والميليشيات قد تجاوزت الخمسين تنظيماً ، نذكر منها على سبيل المثال :", "- ميليشيا الحزب القومي السوري الاجتماعي .", "- ميليشيا حزب الكتائب اللبنانية .", "- ميليشيا حزب النجادة .", "- ميليشيا الحزب التقدمي الاشتراكي .", "- ميليشيا حزب الوطنيين الأحرار .", "- ميليشيا الحزب الشيوعي .", "- ميليشيا حزب البعث السوري .", "- ميليشيا حزب البعث العراقي .", "- ميليشيا المقاومة الشعبية ( صائب سلام ) .", "- ميليشيا حزب بارتي الكردي .", "- ميليشيا جيش التحرير الزغرتاوي .", "- ميليشيا التنظيم الناصري ( شاتيلا ) .", "- ميليشيا المرابطون ( قليلات ) ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0035.png"}, {"n": 36, "paras": ["- المجاهدون ( الجماعة الإسلامية ) .", "- ميليشيا ٢٤ تشرين .", "- ميليشيا حراس الأرز ( سعيد عقل ) .", "- ميليشيا منظمة العمل الشيوعي ( محسن ابراهيم ) .", "- ميليشيا منظمة أمل ( حسين الحسيني ) .", "- ميليشيا حركة ناصر ( عصام العرب ) .", "- ميليشيا فتيان علي .", "- ميليشيا جند الله .", "- ميليشيا صقور الزيدانية ( محمد عيتاني ) .", "- المنظمات الفلسطينية ..", "كذلك فإن حجم الحرب اللبنانية ليس في ما خلفته من قتلى ومشوهين وإن كانت الاحصاءات الأولية للخسائر البشرية التي وقعت خلال السنة الأولى من الحرب (١٩٧٥) قد قدرت باثني عشر ألف قتيل ، كما بلغ عدد الجرحى ٤٠ ألفاً أصيب بعضهم بعطل دائم أو بتشويه جسدي .. وتفيد التقارير بأن عدد المهاجرين من لبنان بلغ مائتي ألف نسمة .. وبأن الخسائر المادية فاقت العشرين مليار ليرة لبنانية .. وهناك تقديرات أخرى تقول أن الخسائر البشرية والمادية هي اضعاف هذه الأرقام بكثير .. إلا أن الحجم الأكبر والأخطر للحرب اللبنانية يبقى في عمق بصماتها الحضارية والأخلاقية على الإنسان نفسه . ولقد بدأ لبنان يشهد آثار هذه البصمات المخيفة يوماً اثر يوم ..", "الحلول المطروحة للمسألة اللبنانية", "* الحل من منظور الكتائب اللبنانية", "* الحل من منظور الوطنيين الأحرار", "* الحل من منظور الرهبانيات اللبنانية", "* الحل من منظور اليسار", "* الحل من منظور الطائفة الشيعية", "* الحل من منظور الوثيقة السياسية", "* الحل من منظور ميثاق ١٩٥٥ الإسلامي", "الفصل الخامس"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0036.png"}, {"n": 37, "paras": ["الحلول المطروحة للمسألة اللبنانية", "نكتفي تحت هذا العنوان باستعراض الحلول المطروحة من الجانب الماروني ( الجبهة اللبنانية ) وخلاصة الحل المطروح من الحركة الوطنية والحلول المطروحة من الجانب الإسلامي بشكل عام وصولاً إلى الحل الجذري الأسلم الذي نراه من منظور إسلامي ...", "أولاً : الحل من منظور الكتائب اللبنانية عبرت الكتائب اللبنانية عن وجهة نظرها في حل القضية اللبنانية من خلال الوثيقة التي قدمتها إلى الجبهة اللبنانية ونوردها هنا بنصها .. قالت الوثيقة : ( مشكلة لبنان هي نفسها مشكلة الأقليات في الشرق .. فالأكثرية الإسلامية بحكم طبيعتها كأكثرية أولاً ، ثم كأكثرية إسلامية ثانياً ، طاغية سواء كان ذلك بارادتها أو بغير ارادتها ، لذلك فهي خطر دائم على لبنان ، وبالتالي على الوجود المسيحي فيه بوجه عام .. ما هو الحل ؟ أياً كان النظام السياسي في لبنان ، فخطر الطغيان الأكثري المشار إليه لا يتغير إلا إذا أصبح النظام والحكم إسلاميين . وفي هذه الحال لا يعود من مبرر لوجود هذا الوطن .. وبمعنى آخر النظام أو البنيان السياسي ، أياً كان شكله ، لا يشكل وحده رادعاً للطغيان . فلا يصح اعتباره غاية في حد ذاته ، ويبقى أداة صالحة أو غير صالحة .."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0037.png"}, {"n": 38, "paras": ["فما هي الأداة الفضلى ؟ إنها التي تعطي الحضور المسيحي في لبنان ( المناعة ) التي تمكنه أكثر فأكثر من مقاومة الطغيان الأكثري ، والمحافظة على التوازن في ميزان القوى والمناعة هذه على أنواع ، أو متعددة الوجود والنواحي ..", "- فهي في العدد وكثافته", "- وهي في مدى انتشار المسيحيين على أرض لبنان وأشغالهم لهذه الأرض", "- وهي في الإنسان المتفوق على غير غطرسة أو عداء فيبقى أن نكتشف الصيغة السياسية التي تحقق هذه الأغراض الرئيسية الثلاثة .. وتوصلاً إلى ذلك نناقش الصيغ المعروضة واحدة واحدة ونقارن في ما بينها ..", "١ - التقسيم : وإن كانت فكرة التقسيم مجرد رد فعل وليست مشروعاً من المشاريع المطروحة ، فلا بد من تحديد شرورها ومخاطرها ، منعاً لتطورها من رد فعل إلى قرار سياسي .. التقسيم أولاً : لا يبدل من طبيعة الطغيان الأكثري في المنطقة أو يحد منه بل على العكس من ذلك ، يزيده وينشطه ، ويمكنه من الاستيلاء على نصف لبنان ، أو على بعضه ، فإذا هو في مقر الدار بدلاً من أن يكون على الأطراف .. وبالمقابل ، التقسيم يعني انكفاء وتراجع من قبل الحضور المسيحي إلى مواقع دفاعية أقل مناعة وأكثر منالاً ، سياسياً واقتصادياً وثقافياً وحضارياً وأمنياً ، مع ما يستتبع ذلك من تقلص في قدراته هذه المحدودة في السكان والعدد وفي الإمكانيات الطبيعية والإنسانية بوجه عام ..", "٢ - اللامركزية أو الفيدرالية : إنها بلا ريب أفضل الصيغ للمجتمعات المتعددة الانتماءات الحضارية والدينية والإنسانية ، هي أيضاً أرقى الحضارات الديمقراطية في هذا العصر ، وهي بالنسبة إلى لبنان وبوصفه مجتمعاً مركباً ، صيغة مثلى ..", "ولكن تطبيق هذه الصيغة في لبنان ترتهن بأن تكون مقبولة من الجماعات المتعددة وغير مرفوضة من قبل بعضها .. أما ارغام أحد الفريقين عليها فهو تقسيم ، والنتائج ستكون عند ذلك على الصورة التالية :", "- ارغام المسيحيين في المناطق ذات الأكثرية الإسلامية على الهجرة إلى المناطق المسيحية ، أو في أحسن الحالات اخضاعهم لحكم الأكثرية المحلية ومعاملتهم كأقلية ..", "- ومن الطبيعي أن تصبح المناطق الإسلامية أكثر حرية في التعامل مع الأكثرية الإسلامية في المنطقة ، وأكثر تضامناً معها ، وأشد تحالفاً على لبنان والحضور المسيحي فيه ، ليكون الطغيان في هذه الحال أقوى وأشد وأقرب أيضاً إلى قلب لبنان .. إذا كان التقسيم شراً كما هو واضح ومتفق عليه .. وإذا كانت اللامركزية السياسية أو الفيدرالية ترتهن باجماع عليها لم يتحقق بعد ، ولا يبدو أن تحقيقه ممكن في المستقبل القريب على الأقل .. ولأن اللامركزية السياسية المفروضة بشكل أو بآخر ، تؤدي إلى اضعاف الحضور المسيحي بدلاً من تعزيزه وتنمية قدراته .. لهذه الأسباب وغيرها يجب أن تأخذ خطة حماية لبنان من الطغيان الأكثري في المنطقة ، وبالتالي حماية الوجود المسيحي فيه ، اتجاهاً آخر يهدف إلى بسط سيطرة المؤمنين بلبنان مجتمعاً حضارياً منفتحاً متميزاً على أكبر رقعة من أراضيه والأفضل على كل أراضيه ، فتمر هذه الخطة بالمراحل التالية : المرحلة الأولى : تأكيد السيطرة على المناطق الموصوفة بالمناطق الحرة وتعزيزها وتنميتها باستمرار .. المرحلة الثانية : الانطلاق نحو المناطق الأخرى بعد احياء الوجود المسيحي فيها ، ثم تعزيز الوجود وتنميته أيضاً باستمرار رقعته إلى أقصى الحدود .."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0038.png"}, {"n": 39, "paras": ["المرحلة الثالثة والأخيرة : قيام الدولة الديمقراطية الحقيقية ، على أرضية ثابتة ، وقدرة دفاعية ذاتية أكيدة ، تجعل لبنان أكثر قوة ومناعة في مقاومة الطغيان الأكثر الملازم لطبيعة هذه المنطقة .. تنفيذاً لهذه الخطة ، ينبغي وضع استراتيجية عامة تحدد وسائل تحقيق هذه المراحل ، وتؤمن الوصول إلى الهدف النهائي في أقصر فترة زمنية ممكنة . تعتبر الاستراتيجية المذكورة بمثابة عهد أو ميثاق يلتزمه المؤمنون بلبنان وطناً نهائياً ، ويدخل في برامج أحزابهم وهيئاتهم وتنظيماتهم كلها . وبانتظار وضع هذه الاستراتيجية وإقرارها وتوضيحاً لبعض المرحلية وتسهيلاً كذلك لجهة الذين سيرسمونها نقترح ما يلي : أ - الاكتفاء مرحلياً بنوع من ( اللامركزية الإدارية ) في إطار النظام السياسي الراهن ، بعد تعزيز الضمانات والصلاحيات المعطاة للمسيحيين . وفي هذا الإطار يعهد إلى لجنة متخصصة في العلم الدستوري تضع في أقرب وقت مستطاع مشروعاً بالتعديلات الدستورية اللازمة والملائمة ، يكون بعد الموافقة عليه من قبل الجبهة ، أساساً للحوار والاتفاق المرحلي مع الفريق الآخر .. ب - العمل على إعطاء اللامركزية الإدارية مضموناً يحقق ويؤمن بصورة رئيسية الأغراض التالية :", "* منع قيام تجمعات سكنية غريبة جديدة في المناطق الحرة مثل ( الكرنتينا ) سابقاً ( وتل الزعتر ) وسواها .", "* تنمية اقتصادية وتربوية - ثقافية متواصلة ومتفوقة بما يكفل لهذه المناطق قدراً معيناً من الاكتفاء والاعتماد على الذات .", "* مهر المناطق المذكورة من التجهيزات الأساسية تحررها من الارتهان للمناطق الأخرى في مجالات الطاقة و المواصلات على أنواعها في الداخل ومع الخارج ... انتهت وثيقة الكتائب .", "ثانياً : الحل من منظور الوطنيين الأحرار كذلك قدم ( حزب الوطنيين الأحرار ) إلى الجبهة اللبنانية ضمنه رأيه في حل القضية اللبنانية ننقله هنا بنصه : المادة الأولى : في الدولة وحدودها لبنان دولة مستقلة ذات سيادة تامة . يحدها شمالاً النهر الكبير ، وشرقاً خط القمة الفاصل بين وادي خالد ووادي نهر العاصي ماراً بقرى المعيصرة ، وجنوباً حدود قضائي صور ومرجعيون الحالية ، وغرباً البحر المتوسط . المادة الثانية : لا يجوز التخلي عن أحد أقسام الأراضي اللبنانية أو التنازل عنها . المادة الثالثة : تنشأ في دولة لبنان ولايتان ومنطقة مشتركة .. تتكون ( الولاية الأولى ) من المدن والمجموعات السكنية والأراضي الزراعية والمشاعية التابعة لها والتي كانت معروفة باسم ( متصرفية جبل لبنان ) المحددة وفقاً لبروتوكول (١٨٦١ - ١٨٦٤) . تضاف إليها ( بيروت الشرقية ) باستثناء المنطقة المشتركة كما ستحدد فيما بعد .. المادة الرابعة : تتألف الولاية الثانية من القسم الغربي لمدينة بيروت باستثناء المنطقة المشتركة ، ومن باقي المدن والمجموعات السكنية والأراضي الزراعية والمشاعات التابعة لها .. المادة الخامسة : تتألف المنطقة المشتركة من الوسط التجاري لمدينة بيروت ، يحده شمالاً ( محلة الكرنتينا ) و ( الصيفي ) وشرقاً ( الخط الممتد من أول شارع الحمراء والبنك المركزي إلى ساحة رياض الصلح فساحة الدباس فشارع النهر ) وجنوباً إلى ( مبنى السفارة الأميركية ومدخل الجامعة الأميركية ) وغرباً ( البحر المتوسط ) . المادة السادسة : تتمتع كل ولاية بحكمها الذاتي في تقرير وإدارة شؤونها"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0039.png"}, {"n": 40, "paras": ["الإدارية والسياسية والقضائية والتشريعية والعسكرية والثقافية ، وفرض الضرائب وجبايتها وتقرير الموازنة وانفاقها . المادة السابعة : السلطة التنفيذية : يرأس كل ولاية حاكم أو رئيس للجمهورية يتمتع بالصلاحيات الدستورية المنصوص عنها في الدستور الحالي ، تعاونه حكومة مؤلفة من وزراء يعينهم رئيس الجمهورية ، ويختار من بينهم رئيساً ، وتحدد مسؤولياتهم وفقاً لأحكام الدستور الحالي . المادة الثامنة : السلطة التشريعية : يمارس السلطة التشريعية في كل ولاية ( مجلس نيابي ) مؤلف من نواب منتخبين يكون عددهم وكيفية انتخابهم وفقاً للقانون الذي تصدره كل ولاية .. المادة التاسعة : يحق لكل مواطن لبناني ذكراً كان أم أنثى أتم الخامسة والعشرين من عمره أن يرشح نفسه للانتخابات النيابية في الولاية التي ينتمي إليها كما أن لهذا المواطن حق الاقتراع عندما يتم العشرين من عمره . المادة العاشرة : السلطة القضائية : تتولاها المحاكم على اختلاف درجاتها واختصاصاتها في كل ولاية بموجب قانون يحفظ للقضاء مستواه الرفيع ثقافياً ومعنوياً ، ويصون استقلاله كما يؤمن الضمانات كاملة لحقوق المتقاضين . المادة الحادية عشرة : المجلس الأعلى للمصالح المشتركة : يتألف المجلس الأعلى للمصالح المشتركة من ستة أعضاء ومن سكريتيريتين عامتين تمثل الطوائف الرئيسية . المادة الثانية عشرة : رئاسة المجلس الأعلى تكون بالتناوب بين الستة أعضاء ، مدة ولاية كل منهم سنة واحدة ، تؤخذ القرارات بأكثرية الأصوات وعند التساوي يكون صوت الرئيس مرجحاً . المادة الثالثة عشرة : قرارات المجلس الأعلى نافذة ما لم يعترض عليها من قبل حكومة إحدى الولايتين في خلال شهر واحد من تاريخ تبليغها القرار خطياً مع علم بالاستلام .", "المادة الرابعة عشرة : تعين حكومة كل ولاية بمرسوم يتخذ في مجلس الوزراء نصف أعضاء المجلس الأعلى وسكريتيراً واحداً . ويتولى الرئاسة لأول سنة أكبر الأعضاء سناً . المادة الخامسة عشرة : مدة ولاية أعضاء المجلس الأعلى والسكريتيرين العامين ست سنوات قابلة للتمديد وفقاً لرغبة الحكومة التي يعنيها الأمر . المادة السادسة عشرة : يمارس المجلس الأعلى للمصالح المشتركة الصلاحيات التالية :", "١ - تطبيق الأنظمة والقوانين والقواعد التي تقوم عليها الوحدة الاقتصادية .", "٢ - تطبيق الوحدة الجمركية واستلام إدارة الجمارك في كافة الموانئ ونقاط الحدود اللبنانية المحلية ، وجباية الرسوم ، ومنع التهريب . ولأجل بلوغ هذه الغاية للمجلس الأعلى أن ينشئ شرطة جمركية تابعة له مباشرة والاستعانة بقوى الأمن التابعة لكل من الولايتين .", "٣ - صيانة النقد اللبناني وتأمين وحدته .", "٤ - تأمين حرية وسلامة المواصلات البحرية والبرية والجوية . المادة السابعة عشرة : يصدر المجلس الأعلى للمصالح المشتركة تقريراً سنوياً مفصلاً عن حركة الاستيراد والتصدير وإعادة التصدير ، كما يجب أن يتضمن تقريره بياناً عن حالة النقد وأوضاع الاحتياط ومقدار الرسوم الجمركية المجباة . المادة الثامنة عشرة : توزع العائدات الجمركية بين الولايتين على الصورة التالية : يدفع ثلث العائدات لصندوق كل ولاية ويحتفظ بالثلث الباقي في حساب خاص لمدة ثلاث سنوات يوزع بعدها على كل ولاية حسب مساهمتها في تكوين العائدات المشار إليها ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0040.png"}, {"n": 41, "paras": ["المادة التاسعة عشرة : من أجل تنسيق الخطط المتعلقة بتأمين سلامة وحرية تنقل المواطنين عبر الأراضي اللبنانية وسلامة وحرية إقامتهم ، ومن أجل تنسيق خطط الدفاع عن سلامة الأراضي اللبنانية والسياسية الخارجية تعقد اجتماعات دورية بين الوزراء المختصين من كل ولاية ، مرة واحدة كل شهرين ، وبصورة استثنائية كلما تدعو الحاجة ، لدرس ما يجب اتخاذه من تدابير ضرورية .. المادة العشرون : تطبق قوانين الولاية المدنية والجزائية على كافة المقيمين على أراضيها مهما كانت الولاية التي ينتمون إليها ، كما يخضعون للسلطات القضائية والإدارية والأمنية القائمة .", "المادة الحادية والعشرون : للمقيمين في المنطقة حق الخيار في الانتماء إلى الولاية التي يختارونها ، ويكونوا خاضعين للأنظمة والقوانين المعمول بها في تلك الولاية . المادة الثانية والعشرون : تعطى لكل مواطن لبناني تذكرة هوية من لون وقياس واحد تحمل فقط الإشارة إلى الولاية التي ينتمي إليها . المادة الثالثة والعشرون : أحكام مؤقتة : يحق لمدة سنة واحدة غير قابلة التمديد بكل مقيم على أرض ولاية أن يبدل انتماءه إلى الولاية الأخرى دون أن يؤثر هذا الطلب على حريته وإقامته ، ويبقى خاضعاً للقوانين والأنظمة المعمول بها في الولاية التي يقيم عليها .. ( انتهت وثيقة الأحرار ) .", "ثالثاً : الحل من منظور الرهبانيات اللبنانية قدم المؤتمر الدائم للرهبانيات اللبنانية ورقة عمل إلى خلوة الجبهة اللبنانية رسم فيها من وجهة نظره صورة لبنان الغد ، واقترح نظام اللامركزية السياسية كحل لمختلف المعضلات اللبنانية .", "وبعدما عرضت ورقة العمل المؤلفة من ١١ صفحة فولسكاب واقع لبنان الاجتماعي وهو واقع تعددي دخلت في تركيبه جماعات اثنية - دينية - حضارية ذات أصول وثقافات وتراث وتطلعات متنوعة . طرحت الحل كما يلي : منذ أكثر من سنة والمؤتمر الدائم للرهبانيات اللبنانية ، مستعيناً بمجموعة من المفكرين وأصحاب الاختصاصات المتنوعة ، يحاول أن يجد الجواب . وقد طرحت لجنة الدراسات السياسية العاملة مع المؤتمر صيغاً أربع للمناقشة واستمعنا إلى الكثير من التعليقات والملاحظات حول كل من هذه الصيغ إلى أن تكونت لدينا القناعات التالية :", "١ - نحن لا نريد تقسيم لبنان ولا نسعى إليه ، فلبنان يفقد الكثير من ذاتيته المميزة عبر التاريخ ومن رسالته في المنطقة والعالم إن هو تفتيت وبعثر .", "٢ - ولكننا نرفض كل صيغة أو شكل للبنان - الدولة يبقيه عرضة للتناحر والتحارب فالتمزق والانتحار .", "٣ - إن الصيغة التي نظن أنها كفيلة بإعادة تجميع لبنان وضمان وحدته ومعالجة الكثير من عوامل تهديمه هي اللامركزية السياسية . ولكي نكون واضحين فنعطي الكلمات مدلولها الصحيح والشعارات مضامينها الحقيقية سنبين فيما يلي :", "١ - ما الذي نقصده باللامركزية السياسية", "٢ - كيف تحل هذه اللامركزية معظم عقدنا ومعضلاتنا المطروحة والمزمنة . أولاً : المقصود باللامركزية السياسية يقول أحد الباحثين « حيثما توجد جماعات ذات أصول وثقافات وأساليب حياة مختلفة ، وعندما تريد كل جماعة منها أن تحافظ على شخصيتها ونمط حياتها وتنمية مواهبها وخصائصها ، لكنها تريد في الوقت نفسه أن تمارس حياة ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0041.png"}, {"n": 42, "paras": ["سياسية مشتركة في إطار من الحرية الواسعة ضمن وطن واحد يوفر لها منعة سياسية وإمكانات اقتصادية لا تتيسر لكل جماعة لو استقلت منفصلة عن شريكاتها ، فإن هذه الجماعات تختار نظام اللامركزية السياسية الذي يلبي رغبتها المزدوجة في الاستقلال المحلي الواسع من جهة والاشتراك في الحياة السياسية العامة من جهة أخرى » .", "فنظام اللامركزية السياسية الذي نقصده يتميز بالسمات التالية :", "١ - ينظم لبنان جغرافياً في أقاليم يراعى في ترتيبها : أ - توفر أكبر قدر ممكن من التجانس السكاني داخل كل منها . ب - توفر موارد طبيعية وطاقات انتاجية ذات شأن لكل منها . ج - وجود مدينة أو قرية كبيرة قابلة من حيث موقعها وأهميتها لأن تصبح عاصمة الاقليم ونقطة استقطاب واشعاع فيه .", "٢ - يقوم في كل إقليم حكم محلي بسلطاته الثلاث : التشريعية والتنفيذية والقضائية ، يتولى جميع الشؤون التي لها علاقة مباشرة بحياة الناس وأعمالهم ومنها الشؤون المالية والاقتصادية والاجتماعية والثقافية والتربوية والأمنية وغيرها ، مما يغني المواطن عن التعامل مع أية سلطة خارج إقليمه . على أن يختار مواطنو الإقليم أجهزة هذا الحكم بالأسلوب الديموقراطي الحر .", "٣ - يقوم إلى جانب الحكم المحلي حكم مركزي يحدد الدستور صلاحياته حصراً حيث يكون لكل ما هو خارج التحديد داخلاً في صلاحيات الحكم المحضي .", "( وإن لدى المؤتمر الدائم للرهبانيات اللبنانية مشاريع جاهزة ، مستعدة لطرحها للمناقشة في حال اعتماد الجهة الحل اللامركزي المقترح ) .", "ثانياً : كيف تحل هذه اللامركزية مشكلاتنا المطروحة والمزمنة", "١ - إنها تحافظ على ذاتية وخصائص المجموعات الحضارية اللبنانية إذ تتيح لها أن ترعى جميع شؤونها وفقاً لخياراتها الخاصة وأهمها الشؤون الثقافية والتربوية والمالية والاقتصادية وغيرها ..", "٢ - إنها تحل عقدة « المشاركة » إذ تعطي الحكم بكامله إلى كل جماعة تشكل في اقليمها أكثرية أكيدة في اقليمها . وفيما يختص بالصلاحيات الباقية للحكم المركزي يمكن أن تكون المشاركة كاملة باعتماد : أ - تعادل التمثيل في المجلس التشريعي المركزي وقاعدة الأكثرية المطلقة ضمن مجموع ممثلي كل اقليم . ب - احداث مجلس رئاسي في قمة السلطة التنفيذية المركزية يتخذ قراراته بالإجماع .", "٣ - وتحل اللامركزية مشكلة التجنيس الجماعي والتسابق على زيادة عدد أفراد كل جماعة إذ لا يعود لهذه الزيادة من معنى بل تصبح عبئاً على السكان الأصليين .", "٤ - وتحل كذلك مشكلة العلمنة إذ يصبح بوسع كل اقليم أن يسن لنفسه قوانين أحواله الشخصية .", "٥ - كما تحل أيضاً مشكلة الطارئين إذ يصبح بإمكان كل اقليم أن يحدد نسبة عدد الغرباء فيه .", "٦ - كذلك يستطيع كل اقليم أن يختار بالطرق الديموقراطية نظامه الاقتصادي والاجتماعي ضمن مبادئ دستور الحكم المركزي .", "٧ - ثم إن اللامركزية تحد من مركزية بيروت الاقتصادية ، فتجنبها الاختناق من جهة وتتيح للأقاليم تنمية اقتصادها وانعاش مرافقها ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0042.png"}, {"n": 43, "paras": ["إلا أن البعض يبدي حول اللامركزية السياسية التي نطرحها كصيغة تعايش جديدة في تركيب جديد للدولة الواحدة ، تحفظات ومخاوف :", "فمنهم من يرى فيها تقسيماً أو مقدمة للتقسيم ، ومنهم من يعتبرها سبيلاً لاضعاف الدولة وتفكيكها ، ومنهم من يقول أن لبنان أصغر من أن يتحمل الأقلمة ، وجوابنا على كل هؤلاء أننا لسنا نموذجاً فريداً في العالم للمجتمع التعددي ، وإن بلداناً كثيرة أكبر منا وأصغر واجهت وتواجه ما ينشأ عن هذه التعددية من مشكلات ، فعالجتها باعتماد الفدرالية الشبيهة لنظامنا المقترح . وما من مخلص يجرؤ على الادعاء بأن الولايات المتحدة والاتحاد السوفياتي وألمانيا الغربية والبرازيل وسويسرا هي دول مقسمة أو على طريق التقسيم . بل إن الاتحاد السوفياتي مثلاً ، وهو البلد الذي يعتنق أكثر العقائد كلية وأهمية لم يجد بداً من اعتماد النظام الفدرالي احتراماً لذاتية الأقليات المختلفة التي يتكون منها .", "هذا فضلاً عن أن دولاً من أعرق الدول مركزية ، كبريطانيا ، قدمت حكومتها إلى مجلس العموم في ٢٦ - ١١ - ١٩٧٦ مشروع قانون يقضي بمنح مقاطعتي سكوتلندا وولز استقلالاً ذاتياً ، معتمدة بذلك نظام اللامركزية السياسية . وفرنسا تبحث جدياً منذ زمن في اعتماد الأقلية وهي تدرك أن التخلي عن المركزية لا يضعف وحدتها الوطنية .", "وحتى البلدان الصغيرة ، كسويسرا ، لم تتعرض وحدتها الوطنية ولا كيانها للتقسيم حتى في أحلك فترات التاريخ الأوروبي الحديث ، إبان الحرب العالمية الثانية ، حين كان الضغط النازي على السويسريين المتكلمين اللغة الألمانية يشادهم بعنف نحو الانفصال عن الاتحاد السويسري .", "وإذا كانت سويسرا بلغت من الرقي ما يفوق رقينا ، فالإمارات العربية المتحدة والعراق والسودان والفليبين والحبشة لم تصل إلى هذا المستوى من التحضر ، ومع ذلك لم يبق أحد من الخائفين على لبنان من التقسيم إلا وأطرى على مبادرة هذه الدول الرامية إلى اعطاء بعض مناطقها استقلالاً ذاتياً صوناً لوحدتها الوطنية وتلافياً للتقسيم .", "رابعاً : الحل من المنظور اليساري", "يعتمد الحل اليساري أساساً على تحويل المجتمع اللبناني إلى مجتمع علماني ، كما ورد في البيان الصادر عن الأحزاب والقوى التقدمية في بيروت بتاريخ ١٩٧٦/٤/٢ وكما جرى طرحه على لسان كمال جنبلاط في عدد من الندوات التلفزيونية آنذاك .", "العلمانية من منظور إسلامي (١)", "من القضايا التي دفعتها الأحداث الدامية التي عصفت بلبنان - كحل لمشكلة الطائفية في نظر البعض - فكرة العلمانية ، أو فكرة علمنة الدولة ...", "كانت هذه الفكرة تطرح بين الحين والآخر خلال فترة ما قبل الأحداث من خلال الدعوة إلى الزواج المدني وإلغاء المحاكم الشرعية وتدعيم الوحدة الوطنية . ولكن بشكل ضعيف وغير مؤثر .", "ولقد بدئ بالتركيز على طرح العلمانية في منتصف الأحداث من قبل الاتجاهات اليسارية كمشروع بديل عن إلغاء الطائفية السياسية .. وعندما قوبلت الفكرة بالرفض من الجانب المسلم وأجهضت في مهدها أخذت هذه الاتجاهات تعطي العلمانية تفسيرات شتى تمهيداً لقبولها لدى المسلمين !!", "ولقد شارك الاتجاهات اليسارية في طرح فكرة العلمانية أحزاب يمينية تبنت هي بدورها الفكرة وأخذت تنادي بها وتدعو إليها كحل بديل يتجاوز إلغاء الطائفية السياسية .", "(١) راجع نشرة عنوانها العلمانية صادرة عن لجنة الدراسات الفكرية في الجماعة الاسلامية ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0043.png"}, {"n": 44, "paras": ["والجماعة الإسلامية - عرضت في رسالة أصدرتها - إذ تعرض لموضوع العلمنة بينت رأيها فيها وموقف الإسلام منها بكل موضوعية، بعيداً عن الانفعال، فلكي يعي المواطنون جميعاً حقيقة هذه الفكرة، أبعادها، وآثارها على الفرد والمجتمع. والجماعة الإسلامية تعتبر أن من الأسباب الرئيسية للأزمة اللبنانية وللممارسات اللاأخلاقية التي وقعت فيها إنما هو بعد المواطن عن هدى الله والتزام شرعه، وإن هذا لا يعالج بالتالي بتكريس فصل الدين عن الحياة، أي بعزل المجتمع عن الدين رسمياً ودستورياً. وإنما تكون معالجة الفساد والانحراف بمعرفة الأسباب المؤدية إليه. لذلك نرجو أن تكون هذه الرسالة نوراً على الطريق. يضيء جوانبه للمؤمنين، ويهدي الضالين المنحرفين، والله من وراء القصد وهو يهدي سواء السبيل.", "نشأة العلمانية لقد أصبح من البديهي القول أن العلمانية - تاريخياً - لم تظهر في بلاد المسلمين، وإنما انتقلت إليهم مع كثير من الأفكار الأخرى من بلاد الغرب في أوائل القرن العشرين. وإذا كانت فرنسا هي رائدة العلمانية بلا منازع وهي أول من طبقها ودعا إليها في أعقاب صراع دموي عنيف إلا أن التاريخ يؤكد أيضاً أن جميع الأمم النصرانية قد لجأت إلى العلمانية بشكل أو بآخر من أجل حل مشكلة مستعصية لا يمكن تجاوزها. هذه الظاهرة التاريخية تلفتنا للرجوع إلى النصرانية نفسها لنتلمس فيها أحد أهم ظهور العلمانية. فالنصرانية تقوم على مبدأ فصل الدنيا عن الآخرة، والناس فيها قسمان: رجال الدين والعلمانيون. كما تقوم على مبدأ فصل الدين عن الدولة. يظهر ذلك واضحاً في الجواب المنسوب إلى عيسى السلام رداً على السؤال الذي وجه إليه حول ولائه السياسي حيث قال: (دع ما لقيصر لقيصر وما لله لله ..) انجيل متى. إلا أن الكنيسة في فترة الاندفاع الديني الأول وعندما كانت حماسة الالتزام الديني تطغى على أي اعتبار آخر لم تترك ما لقيصر لقيصر بل راحت تتدخل في جميع الأمور باسم الله، مما أدخلها في صراع عنيف مع العلم والعلماء حيناً ومع الحكام المدنيين حيناً آخر. ولما كانت أفكار وممارسات الكنيسة في هذه المجالات جهد بشري محض قام به رجال الكنيسة ونسبوه إلى الدين كان من الطبيعي"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0044.png"}, {"n": 45, "paras": ["أن يظهر خطؤها وبعدها عن الصواب ولو بعد حين مما أدى إلى ذلك الصراع العنيف الذي لم تنج منه أية أمة نصرانية ، والذي كانت العلمانية - بمختلف صورها ومظاهرها - هي الحل المناسب له .", "لقد شعرت الشعوب النصرانية أنه لا بد من منع الكنيسة من التدخل في شؤون ( قيصر ) بعدما تبين أن هذا التدخل لم يكن في مصلحة الشعوب ولا في مصلحة التقدم العلمي ، وأنه قائم على امتيازات تعطى لرجال الدين بدون أي سند لا من الدين ولا من غيره ، ومن أجل ذلك ظهر اتجاهان : الأول : هو الإبقاء على الكنيسة وحصرها في مجال العبادات والأخلاق ومنعها من التدخل في أمور الناس الدنيوية ، وقد نجحت جميع البلاد النصرانية في ذلك نجاحاً تاماً باستثناء أنظمة الأحوال الشخصية حيث لا تزال هذه الدول تتفاوت في مدى الاعتراف للكنيسة بحق التشريع في الأحوال الشخصية . الثاني : هو الرفض الكامل للدين ولرجاله ، واعتباره أفيون الشعوب والسعي للقضاء عليه نهائياً ، وهذا هو مسلك الشيوعية النظري الذي لم تستطع تطبيقه واقعياً حتى الآن فعادت إلى ما يشبه الاتجاه الأول .", "وبين هذين الاتجاهين النظريين يمكننا أن نقسم الدول العلمانية اليوم إلى عدة أنواع : الأول : الدول الشيوعية ، وتقوم العلمانية فيها على محاربة الدين فكرياً ، وجعل التشريع خارج إطاره في جميع المجالات بما في ذلك الأحوال الشخصية ، مع ترك الحرية للناس بأداء واجباتهم وبالالتزام بأحكام الدين في الإطار الفردي البحت إذا لم يتعارض مع القوانين العلمانية . الثاني : الدول الرأسمالية ، التي لا تقوم على محاربة الدين في أصوله - كما تفعل الشيوعية - بل تمنع تدخل رجال الدين في شؤون الدولة والسياسة والتشريع ، ومن جهة أخرى تساعدهم على القيام برسالتهم الدينية ، فتقدم التبرعات للمؤسسات الدينية والمدارسها - وإن كانت لهذه المدارس مناهجها الخاصة المخالفة لمنهج الدولة - سواء داخل البلاد أو خارجها ، وهذا يظهر واضحاً من خلال المؤسسات التبشيرية الضخمة المنتشرة في كل بلاد العالم الثالث ، والتي تتلقى دعماً كبيراً من دول علمانية من أجل القيام بنشاطها التبشيري وقد يكون ذلك لتحقيق أهداف سياسية أخرى .", "الثالث : الدول الرأسمالية التي تسمح بالإضافة إلى ذلك بقيام نشاط حزبي سياسي على أساس ديني ، وتقوم فيها الأحزاب الديمقراطية المسيحية وأحياناً تصل إلى الحكم .. ومن الطبيعي أن هذه الأحزاب تتأثر في نشاطها السياسي بالأفكار الدينية إلى حد كبير .", "العلمانية في بلاد المسلمين وإذا كان ظهور العلمانية في بلاد الغرب أمراً طبيعياً لأنها كانت حلاً لمشكلة منبثقة من طبيعة النصرانية نفسها ، فإن عدم وجود هذه المشكلة في بلاد المسلمين جعلهم لا يفكرون بالعلمانية ولا يشعرون بأية حاجة إليها .", "ذلك أن الإسلام يشرع للبشرية ما يكفل لها اطمئنانها وسعادتها وتلاؤمها مع الكون والحياة ، فليس من انفصام بين المادة والروح ولا بين سلطة روحية وأخرى زمنية ، بل فيه سلطة واحدة تحكم كل جوانب الحياة سواء في مجال العبادة أو الحكم أو الاجتماع والاقتصاد بشرع الله . أما حكاية ( دع ما لقيصر لقيصر وما لله لله ) فليس لها وجود في مفاهيم المسلمين ، ذلك أن الحاكم في الإسلام يمارس سلطته في الحكم والإدارة كما يؤم الناس في الصلاة ، ( قل إن صلاتي ونسكي ومحياي ومماتي لله رب العالمين لا شريك له وبذلك أمرت وأنا أول المسلمين ) . والإسلام يخضع الإنسان - فرداً ومجتمعاً - وفي جميع نواحي الحياة لحكم الله وحده ، ويعتبر رفض الخضوع لحكم الله كلياً أو جزئياً كفراً يخرج به صاحبه من دائرة الإسلام ، ويعتبر أي حكم آخر - غير"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0045.png"}, {"n": 46, "paras": ["حكم الله - طاغوتاً يحذر المسلمين من الاحتكام إليه : ( ألم تر إلى الذين يزعمون أنهم آمنوا بما أنزل إليك وما أنزل من قبلك يريدون أن يتحاكموا إلى الطاغوت وقد أمروا أن يكفروا به ..؟ ) ( فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في أنفسهم حرجاً مما قضيت ويسلموا تسليما ) . والقداسة في نظر الإسلام لله وحده ، ولرسوله صلى الله عليه وسلم فيما يبلغه عن ربه ( قل : إنما أنا بشر مثلكم يوحى إلي ) وليس لأحد من الناس بعد ذلك قداسة تعصمه من الخطأ مهما بلغ من العلم والتقوى ، ولذلك عرف المسلمون التمييز بين حكم الله المحدد بالنصوص القرآنية أو النبوية ، وبين الحكم الشرعي المستنبط عن طريق الاجتهاد . فالأول لا يقبل التعديل أو التحوير أو التبديل ، بينما الحكم الثاني اجتهاد بشري يمكن نقضه باجتهاد آخر . ومن أجل ذلك لم تكن لآراء العلماء المسلمين القداسة التي ادعاها رجال الكنيسة .. بل هذا رسول الله صلى الله عليه وسلم يؤكد أنه عندما يحكم برأيه واجتهاده البشري فهو معرض للخطأ : ( انما أنا بشر ، وانه يأتيني الخصم ، فلعل بعضهم أن يكون أبلغ من بعض فأحسب أنه صادق فأقضي له ، فمن قضيت له بحق مسلم ، فإنما هي قطعة من النار فليحملها أو يذرها ) رواه مسلم . والواقع أن المسلمين في تاريخهم الطويل لم يشعروا أن حكم الله تعالى وتشريعه للبشر يقصر عن تلبية حاجاتهم وتحقيق سعادتهم ، ولم يفكروا في التخلي عن شريعة الله ولا في حصرها في مجال العبادات والأخلاق ، وبالتالي فإنهم لم يعرفوا العلمانية ولا خطرت على بال حتى وقعت الحرب العالمية الأولى وانتهت بهزيمة تركيا وباحتلال الحلفاء لمعظم بلاد المسلمين وتمزيقها دولاً ومستعمرات ..", "يومذاك فرض الحلفاء المنتصرون العلمانية على تركيا في مقابل سحب جيوشهم من أراضيها بل وفرضوا عليها شروطاً لقطع كل صلة تربطها بالعرب والإسلام ، فمنعوا اللغة العربية ، وحولوا كتابة اللغة التركية من الأحرف العربية إلى الأحرف اللاتينية .. وكان كمال أتاتورك صنيعتهم في تنفيذ ذلك فجعل تركيا أكثر تطرفاً في تطبيق العلمانية من كثير من الدول الأوروبية التي لا تزال تسمح بوجود أحزاب سياسية على أساس ديني بينما يمنع في تركيا وجود حزب سياسي على أساس إسلامي .", "وهكذا نجح الاستعمار في تحطيم الخلافة الإسلامية وفي قطع كل صلة تربط تركيا بالعرب ، ثم في تمزيق العرب أنفسهم دولاً متعددة لقطع الطريق على عودة الخلافة الإسلامية التي تجمع الشمل المبعثر . وقامت تركيا العلمانية تتنكر لكل الصلات التي تربطها بالعرب والمسلمين وتعترف بإسرائيل وتتعامل معها كما ترتبط بالأحلاف الغربية الاستعمارية . لم تكن العلمانية إذاً بالنسبة لتركيا حلاً لمشكلة تعانيها ، وإنما كانت مفروضة عليها من الخارج .. ومنها بدأت تتسرب إلى سائر بلاد المسلمين على استحياء في أول الأمر .. ثم بوقاحة كاملة بعد ذلك . وكلما ضعف سلطان الإسلام في قلوب المسلمين وعقولهم كلما وجدت العلمانية منفذاً تدخل منه . ولقد تفنن كثير من الحكام - المسلمين هوية العملاء حقيقة - في ادخال العلمانية إلى بلادهم . فبعضهم يجاهر بها ، والبعض الآخر يخفيها تحت ستار من القومية أو الاشتراكية ، وأحياناً يقولون : ( إن دين الدولة هو الإسلام ) بينما تكون قوانينهم وشرائعهم تخالف الإسلام .. كل ذلك لاستغفال المسلمين وخداعهم ريثما يصبح بالامكان المجاهرة بالعلمانية الكاملة الملحدة ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0046.png"}, {"n": 47, "paras": ["٤ - المجلس النيابي ١٩٢٦ ١٣/١٧ مع مجلس للشيوخ بنسبة ٧/٨ .", "٥ - المجلس التمثيلي النيابي ١٩٣٤ ٨/٩ منتخبون و ٣/٤ معينون .", "٦ - المجلس التمثيلي ١٩٣٧ ٨/٩ منتخبون و ٨/١٣ معينون .", "٧ - المجلس التمثيلي ١٩٤٣ ٢٥/٢٧ كلهم منتخبون وهو الأول في الاستقلال .", "٨ - المجلس النيابي ١٩٤٧ نفس النسبة .", "٩ - المجلس النيابي ١٩٥١ ٣٥/٤٢ اي ٥/٦ .", "العلمانية في لبنان", "واستقرت هذه النسبة في جميع المجالس النيابية بعد ذلك . وإذا تذكرنا أن أول مجلس إدارة شكل أيام المتصرفية ، وعندما كان لبنان محصوراً في حدود الجبل ، كان التمثيل فيه بنسبة خمسة إلى سبعة ، وانه بعد ضم الساحل والأقضية الأربعة وكلها تسكنها أكثرية ساحقة من المسلمين أصبحت نسبة التمثيل في المجالس النيابية هي خمسة إلى ستة أدركنا الغبن والظلم الذي رزح تحته المسلمون . وإذا أضفنا إلى ذلك حرص المستعمر الفرنسي على جعل الرئاسة الأولى بيد الموارنة مع اعطائها ما يشبه الصلاحيات المطلقة ، ذلك الحرص الذي أدى إلى تعليق الدستور وحل المجلس النيابي سنة ١٩٣٢ عندما كان المرشح لرئاسة الجمهورية الشيخ محمد الجسر وكان فوزه مؤكداً وذلك ( حتى لا تسلب الرئاسة من المسيحيين ) كما قال المفوض السامي الفرنسي للشيخ بشاره الخوري . كل هذا جعل الدولة منذ الاستقلال وحتى اليوم تسير في سياسة غير متوازنة وتحصر أهم المراكز الحساسة في الطائفة المارونية مع ما يؤدي إليه ذلك من غبن يلحق خاصة بالمناطق والطوائف الإسلامية ... هذا الشعور بالغبن أدى إلى ظهور الدعوة لالغاء الطائفية السياسية أو لتحقيق العدالة بين الطوائف في كل أجهزة الدولة ومعاملة جميع اللبنانيين بالعدالة والمساواة . وكانت ردة الفعل من الطائفة المارونية - في سبيل المحافظة على امتيازاتها", "عندما وقعت حوادث سنة ١٨٦٠ في جبل لبنان أقرت الدولة العثمانية بالاتفاق مع الدول الأجنبية الكبرى جعل لبنان متصرفية مستقلة يديرها متصرف نصراني غير لبناني ومجلس إدارة يتألف من اثني عشر عضواً موزعين على الطوائف كما يلي : ٤ للموارنة ٢ للروم الارثوذكس ١ كاثوليك ٣ للدروز ١ للسنة ١ للشيعة . أي سبعة للنصارى مقابل ٥ للمسلمين بمن فيهم الدروز . وعندما انتهت الحرب العالمية الأولى بهزيمة تركية قرر المندوب السامي الفرنسي ضم الساحل الممتد من طرابلس إلى صور بالإضافة إلى بعلبك والبقاع وحاصبيا وراشيا إلى جبل لبنان سنة ١٩٢٠ وأعلن الجنرال غورو قيام لبنان الكبير ، وتعيين أول مجلس إداري بصفة لجنة استشارية من ستة عشر عضواً موزعين على الطوائف كما يلي : ٦ موارنة ٢ أرثوذكس ١ كاثوليك ٤ سنة ٢ شيعة ١ دروز أي بمعدل تسعة للنصارى وسبعة للمسلمين . واستمر هذا التمييز الظالم في تشكيل المجالس التمثيلية سواء كانت انتخابية أو معينة - كما في مجلس الشيوخ عندما كان قائماً حتى اليوم - وكانت النسبة فيه بين المسلمين والنصارى كما يلي :", "١ - المجلس التمثيلي ١٩٢٢ ٧/٨ .", "٢ - المجلس التمثيلي ١٩٢٥ ٧/٨ .", "٣ - المجلس التمثيلي ١٩٢٦ ٧/٨ مع مجلس للشيوخ بنسبة ٦/٩ ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0047.png"}, {"n": 48, "paras": ["السياسية الظالمة - ان طالبت بالعلمنة الكاملة وخاصة في مجال الأحوال الشخصية وإقرار قانون موحد لها .", "لماذا العلمانية في لبنان ؟ وقد التقى على الدعوة إلى العلمانية الكاملة النقيضان المتمثلان بالانعزالية الطائفية المارونية واليسارية التقدمية الاشتراكية . ولا تزال هذه الدعوة تظهر وتخبو وتتولى كبرها كبريات الصحف اللبنانية وتعقد لها ندوات ومحاضرات وتوصف للناس على أنها الخلاص الوحيد للبنان . من أجل ذلك نتساءل : ما هي الأهداف الحقيقية لطرح العلمانية في لبنان ؟ وقبل أن نجيب على هذا السؤال لا بد أن ننبه إلى حقيقة قائمة وهي أن لبنان بواقعه الحالي دولة علمانية بكل معنى الكلمة ، وتتجلى هذه العلمانية فيما يلي :", "١ - الدستور اللبناني لا ينص على هوية دينية للدولة وإن كان ينص على احترام جميع الأديان والمذاهب ويكفل إقامة الشعائر الدينية . ومن المعلوم أن كثيراً من الدول العلمانية تتخذ مثل هذا الموقف من الدين .", "٢ - إن شرعية السلطة بموجب الدستور اللبناني لا تستمد من أي دين ولا من أية هيئة دينية ، إنها تستمد من الشعب اللبناني الذي يمثله مجلس النواب . وإذا كان الذين يتولون السلطات التنفيذية والتشريعية والقضائية يجب أن يكون لهم انتماء ديني معين إلا أنه شكلي تماماً . إن الذي يتولى السلطة بحكم انتمائه الديني المعين لا يحمل معه مذهبه الديني بل يعتبر ممثلاً لجميع اللبنانيين .", "٣ - إن التشريع في لبنان علماني محض يقوم به رجال منتخبون من قبل الشعب ولا يخضعون لأي اعتبار ديني ولا يستوحون الأصول التشريعية لأي دين بل يشرعون ما يخالف دينهم . ولا يستثنى من ذلك إلا التشريع الخاص بالأحوال الشخصية الذي جعله الدستور اللبناني تابعاً للطوائف .", "هناك فقط ظاهرتان يشكل وجودهما خدشاً للعلمانية الكاملة : الأولى : هي الطائفية السياسية ، وهذا قد لا يتعارض مع علمانية الدولة لأن الطوائف هنا ينظر إليها على أنها أحزاب وتجمعات سياسية أكثر منها طوائف دينية . والدليل على ذلك أن من يمثل طائفته في أي مركز من مراكز السلطة لا يستوحي مذهبه الديني في مركزه بل غالباً ما يخالف دينه ومراجعه الدينية . ولقد كان اعتماد الطائفية السياسية ( التماساً للعدل والوفاق ) - كما صرح بذلك الدستور - إلا أن ممارستها كانت بعيدة عن العدالة فأدت إلى عدم الوفاق مما قوى الدعوة إلى إلغائها نهائياً . الثانية : هي وجود قوانين الأحوال الشخصية الخاصة بكل طائفة وحماية الدستور اللبناني لها . ولعلنا الآن قد وصلنا إلى الجواب الدقيق عن سبب وهدف طرح العلمانية في لبنان ، إنه إلغاء استقلال كل طائفة في أحوالها الشخصية ووضع قانون موحد تطبقه محاكم مدنية ، هذا ما يصرح به أحياناً أكثر دعاة العلمانية ، وأحياناً أخرى يحاولون تمريره عن طريق شعارات واقتراحات تخفف من أثره على جماهير المسلمين خاصة .", "أسباب الدعوة إلى علمنة الأحوال الشخصية فلندخل إلى صلب الموضوع ولندرس الأسباب التي يذكرها دعاة العلمانية كمبررات لعلمنة الأحوال الشخصية . هذه الأسباب في نظرهم هي :", "١ - إن وجود قوانين دينية للأحوال الشخصية يعني أن الدولة ليست ذات سيادة على هذا الجزء الهام من حياة شعبها مع العلم أن سيادة الدولة يجب أن تكون كاملة وشاملة على كل شيء .", "٢ - إن وجود قوانين دينية للأحوال الشخصية يبقي المجتمع في إطار العقلية الدينية وهذا وضع قد تخطاه الزمن وتجاوزه التطور البشري ، وإلغاء هذه القوانين يحرر الفرد والمجتمع من القيود الدينية ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0048.png"}, {"n": 49, "paras": ["٣ - إن وجود قوانين دينية للأحوال الشخصية يثبت الانقسامات الطائفية ويعمقها ويمنع الوصول إلى وحدة وطنية حقيقية ، بينما وضع قانون مدني موحد يلغي هذه الانقسامات ويؤدي إلى وحدة وطنية حقيقية .", "٤ - إن وجود قوانين دينية للأحوال الشخصية يجعل تكوين العائلة محصوراً في طائفة واحدة ويمنع تكونها من طائفتين . إن هذا الأمر يحول دون وجود وحدة تقوم على صلات الدم والقرابة بين أبناء الوطن الواحد .", "٥ - هناك أفراد في المجتمع لا يؤمنون بأي دين ، وارغامهم على اتباع القوانين الدينية في أحوالهم الشخصية يتنافى مع مبدأ الحرية . إن وجود قانون مدني موحد ولو كان اختيارياً يحل مشكلة هؤلاء المواطنين ويصون حريتهم .", "٦ - وإن القانون المدني الموحد - إذا كان اختيارياً - لا يتنافى مع الإسلام لأن المسلم يجوز له - في زعم دعاة العلمانية - أن يطبق أي قانون يريد لأنه (لا إكراه في الدين ) .", "مناقشة هذه الأسباب لا بد من التنبيه أولاً إلى أن كل هذه الأسباب تعني إلغاء القوانين الدينية للأحوال الشخصية واستبدالها بقانون مدني موحد وإلزامي - إلا ما يتعلق بمشكلة الذين لا يؤمنون بأي دين وهذه يمكن حلها عن طريق قانون مدني اختياري تبقى إلى جانبه القوانين الدينية - وهذا يكشف نوايا دعاة العلمانية ومدى استغفالهم للمسلمين عندما يطرحون القانون المدني الاختياري بينما يطمحون إلى جعله إلزامياً لتحقيق الأهداف التي لا تتحقق أبداً إذا بقي اختيارياً .. فلا سيادة الدولة تكون كاملة ولا الإنسان يتحرر من القيود الدينية ، ولا الوحدة الوطنية الحقيقية ، ولا وحدة النسب والدم والقرابة يمكن أن تتحقق بقانون مدني اختياري . إذن فالمرحلة الأولى يمكن أن تمر هكذا .. أما الثانية فهي حتماً قانون إلزامي واحد تلغى معه تماماً كل القوانين الدينية للأحوال الشخصية .", "وننتقل الآن لمناقشة تلك الأسباب", "١ - أما أن سيادة الدولة يجب أن تشمل كل نواحي الحياة فهذا من بقايا فلسفة الحكم الاستبدادي المطلق وهو يؤدي إلى تجريد الإنسان من حريته وكرامته وهي تتناقض مع الفكر السياسي الحديث الذي ينادي باستقلالية الإنسان في كل ما لا تدعو الضرورة والمصلحة العامة الى تدخل الدولة فيه ، وانه لعجيب حقاً أن تنادي الجبهة اللبنانية المسماة جبهة الحرية والإنسان بالعلمانية وأن تفرط بمفهومها عن الحرية الشخصية .. لولا أن الامتيازات التي تتحقق لها عن طريق الطائفية السياسية أكبر بكثير .", "ثم أنه كيف يتنافى وجود قوانين دينية للأحوال الشخصية مع سيادة الدولة إذا كانت الدولة هي التي تضعها موضع التنفيذ وإذا كانت لا تتم خارج إرادتها ولا تحدياً لها .. ومن البديهي أن الدين لا يملك أية سلطة سياسية في لبنان تنازع سلطة الدولة .", "٢ - أما أن وجود قوانين دينية للأحوال الشخصية يبقي المجتمع في إطار العقلية الدينية التي تخطاها الزمن ، وإلغاءها يحرر الفرد والمجتمع من القيود الدينية ، فهذه نظرة قد تصح بالنسبة للنصرانية ولكنها لا تصح أبداً بالنسبة للإسلام ، لأن العقلية الدينية الإسلامية لم يتجاوزها الزمن بل هي التي لا زال التطور يسعى إليها وخاصة في مجال القوانين . وإذا كان إلغاء القوانين الدينية يحرر الفرد والمجتمع من القيود الدينية فإنه يوقعه في قيود وضعية وبذلك تتحول المسألة إلى أيهما أفضل لمصلحة الفرد والمجتمع : القوانين الدينية أو القوانين الوضعية ، طالما أنها كلها قيود وهذا لا مجال لتفصيله في هذه الدراسة .", "٣ و ٤ - أما إن وجود قوانين دينية يثبت الانقسامات الطائفية ويحول دون الوصول إلى وحدة وطنية حقيقية ، ويجعل تكون العائلة محصوراً في طائفة واحدة ، ويمنع تكونها من طائفتين ، ويحول بالتالي دون وحدة مبنية على صلات الدم"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0049.png"}, {"n": 50, "paras": ["والقرابة ، فالواقع أن لبنان يقوم على فئات دينية متنوعة ، وقوانين الأحوال الشخصية المختلفة ناشئة عن هذا التنوع الديني وهي لا تسبب الانقسامات الطائفية لأن هذه تنشأ عن الطائفية السياسية ، وإلغاء هذه القوانين يعني التعرض للإلغاء الدين عن طريق القضاء على آثاره في المجتمع أكثر مما يعني إلغاء الانقسامات الطائفية . أما الوحدة الوطنية في بلد كلبنان فلا بد أن تقوم على تفاهم بين الطوائف تشعر به كل طائفة أنها تربح أكثر مما تخسر ، وعندما تعرض الوحدة الوطنية على المسلمين على أنها بديل عن الإسلام وتشريعاته الخاصة للأحوال الشخصية فسيكفر المسلمون بالوحدة الوطنية نفسها لا بالإسلام . إن المطلوب اليوم إيجاد الصيغة التي لا تخرج المسلمين من دينهم وتحفظ للبنان جميع أبنائه على قدم المساواة ، وهذه الصيغة ممكنة بإلغاء الطائفية السياسية .", "أما الدعوة للوحدة القائمة على صلات الدم والقرابة فهي وحدة تجاوزها الزمن وأصبحت الصلات بين الناس تقوم اليوم على وحدة الفكر أو وحدة المصالح والأهداف ، ولم يعد للدم أو حتى للغة ذلك الأثر الكبير في توحيد الشعوب . ثم إن إلغاء قوانين الأحوال الشخصية الدينية أو استبدالها بقانون مدني لن يؤدي إلى التزاوج بين الطوائف لأن الأمر متعلق بالدين لا بمجرد قوانينه . هناك نسبة ضئيلة تقدم على مثل هذا الأمر رغم وجود القوانين الدينية ، وهذه النسبة قد تزيد قليلاً ولكنها تبقى استثناء ضئيلاً جداً لا يكفي لتحقيق وحدة الدم إلا إذا كان دعاة العلمانية يريدون أن يفرضوا ويشجعوا مثل هذا الزواج المختلط بمختلف وسائل الترغيب والترهيب . ونكون هنا أمام حرب مكشوفة ضد الدين هدفها تشجيع زواج المسلمات من غير المسلمين الذين لا يحترمون مشاعرهن ولا يعترفون بالإسلام ، ثم يقولون أنهم يحافظون على الإيمان الديني ولا يناصبونه العداء .. هل المحافظة على الإيمان الديني لا يكون إلا بالقضاء على آثاره في المجتمع وتحرير الأفراد من الخضوع لقوانينه في الحياة ؟", "٥ أما مشكلة غير المؤمنين فهي واقع لا شك فيه ولكن ما هي نسبة هؤلاء إلى مجموع اللبنانيين ؟ هل تزيد عن واحد بالمئة ؟ وهل يجوز إلغاء قوانين الأحوال الشخصية ل ٩٩ ٪ من اللبنانيين ارضاء لهذه النسبة الضئيلة .", "وإذا كانت كل فئة من المواطنين يجب أن يشرع لها من القوانين ما يرضيها فلماذا لا تشرع بالنسبة للمسلمين مثلاً القوانين الإسلامية التي تحرم الربا وتطبق العقوبات الشرعية ؟", "إن مشكلة غير المؤمنين بدين وهم قلة لا تحل إلا بخضوعهم للأكثرية . أما فتح باب وضع قوانين خاصة لهم فإنه يحل مشكلة وينشئ عشرات المشاكل بديلاً لها . ثم هل يوجد قانون وضعي واحد في الدنيا يرضى بتطبيقه جميع الناس ؟! وهل من المصلحة كلما رفضت قلة من الناس قانون الأكثرية أن نضع لها قانوناً خاصاً ؟", "٦ أما إن الإسلام لا يتعارض مع وجود قانون مدني اختياري للأحوال الشخصية بحجة قوله تعالى ( لا إكراه في الدين ) فهو مرفوض تماماً لأن أي إنسان عنده حد أدنى من المعرفة بالإسلام والقرآن يدرك أن هذه الآية الكريمة تتعلق بعدم الإكراه على الدخول في الدين ، وتتمة الآية تؤكد هذا المعنى : ( لا اكراه في الدين قد تبين الرشد من الغي فمن يكفر بالطاغوت ويؤمن بالله فقد استمسك بالعروة الوثقى لا انفصام لها والله سميع عليم ) وإذاً فإن الإسلام يرفض إكراه أي إنسان على الدخول فيه ، ولكن متى أصبح الإنسان مسلماً أصبح ملزماً بالخضوع لكل تعاليم الإسلام وقوانينه ، وهذا ليس إكراهاً ولكنه ترجمة الإيمان إلى تطبيق ، وإلا أصبح الإسلام مجالاً للعب والتسلية والاحتيال أكثر منه ديناً يطالب معتنقيه بالتزام أسلوب معين في الحياة .", "وبعد . فإن لبنان اليوم يقف على أبواب صيغة جديدة ، وإن المسلمين في لبنان يهمهم أن يؤكدوا تمسكهم بلبنان بلداً يقوم على التنوع الديني لا على الانقسام"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0050.png"}, {"n": 51, "paras": ["الطائفي ولا على التسلط المتعصب . وإن المسلمين في لبنان - مع تمسكهم القاطع بمبادئ دينهم وقوانينهم الخاصة بالأحوال الشخصية وإيمانهم بقوامة شريعتهم وضرورة العمل على تحكيمها فيهم يقبلون بأية صيغة تضمن التعايش القائم على العدل والمساواة انطلاقاً من إلغاء الطائفية السياسية ... أو من تحقيق العدالة بين الطوائف والمناطق . أما العلمانية فهي المرض الذي يقضي على الإيمان ولو بعد حين ... ولن نكون مغفلين لنسمح لها بالمرور إلى أجسادنا المنهكة تحت أية حجة .. ولو زعموا أنها ( قانون اختياري !! ) فالبداية معروفة .. والنهاية مكشوفة .", "خامساً : الحل من منظور الطائفية الشيعية : حدد المجلس الإسلامي الشيعي الأعلى في مذكرة سلمها إلى المبعوث البابوي الكاردينال باولو برتولي ، مفهومه لهوية لبنان ونظامه وتصوره للخطوط الكبرى للإصلاح المنشود في المجالات السياسية والدفاعية والإدارية والثقافية والتربوية والاعلامية والاجتماعية والاقتصادية . وهنا نص المذكرة : « إن الطائفة الإسلامية الشيعية في لبنان التي تعتز بكونها من أرسخ دعائم كيانه والتي ساهمت مساهمة فعالة في نضاله الطويل من أجل استقلاله وسلامة أراضيه وبقائه ضمن واقعه العربي ، ودفعت في هذا السبيل ، دونما منة ، من حياة أبنائها وممتلكاتهم ومختلف وسائل عيشهم أبهظ الأثمان ، والتي لا تزال مستعدة لبذل أية تضحية مهما عظمت من أجل الوطن المفدى . بعدما انجلت المحنة عن معظم أنحاء لبنان ، ومع التشديد على وجوب إجلائها عن كامل أنحاء الجنوب . وإزاء ما خلفته هذه المحنة المأساة من الدمار والتصدع في البنيان والإنسان ، وفي هيكلية الدولة ، وفي الاقتصاد الوطني ، وفي لحمة المجتمع اللبناني ، وفي سمعة لبنان الحضارية ، فضلاً عن عشرات آلاف الضحايا البريئة من كل الطوائف والمناطق ، وفي مقابل ما يطرح من الأفكار وما يتخذ من المواقف ، من قبل مختلف الهيئات والتجمعات الطائفية والسياسية ، في سبيل بناء لبنان الجديد . وشعوراً بمسؤوليتها التاريخية في هذا المنعطف الخطير من حياة لبنان ، بل المصيري في حياة المنطقة بأسرها ، وتلبية لواجب المساهمة في انهاض الوطن والحفاظ على استقلاله وسيادته ووحدة أرضه وشعبه ، وانسجاماً مع مواقفها الدائمة في خدمة المصلحة العامة ، تحقيقاً لمطامح الأجيال الصاعدة ، نعلن ما يأتي :", "ملاحظات عامة", "١ - أياً كانت أسباب المحنة ، وأياً كانت العناصر الخارجية التي هيأها ودفعتها وتفاعلت بواسطتها على أرضنا ، وأياً كان دور إسرائيل ومن يشد أزرها في هذه المؤامرة الضخمة التي حيكت خيوطها في عواصم عديدة قبل أن تنفذ على أرض لبنان ، وأياً كان صراع اليمين الدولي واليسار الدولي مباشرة أو بواسطة اليمين واليسار اللبنانيين على الساحة اللبنانية ، وأياً كان خلاف اللبنانيين أو بعضهم مع الفلسطينيين ، وأياً كانت امتيازات فئة منا وغبن فئة ، ومهما تعاظم عاملا الخوف والغبن عند كل من الفئتين ... وبكلمة واحدة مهما عددنا لهذه المحنة المأساة من أسباب داخلية وعربية ودولية يختلف على تحديدها اللبنانيون باختلاف مشاربهم ومصالحهم وانتماءاتهم ، يبقى أمر ثابت واضح لا خلاف عليه هو أن الجسم اللبناني كان قد فقد مناعته الطبيعية وأمسى عرضة لكل المضاعفات .", "٢ - إن الوطن ، بمعناه العميق ، ليس أرضاً محددة فحسب ، تلتقي عليها طوائف ضمن مناطق ، متعايشة سلمياً في نوع من الحذر والتحاسد والتمويه ، بل هو قبل كل شيء مناخ استقرار وطمأنينة وثقة في إخاء حقيقي ، وحرية مسؤولة ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0051.png"}, {"n": 52, "paras": ["وطموح على بساط العدالة الاجتماعية في إطار تكافؤ الفرص للجميع ، وفي احترام حضاري للكرامة الإنسانية .", "٣ - إن واجب الدولة ، واجبها الأول ، هو إنماء روح المواطنية الصحيح في نفوس المواطنين ، بكل ما لديها من وسائل . ومن الفضول القول أن كل الوسائل الناجعة للوصول إلى هذا الهدف الأسمى هي أصلاً ، بحكم طبيعتها ، في يد الدولة .", "٤ - إن المآسي في حياة الشعوب الراقية بواتق انصهار وتجدد وتألق ، وليس كثيراً على الشعب اللبناني ، العريق في أصالته ، أن يخرج من مأساة العامين الرهيبة وقد انصهر تجدد وتألق ، فيعمد إلى تعمير ما تدمر في بنيانه الاجتماعي ، بل إلى تجديد هذا البنيان من أساسه ، بما يكفل له وحدة وطنية حقيقية ، لا رياء فيها ولا زيف ، وحدة يكون هو فيها الوطن الحي ، الدائم التجدد على أرض الوطن .", "بعد هذه الملاحظات العامة ، التي تعتبرها الطائفة الإسلامية الشيعية أساسية في بناء لبنان الجديد ، يهمها أن تؤكد على ما يأتي :", "أولاً - في هوية لبنان ونظامه : تجدد الطائفة الإسلامية الشيعية إيمانها بلبنان الواحد الموحد :", "- وطناً نهائياً بحدوده الحاضرة سيداً حراً مستقلاً .", "- عربياً في محيطه وواقعه ومصيره ، يلتزم التزاماً كلياً بالقضايا العربية المصيرية ، وفي طليعتها قضية فلسطين .", "- منفتحاً على العالم بأسره يلتزم بقضية الإنسان لأنها من صلب رسالته الحضارية .", "- جمهورية ديموقراطية برلمانية ، تقوم على احترام الحريات العامة وفي طليعتها حرية الرأي والمعتقد ، وعلى مبدأ فصل السلطات ، وعلى العدالة الاجتماعية والمساواة في الحقوق والواجبات بين جميع المواطنين ، في نظام اقتصادي حر مبرمج ، ووفق تخطيط علمي إنمائي شامل لمختلف الطاقات والاحتياجات والنشاطات في كل المضامير . بلد الكرامة الإنسانية والطموح الحضاري .", "وتشدد الطائفة الإسلامية الشيعية على أن هذه الأوصاف ليست كلياً أو جزئياً ، ولا يمكن أن تكون ، موضوع مساومة أو تسوية ، لأنها ليست عارضة أو طارئة ، وليست مطلباً من مطالب فئة من دون أخرى ، بل هي منبثقة من جوهر وجود لبنان ، ومن صميم كيانه ، ومن رسالته التاريخية ، ومن آفاق مصيره ، ومن طموح أبنائه وتطلعاتهم المستقبلية .", "ثانياً : في ما لا يمكن القبول به :", "١ - تقسيم لبنان . إن الطائفة ترفض رفضاً باتاً أية صورة من صور التقسيم ، تحت ستار لا مركزية سياسية أياً كانت هيكليتها ، وهي على العكس ترحب بأية صيغة للامركزية الإدارية التي من شأنها تعزيز الحكم المسؤول في المناطق واختصار المعاملات الروتينية وتقريب القضاء من المتقاضين وإشراك الهيئات الشعبية والبلدية ومجلس المحافظات في إدارة الشؤون المحلية .", "٢ - تشويه وجه لبنان الحضاري بتحجيم دوريه العربي والدولي ، أو بقطعه عن المد الحضاري الإنساني ، أو بجره إلى أي محور سياسي عربي أو دولي ، بحيث يتقوقع ويتقزم ، أو ينحاز ويفقد طابعه المميز .", "٣ - تحجير الصيغة اللبنانية بحيث يبقى عامل القلق على المصير عند البعض ذريعة للمحافظة على امتيازات فئوية ، بينما يبقى عامل الغين عند البعض الآخر باباً للنزاع ، وبحيث يبقى العاملان معاً ثغرتين في الكيان تنفذ منهما المؤامرات على سلامة البلد واستقلاله وسيادته ووحدة أرضه وشعبه .", "٤ - أية تسوية بين الأطراف على حساب الوطن - ولو مؤقتة ، وقد علمتنا التجارب أنه لا يدوم إلا المؤقت - بحيث لا يسفر الحوار المرتقب عن رغبة صادقة مدعومة بتخطيط شامل لتحديث الدولة في جميع مرافقها ، تحديثاً جذرياً ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0052.png"}, {"n": 53, "paras": ["ولحل المشاكل الاجتماعية ، التي تتفاقم ، ولإيجاد تكافؤ الفرص للجميع على أساس الكفاية والنشاط والاخلاص ، في ضوء رؤية مستقبلية مستمرة الاستكشاف . مستمرة التركيز والتحسين . هذه النقاط الأربع ، يهم الطائفة الإسلامية الشيعية أن تشدد على رفضها جملة وتفصيلاً لأنها شبه قنابل موقوتة ، لا بد من أن تؤدي إلى الانفجار عند أول فرصة تسنح . ثالثاً - في الخطوط الكبرى للإصلاح المنشود : تعي الطائفة الإسلامية الشيعية ، في عمق وشمول ، أنها ليست وحدها في الوطن لتفرض ما تشاء ، وهي ، بانفتاحها على كل الأفكار الخيرة ، تطلب بمحبة واخلاص إلى سائر الطوائف والهيئات السياسية أن يبلور في نفسها هذا الوعي الوطني البناء . فلبنان للجميع لا فضل فيه لأحد على أحد . وإذا كان لا بد من تمييز ، فالأفضل لمن يعطي من مواهبه ونشاطه وإخلاصه ، وليس لمن يأخذ من طريق الآخرين وعلى حساب الوطن . بهذه الروح نطرح الخطوط الكبرى للإصلاح الذي نرتأيه ، كورقة عمل في الحوار المرتقب . ونحن ، إذ نعلن عن استعدادنا لمناقشة أي بند من هذه البنود ، ولوضع دراساتنا في تصرف المسؤولين ، نؤكد سلفاً أمرين أساسيين ، الأول أن هذه النقاط عامة يحتاج كل منها إلى توضيح وتفصيل من رجال الاختصاص ، الثاني إننا مستعدون للقبول بأي اقتراح في هذه المجالات تتفق عليه غالبية اللبنانيين . بنود الإصلاح المقترحة :", "١ - في السياسة : أ - إلغاء الطائفية السياسية في كل مرافق الحياة العامة . ب - اعتماد الاستفتاء الشعبي في القضايا المصيرية . ج - تشكيل المجلس الاقتصادي الاجتماعي ، أو مجلس الشيوخ ، أو كليهما . د - تعديل قانون الانتخابات النيابية على أساس جعل لبنان كله دائرة انتخابية واحدة ، واعتماد البطاقة الانتخابية وإجراء الانتخابات في يوم واحد . وفي هذا التعديل تحقيق للأغراض الآتية : يصبح النائب فعلاً نائب الأمة جمعاء حسب نص المادة ٢٧ من الدستور الحالي . ويصبح نائب كل شبر من لبنان . ويقضى على التزوير والرشوة وما إليهما . ويستغنى عن نقل الناخبين إلى مناطقهم وما يجر ذلك من نفقات ومشاكل مخلة بالأمن ويفتح الباب واسعاً للحزبية السياسية الصحيحة ، على أساس مبادئ وليس على أساس مصالح عارضة أو تجمع أشخاص أو تكتل طائفي . إضافة إلى مزايا أخرى كثيرة . لكن أهم مزية في هذا التدبير ، أن يشعر النائب أن ناخبيه هم مجموعة الشعب اللبناني وأن منطقته هي كل أرض لبنان ، فتعتدل سياسته بعيداً عن كل تطرف ، وتتسع آفاقه في السعي وراء المشاريع العمرانية والإنمائية . إن المحنة المأساة التي دامت عامين ودمرت ، إضافة إلى المباني ومرافق الحياة الاقتصادية ، لحمة المجتمع اللبناني ، تفرض فرضاً أن يصبح لبنان دائرة انتخابية واحدة . وإلا فسيبقى طوائف ومناطق ، ويبقى التمزيق في الباطن والتلفيق في الظاهر حائلين أساسيين دون أية وحدة وطنية حقيقية ، وبالتالي دون بناء وطن بالمعنى العميق ، الأصل الثابت الأركان . وتمهيداً لهذه الغاية ، وإلى أن تشمل لبنان بأسره أحزاب وطنية ، يمكن اعتماد الدائرة الموسعة بحيث لا تقل عن نطاق المحافظة . ه - إنشاء محكمة عليا من كبار القضاة . متفرغة ، جميع أفرادها قضاة ، مهمتها مثلثة تتولى :", "- محاكمة الرؤساء والوزراء .", "- بت دستورية القوانين ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0053.png"}, {"n": 54, "paras": ["- بت الطعون الانتخابية .", "٢ - في تطبيق مبدأ فصل السلطات : أ - فصل الوزارة عن النيابة . ب - انتخاب رئيس المجلس ومكتبه لمدة أربع سنوات ، لئلا يبقى رئيس المجلس رهن رضا النواب أو رضا السلطة التنفيذية . ج - انتخاب رئيس الوزارة من قبل المجلس النيابي واشتراكه بعد ذلك مع رئيس الجمهورية في تأليف الحكومة . د - عدم إمكان حل مجلس النواب إلا في حالات محددة . ه - تحديد صلاحيات رئيس الجمهورية ورئيس الوزراء والوزراء في صورة واضحة . و - استقلال القضاء استقلالاً تاماً قاطعاً ، بحيث يكون مجلس القضاء الأعلى هو المهيمن الفعلي ، الأول والأخير ، على شؤون القضاة وفقاً للشروط القانونية المطلوبة .", "٣ - في الإدارة : اعتماد جميع أساليب العلم والخبرة ومبدأ الفعالية ومفهومي الإنتاج والمردود واستخدام التكنولوجيا لتحديث الإدارة وتطهيرها تدريجياً ، من العناصر الفاسدة أو العقيمة ورفعها إلى مستوى المسؤوليات الجسام التي تتولاها ، وأن يكون تحركها دائماً في إطار الرؤية والتخطيط وأن تعتمد على تعزيز معهد الإدارة ويكون التعيين والترقية معتمدين على عنصري الكفاية والمهارة فقط .", "٤ - في الدفاع الوطني والأمن الداخلي :", "- إعادة بناء الجيش بحيث يصبح سياجاً للوطن وأداة فعالة في إنمائه ومدرسة لإرساء قواعد الوحدة الوطنية وتعزيزه بالعدد والعتاد الكافيين ، وتحديث وسائل اعداده .", "- تعزيز الجيش وزيادة عدده وسلاحه ووضع قانون متطور جديد يتناسب مع تطور الزمن ومتطلبات البلاد .", "- إنشاء مجلس قيادة وفقاً للنظم الحديثة .", "- تطبيق التجنيد الإلزامي وقانون خدمة العلم .", "- إعادة النظر في ملاكات الرتب العسكرية بحيث يكون عدد العمداء والعقداء والمقدمين والرواد وسائر الضباط مستوحى من مقتضيات التنظيم العسكري البحت .", "- إعادة تنظيم قوى الأمن الداخلي وتعزيزها بالعدد والعتاد والعناصر البشرية القيادية الصالحة ، بحيث تصبح قادرة على ضبط الأمن ومساعدة العدالة في كل المناطق .", "- حل كل الميليشيات والتنظيمات المسلحة وتجميع سلاحها .", "٥ - في الثقافة : إن المفهوم الصحيح للثقافة هو مفهوم سياسي حضاري ، غايته الأولى بناء وطن موحد متماسك متحضر طامح . ومن وسائله مساهمة كل فرد في البناء المعنوي للوطن . ولذلك لا بد من اعتماد وحدة الثقافة الوطنية بعد تحديد مضمونها ومعالمها واتجاهاتها . أما اللغات والثقافات الاختيارية الأخرى فإنها مرتبطة برغبة المواطن ونتيجة تفاعله مع العالم وشعوبه وهي مع الاحتفاظ بالثقافة الأصيلة الواحدة تصبح واقعاً متألقاً يتناسب مع رسالة لبنان الحضارية في العالم .", "- إنشاء وزارة للثقافة .", "- إحياء التراث اللبناني .", "- تنمية الثقافة الريفية .", "- إنشاء مركز وطني للمعلومات والمحفوظات . أو بطريقة أفضل ، تعجيل إنشاء مركز الأبحاث العلمية وعلوم الإنسان الذي قررت الأونيسكو إنشاءه في"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0054.png"}, {"n": 55, "paras": ["جبيل منذ سنوات ، وبذل كل الجهود لإرساء قواعده وتشييد بنيانه ، والاتصال الحثيث بكل الدول والمؤسسات الثقافية والمالية في العالم للمساهمة في إقامته وتجهيزه وتزويده بكل ما يحتاج إليه .", "٦ - في التربية والتعليم :", "- إعادة النظر في برامج التعليم في صورة جذرية شاملة ، في مختلف المراحل ، بهدف التوحيد والتحديث وتحقيق الفعالية التي يتطلبها التطور العلمي والتكنولوجي ، وبغية وضع لبنان في موكب العصر الذي يعيشه .", "- إلزامية التعليم ومجانيته حتى نهاية المرحلة المتوسطة .", "- تعزيز التعليم المهني ، والزراعي منه على الأخص ، وتوزيع معاهده ومدارسه على المناطق اللبنانية حسب طبيعة تلك المناطق واحتياجاتها ، وذلك من ضمن خطة شاملة لتطور الصناعة والزراعة والتجارة تستشرف حاجة هذه القطاعات المتزايدة وتمهد لتوجيه مهني سليم للناشئة في ضوء النمو السكاني وتزايد عدد المقبلين على الفروع المهنية .", "- تعزيز نطاق الجامعة اللبنانية وتوسيعها ، مع المحافظة على وحدتها ، وجعلها قطب التربية والتعليم في لبنان ، وإنشاء الكليات التطبيقية فيها ، وتزويدها بالأساتذة الأكفياء المتفرغين ، وتجهيز مكتباتها ومختبراتها تجهيزاً كاملاً ، وتسهيل تعاملها بالمستوى اللائق مع كبريات الجامعات في العالم .", "- دعم مجلس البحوث العلمية ، وتخصيص موازنة له في مستوى مهماته ليصبح عاملاً فعالاً في إنماء الاقتصاد الوطني ، وحائلاً دون هجرة الأدمغة من لبنان .", "- إنشاء إدارات الإعداد التربوي على مختلف المستويات في كل المناطق .", "- إلزامية التعليم الديني وتأسيس دار للمعلمين من أجله .", "٧ - في الاعلام : الاعلام ليس اخباراً فحسب . إنه توعية وإرشاد وتوجيه . من هنا أهميته إيجاباً وسلباً ، فهو الذي يساهم إلى حد بعيد في خلق المواطن الصالح أو في تضليل المواطن الجاهل ، وتوحيده توحيداً كلياً من دون أي استثناء ومهما كلف الأمر من مال وجهود ومجابهة . ثم اعطاء الاعلام الموحد مضموناً وطنياً صرفاً ، ثم تجهيزه بالعناصر البشرية الواعية المخلصة ، وبكل ما يحتاج إليه من آليات وإنشاءات ووسائل اتصال ليصبح صوت لبنان وضميره ومصباحه . وانطلاقاً من هذه المبادئ يتحتم اتخاذ التدابير الآتية :", "- إعادة النظر في تنظيم وزارة الاعلام ، لاعطائها الحجم الملائم لرسالتها الخطيرة كما ونوعاً ، والاستعانة بكل معطيات التكنولوجيا الحديثة في سبيل ذلك .", "- توسيع الإذاعة اللبنانية فنياً ليصل صوتها واضحاً جلياً إلى كل أنحاء لبنان بدون إستثناء ، وإلى العالم بأسره .", "- إلغاء كل الإذاعات الخاصة التي أفرزتها الحوادث .", "- إنشاء مؤسسة في وزارة الاعلام ، مهمتها جمع الأخبار وتدوين الأحداث اللبنانية والعالمية وحفظ المستندات والوثائق المتعلقة بهذه الأحداث . وبصورة عامة تجمع وتصنف وتحفظ كل ما من شأنه أن يفيد الباحثين والمؤرخين في المستقبل ، في مختلف المجالات السياسية والاقتصادية والثقافية والاعلامية .", "- اعلان حرية الصحافة ، حرية مسؤولة ، ضمن الحدود القانونية ، ومراقبة مداخيل الصحافة ومصادر تمويلها وتشجيع اندماج الصحف المرخص لها في وحدات تعاونية ، وإلغاء كل الصحف غير المرخص بها التي أفرزتها الأحداث .", "- تطبيق مبدأ الزامية الاعلام . تلتزم بموجبه السلطات بجعل المواطنين في مجرى الأحداث دائماً ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0055.png"}, {"n": 56, "paras": ["- تشجيع النشرات الدورية الثقافية والعلمية والتقنية .", "- إعادة النظر ، نتيجة كل ذلك ، في قانون المطبوعات .", "٨ - اجتماعياً : بما أن كل المشاريع التي تتولاها الدولة على كل الصعد تتوجه إلى الجسم الاجتماعي ككل وتهدف إلى تحسين أوضاع الشعب المادية ، فمن الضروري إذن أن تكون كل نشاطات الدولة مبنية على ضوء الاحتياجات الاجتماعية . إن ارتقاء الإنسان ورفاهيته وحقه في حياة كريمة يقتضي :", "١ - أن يتم وضع سياسة ديموغرافية شاملة بالنسبة إلى اللبنانيين والمقيمين على الأرض اللبنانية والهجرة الداخلية والخارجية والطارئين والدائمين بحيث لا يخفى مكتوم واحد على أرض لبنان .", "٢ - أن يتجه التطور الاجتماعي بحيث تتكافأ الفرص أمام الجميع .", "٣ - أن تتأمن المساواة على مستوى العمل والتربية والثقافة باعتماد برامج وخطط تؤدي تدريجياً إلى لا مركزية معظم المرافق الوطنية .", "٤ - أن يتم وضع سياسة إسكان تسمح لكل مواطن بالحصول على سكن لائق بالإنسان وتمكنه من امتلاكه في مرحلة لاحقة .", "٥ - أن يتم وضع سياسة اشغال وتسليفات تسمح بتشييد مناطق سكنية في المدن والأرياف .", "٦ - أن يتم إنماء المناطق المحرومة وإنشاء مراكز تنمية في كل المناطق الساحلية والريفية .", "٧ - تعميم الضمانات الاجتماعية بحيث تضم ضمان الشيخوخة والبطالة والمرض بالنسبة إلى جميع المواطنين .", "٨ - أن يرسى بناء التقدم الاجتماعي على أساس من المشاركة الفعلية بين مختلف قوى الشعب المنتجة وأن يتأهل العمال تدريجياً للمشاركة في الإدارة الذاتية مما يفسح في المجال لارتقاء اجتماعي حقيقي وبناء وطني الجذور ( مساهمة في إدارة المؤسسات ومشاركتة في أرباحها ) .", "٩ - أن ترسم سياسة لمكافحة التلوث وحماية الطبيعة والإنسان والثروات الوطنية تهدف إلى تأمين مستوى أفضل لحياة المواطن في المستقبل القريب والبعيد .", "١٠ - أن يتم إنشاء مؤسسات استشفائية وصحية تبعاً لحاجات المناطق .", "١١ - أن يتم وضع سياسة للطب الوقائي الاجتماعي تشمل كل أنحاء الوطن .", "٩ - اقتصادياً : للمبادرة الفردية والملكية الخاصة دور أساسي معترف به . من هنا كان وجوب المحافظة عليهما ضمن الحدود التي لا تسيء إلى المصلحة العامة وعليه يقوم دور الدولة على :", "١ - مراقبة المبادرة الفردية وتوجيهها لضمان تنمية منسجمة للاقتصاد الوطني .", "٢ - تدعيم هيكلية القطاع العام والعمل في استمرار على إنمائه وتغذيته .", "٣ - إعادة النظر في مجمل النظام الضريبي الحالي .", "٤ - وضع سياسة تكفل التعامل بين الصناعة والتجارة والزراعة .", "٥ - استملاك الدولة لكل المرافق العامة ( الطرق ، وسائل النقل ، المرافئ ، المياه ، الكهرباء ، الإذاعة والتلفزيون وغيرها ) وتحمل مسؤوليات إدارتها كاملة . سادساً : الحل من منظور الوثيقة السياسية : بتاريخ ١٤ / ٢ / ١٩٧٦ أذاع رئيس الجمهورية اللبنانية سليمان فرنجية الوثيقة السياسية التالي نصها كحل للأزمة اللبنانية :", "١ - التأكيد على العرف القائم بتوزيع الرئاسات الثلاث ، فيكون رئيس"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0056.png"}, {"n": 57, "paras": ["الجمهورية مارونياً ، ورئيس المجلس النيابي شيعياً ، ورئيس الوزراء مسلماً سنياً ، واعتبار كل من الرؤساء الثلاثة ممثلاً لكل اللبنانيين ..", "٢ - توزيع المقاعد النيابية بالتساوي بين المسلمين والمسيحيين ونسبياً ضمن كل طائفة ، وتعديل قانون الانتخاب في ضوء ذلك بما يضمن تمثيلاً أفضل للمواطنين .", "٣ - انتخاب رئيس مجلس الوزراء من المجلس النيابي بالأكثرية النسبية ، ثم يقوم رئيس الوزراء بإجراء المشاورات البرلمانية لتشكيل الوزارة ، ويتم وضع اللائحة بأسماء الوزراء بالاتفاق مع رئيس الجمهورية ، وبعدها تصدر المراسيم ..", "٤ - اعتماد أكثرية الثلثين في مجلس النواب لإقرار القضايا المصيرية ، وأكثرية ٥٥ ٪ بالمئة لانتخاب رئيس الجمهورية في الدورات التي تلي الدورة الأولى .", "٥ - وضع نص يجعل رئيس الجمهورية ورئيس الوزراء والوزراء مسؤولين ، وإنشاء المجلس الأعلى لمحاكمة الرؤساء والوزراء .", "٦ - قيام رئيس الوزراء والوزراء بقسم يمين دستورية أمام رئيس الجمهورية .", "٧ - إصدار جميع المراسيم ومشاريع القوانين بالاتفاق بين رئيس الجمهورية ورئيس الوزراء ، وتحمل توقيعها ما عدا تعيين رئيس الوزراء وقبول استقالة الوزارة أو إقالتها . ويتمتع رئيس الوزراء بجميع الصلاحيات التي يمارسها عرفاً .", "٨ - وضع نص يضمن الإسراع في إصدار المراسيم والقرارات .", "٩ - تعزيز استقلال القضاء ، وإنشاء محكمة دستورية عليا للنظر في دستورية القوانين والمراسيم ..", "١٠ - تعزيز اللامركزية في العمل الإداري .", "١١ - إزالت الطائفية في الوظائف ، واعتماد مبدأ الكفاية مع المحافظة على المساوات في وظائف الفئة الأولى .", "١٢ - إنشاء مجلس أعلى للتخطيط والإنماء من مهماته وضع برامج الخطط الإنمائية .", "١٣ - العمل على تحقيق عدالة اجتماعية شاملة ، من خلال الإصلاح المالي والاقتصادي والاجتماعي .", "١٤ - تعزيز التعليم العام بما يؤدي إلى تعميم التعليم المجاني وإلزاميته وتطوير البرامج التربوية بما يرسخ الوحدة الوطنية .", "١٥ - وضع سياسة دفاعية وتعزيز الجيش .", "١٦ - تكريس حرية مسؤولة للصحافة تضمن انسجامها مع سياسة المجتمع في تحقيق الوحدة الوطنية وتوطيد علاقات لبنان العربية والدولية ..", "١٧ - تعديل قانون الجنسية .. هذه القواعد التي تطرح عليكم اليوم والتي يصير العمل بها تبعاً لتنفيذ اتفاق ( القاهرة ) ما هي .. إنها إعلان نهج للعمل الوطني جرى تدوينه في وثيقة وافق عليها مجلس الوزراء وسيعرض مضمونها على مجلس النواب ، وتكون إلى جانب الميثاق الوطني غير المكتوب ركيزة جديدة تضاف إلى ركائز الحياة الوطنية في لبنان .. وتستمد قوتها من الولاء للبنان ومن الاخلاص في خدمته .. مناقشة الوثيقة السياسية : (١) القسم الأول - إيجابيات الوثيقة : لا شك أن في البيان إيجابيات نتمسك بها ونعتبر تأكيدها تأصيلاً لواقع ينبغي تدعيمه والاعتزاز به ولعل أهم هذه الإيجابيات هو حسم الجدل فيما يتعلق بهوية لبنان ذي اللغط حول هذا الموضوع الوجه العربي .. فقد كثر وقدمت دراسات ومذكرات حرضت جميعها على نبذ الانتماء العربي فجاء البيان مؤكداً .", "(١) من نشرة اصدرتها الجماعة الاسلامية في ذلك الحين ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0057.png"}, {"n": 58, "paras": ["أن لبنان بلد عربي مستقل . والأمر الآخر في الإيجابيات هو ما يتعلق بالمقاومة الفلسطينية وحقها في الحياة والتحرك ضمن اتفاق القاهرة . وثالث هذه الإيجابيات إنشاء المحكمة الدستورية لمراقبة دستورية القوانين والأنظمة والمراسيم والقرارات بحيث تضمن العدالة والحرية والمساواة . القسم الثاني - سلبيات الوثيقة :", "* النقطة الأولى : تكريس الطائفية : كرس البيان الطائفية في الرئاسات الثلاث فأعطى رئاسة الجمهورية للموارنة ورئاسة مجلس النواب للشيعة ورئاسة الوزارة للسنة . كما أنه كرس الطائفية في المجلس النيابي فوزعت مقاعده مناصفة بين الطوائف الإسلامية ( سنة ، شيعة ، دروز ) وبين الطوائف النصرانية ( موارنة ، روم أرثوذكس ، كاثوليك ، أرمن ، إنجيليون ) وكذلك أبقى البيان التوازن الطائفي في مراكز الفئة الأولى من الوظائف وألغاها في المراكز الأدنى . ملاحظات حول تكريس الطائفية :", "١ - بدل أن تتطور الدولة اللبنانية نحو إلغاء الطائفية نراها تعود إلى تكريسها ببيان سمي تارة « بالوثيقة الدستورية » وتارة « بالبيان الاصلاحي » وهي رجعة إلى الوراء تتناقض بشكل فاضح مع المبادئ الأساسية في الدستور الصادر في ٥/٢٣/", "١٩٢٦ ومع المادة ٩٥ منه والتي أجازت الوضع الطائفي بصورة مؤقتة ( التماساً للعدل والوفاق ) .", "٢ - إن حركة الجماعة الإسلامية ترفض اعتماد الحل الطائفي في لبنان لأسباب كثيرة منها : أ - ما سبق أن التزمت به من مبدأ إلغاء الطائفية السياسية من القمة إلى القاعدة .. وهو مبدأ يجعل المراكز جميعاً مفتوحة أمام الجميع وعلى صعيد المساواة . ب - ان اعتماد الحل اللاطائفي مع الحفاظ على جوهر الدين هو وحده الذي يبني لبنان جديداً . ج - إن اعتماد الحل الطائفي يبقي احتمالات التفجر والتصادم بين الطوائف قائمة ويزيد في تعقيد الحياة اللبنانية .", "٣ - إن تكريس الطائفية يضع الطائفة المارونية عبر مركز رئاسة الجمهورية على رأس كل الطوائف اللبنانية ، وهذا يجرنا إلى التساؤل : على أي أساس أعطي الموارنة الرئاسة الأولى ؟ هل على أساس أنهم الطائفة الأكثر عدداً أم على أساس أن في الموارنة « مؤهلات لانجاب الرؤساء » ليست لدى الطوائف الأخرى ؟ أليس في ذلك تمايز بين أبناء الوطن الواحد يكسر قاعدة المساواة ويمنع العطاء وخدمة البلاد عن أبناء الطوائف الأخرى ؟", "٤ - إن تكريس الرئاسة الأولى لطائفة الموارنة يتعارض مع أحكام الشريعة الإسلامية الغراء نصاً وروحاً .", "٥ - ثم إن البيان كرس التوازن الطائفي عددياً في مراكز الفئة الأولى وألغى الطائفية في سائر الوظائف الدنيا . إن إلغاء الطائفية السياسية مبدأ شامل لا يجوز تجزئته ، فعندما تلغى طائفية الوظيفة ينبغي أن تلغى من كل صعيد ابتداء من القمة حتى القاعدة فلا يمكن التسليم بقبول إلغاء طائفية الوظيفة الدنيا وإبقائها في الفئات الأولى وفي الرئاسات الثلاث وفي المجلس النيابي . إن إلغاء طائفية الوظيفة في الدرجات الدنيا له مخاطره العديدة خاصة بعد أن أكدت الوثيقة السياسية استمرار العمل بالعرف المزعوم بإبقاء الرئاسة الأولى - صاحبة السيادة - للطائفة المارونية الأمر الذي يفرض كثيراً من التعسف واختلال التوازن .. وقد يتسبب في كثير من المشاكل . هذا فضلاً عن أن البيان لم يشر إلى القيادات غير المدنية وهي من الفئات الأولى ، فهل ستخضع لمنطق الوظيفة"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0058.png"}, {"n": 59, "paras": ["وتلغى طائفتها أم ستبقى في منأى عن ذلك استمرار للتآمر على المسلمين ؟ إننا نؤكد على مطلبنا بربط الغاء طائفية الوظيفة بإلغائها على كل صعيد ونطالب هنا مرحلياً باخضاع كافة الوظائف المدنية وغير المدنية لمنطق التوازن والتبادل .", "* النقطة الثانية : هل أعطي المسلمون حقوقاً أم سلبت منهم الحقوق ؟", "١ - في مناصفة عدد أعضاء المجلس النيابي بين المسلمين والمسيحيين : يظن الكثير أن هذه المناصفة التي ألغت القاعدة الانتخابية المعروفة ٦/٥ هي مكسب كبير للمسلمين تحقق عبر البيان - الوثيقة .. ولا شك أن المرء لأول وهلة يقر بذلك باعتباره زيادة .. وكل زيادة هي مكسب ولكن لو عمقنا الرأي وقلبناه لوجدنا أن المسلمين اليوم في لبنان يتجاوز عددهم ٦٥ ٪ باعتراف بعض كبار رجال السياسة والدين المسلمين .. ومن أجل ذلك تهرب الحكم في لبنان ولا يزال من إجراء إحصاء عام شامل ، فلو أن الوثيقة تبنت إلغاء الطائفية السياسية من مجلس النواب لحصل المسلمون على سبعين بالمائة من المقاعد وعلى ضوء ما تقدم يتبين أن قاعدة المناصفة كانت في مصلحة المسيحيين أكثر من مصلحة المسلمين .", "ومن جانب آخر لم تنص الوثيقة على الإصلاحات المنتظرة في قانون الانتخاب ولعل أهم إصلاح كان يمكن أن يدخل هو تخفيض السن وسوى ذلك من أمور ليس الآن مجال استعراضها .", "٢ - في انتخاب رئيس الوزراء من قبل مجلس النواب : قلنا أن اعطاء مركز رئاسة الوزراء للسنة لا يعني أن السنة قد نالوا مركز سلطة في الدولة وذلك للأسباب التالية : أ - إن الدستور اللبنانى أوجد ثلاث سلطات مستقلة عن بعضها البعض : السلطة التشريعية ، والسلطة القضائية ، والسلطة التنفيذية . على رأس السلطة التنفيذية رئيس الجمهورية ، وإن مركز رئيس الوزارة يأتي بعد رئيس الجمهورية فإذا كان للسلطة التنفيذية رأس واحد فهذا يعني أن الطائفة السنية لم تعط مركز سلطة بل وظيفة في السلطة التنفيذية وتحت سيطرة رئيس الجمهورية الماروني . وقديماً قيل إن رئيس الوزراء « باش كاتب » وأكد ذلك البيان - الوثيقة عندما نص على وجوب حلف رئيس الحكومة اليمين وقسمه أمام رئيس الجمهورية .", "ب - إن رئيس الحكومة أعطي بموجب بيان رئيس الجمهورية الصلاحيات التي كان يمارسها عرفاً . وإذا عرفنا أنه بمقتضى العرف لم يكن رئيس الحكومة يمارس صلاحيات فعلية في السلطة ، أدركنا أن البيان لم يحقق لطائفة السنة المشاركة الفعلية والفعالة في الدولة ، مثلاً : عندما قام الطيران اللبناني بقصف القوات التي كانت تحاصر الدامور كان ذلك دون علم رئيس الحكومة ووزير الدفاع ، كما أن القصف لم يتوقف رغم إصدار رئيس الحكومة ووزير الدفاع أوامره بتوقيف القصف ! هذا نموذج من الصلاحيات التي كان يمارسها رئيس الحكومة عرفاً !", "ج - إن انتخاب رئيس الحكومة من قبل مجلس النواب بالأكثرية النسبية بينما انتخاب رئيس الجمهورية بأكثرية ٥٥ بالمائة له عدة دلالات : إنه يعطي النواب النصارى دوراً مؤثراً في انتخاب رئيس الوزراء المسلم على أساس أن المركز ليس لهم ، بينما ينقسم النواب المسلمون بين المرشحين لهذا المنصب ، كما أن تركيبة النظام اللبناني تعطي رئيس الجمهورية سلطة التأثير الفعال على الأكثرية النيابية ولا سيما في أوائل عهده ، وتوجيه تلك الأكثرية نحو انتخاب رئيس وزراء يرضى عنه وتؤيده الطوائف النصرانية فيأتي رئيس الوزراء - المفروض أنه ابن الطائفة السنية - مرتباً للطوائف النصرانية ولرئيس الجمهورية الماروني يضاف إلى ذلك أن حق رئيس الجمهورية في إقالة الوزارة ، دون أية قيود تحد من هذا الحق ، يكشف من جهة أولى أن مركز رئيس الحكومة هو مركز وظيفي وليس مركز سلطة ، كما أنه يكشف مدى سيطرة رئيس الجمهورية على الوزارة ورئيسها ، فضلاً عن ذلك فإن انتخاب رئيس الحكومة من قبل مجلس"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0059.png"}, {"n": 60, "paras": ["النواب إلا أنه لا يستطيع تشكيل حكومته بإرادته المنفردة وعرضها على رئيس الجمهورية لأن البيان فرض عليه « الاتفاق مع رئيس الجمهورية » على ذلك . د - إنه إذا كان ولا بد من تكريس الطائفية في مناصب الدولة فكان يجب ملاحظة ما يلي :", "١ - يجب إعطاء رئيس الحكومة صلاحيات دستورية محددة تجعل له دوراً فاعلاً في الدولة غير مرتهن لأحد وغير مسؤول إلا أمام مجلس النواب وأمام المحكمة المختصة بمحاكمة الرؤساء .", "٢ - إن إعطاء الحق لرئيس الجمهورية بإقالة الوزارة يقتضي الغاؤه فالسلطة التي انتخبت هي وحدها التي يمكن أن تحجب ثقتها .. ويبقى لرئيس الجمهورية حق محاكمة رئيس الحكومة .", "٣ - إن حق رئيس الوزارة بتشكيل الحكومة يجب أن لا يشاركه فيه أحد ويظل بقاء الحكومة مرهوناً بثقة مجلس النواب لها .", "٤ - لا يجوز لرئيس الحكومة أن يقسم أي يمين أمام رئيس الجمهورية لأن رئيس الحكومة مسؤول أمام البرلمان لا أمام الرئيس الأول . نخلص من كل ذلك أن السنة لم يعطوا حقوقاً تدل على دورهم في المشاركة الفعالة في إدارة دفة السلطة في البلاد .", "* النقطة الثالثة : مسؤولية رئيس الجمهورية : تضمن البيان إشارة إلى وجوب وضع نص يجعل رئيس الجمهورية ورئيس الوزارة والوزراء مسؤولين . هذه نقطة هامة ولكن يجب تحديد هذه المسؤولية بنصوص تجعلهم مسؤولين عن : خرق الدستور ، والخيانة العظمى والاثراء غير المشروع ، وإساءة استعمال السلطة ، والإهمال ، ومخالفة القوانين والأنظمة ولا سيما المالية منها بالإضافة إلى مسؤوليتهم عن أعمالهم العادية ووضع نصوص تجيز لكل متضرر من سوء تصرف المسؤولين الحق بتحريك الدعوى ضدهم :", "وعندما يكون الأمر كذلك ، ويجب أن يكون ، فمعنى ذلك أن النظام قد تحول بصورة طبيعية إلى نظام رئاسي الرئيس فيه مسؤول وهذا يعني أيضاً أن دور رئيس الوزراء هو دور وهمي أو دور موظف لدى رئيس الجمهورية وهو ما حرصت على التبشير به الوثيقة البيان .", "* النقطة الرابعة : حصر إقرار القضايا المصيرية بأكثرية ثلثي أعضاء المجلس النيابي : وهو مبدأ جد خطير خاصة أن الوثيقة لم تحدد القضايا المصيرية من جهة أخرى فإن الاختلافات السياسية الكبرى في النظرة إلى الأمور الهامة بين مختلف الكتل والفئات والطوائف يجعل من هذا النص سيفاً بيد الثلث الأمر الذي يخالف قواعد الأكثرية والأقلية . القسم الثالث : وعود باصلاحات اجتماعية واقتصادية ومالية وإدارية ودفاعية وصحافية وإنشاء مجلس أعلى للتخطيط والإنماء : وهذه الوعود أشبه ببيان وزاري ، فلا يمكن الوقوف عندها إلا بعد أن تكشف بنودها ومضامينها التي نأمل أن تأتي إيجابية بناءة تزيل الغبن وترفع الحرمان وتحقق العدل وتنشئ جيشاً قوياً وطنياً بعيداً عن التعصب الأعمى ويكون للجميع ولحماية الوطن خاصة من التهديدات الخارجية الإسرائيلية ، وترفع مستوى التعليم وتقضي على آفاقه وتحبط المؤامرات التي تستهدف مسخ الثقافة العربية الإسلامية وتشويه التاريخ الإسلامي المشرق وبتر لبنان عن عالمه العربي وحضارته الإسلامية العريقة . سابعاً : الحل من منظور ميثاق ١٩٥٥ الإسلامي : وفي الخمسينات وعندما أدرك المسلمون أن حقوقهم مهضومة ومضيعة ، اجتمع مسؤولوهم وأصدروا ميثاقاً سموه ( الميثاق الوطني للهيئات الإسلامية ) . وقد جاء في الميثاق ما نصه : لما كان استقرار الحكم في لبنان لا يتحقق إلا بالتعاون الصادق بين فئتي"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0060.png"}, {"n": 61, "paras": ["المواطنين مسلمين ومسيحيين الذين تتألف منهم الجمهورية اللبنانية . ولما كان ذلك التعاون لا يتم إلا بتوزيع الحقوق بين أصحابها على أساس العدل والإنصاف والمساواة ، ولما كان المسلمون في لبنان يتساوون عدداً - على أقل تعديل - مع إخوانهم المسيحيين وكان في توزيع الوظائف والمرافق الحالي في الدولة إجحاف ظاهر بحقوق المسلمين . ولما كان العدل من جهة والحرص على الوحدة الوطنية من جهة ثانية يوجبان على عناصر الوطن أن تتعاون لإزالة هذا الإجحاف . ولما كانت المادة ٩٥ من الدستور قد ضمنت مبدأ العدل وروح الوفاق بين المواطنين ، ومن أجل هذا التعاون الصادق وضع الموقعون أدناه هذا الميثاق وتعهدوا بالعمل على تحقيقه بجميع الوسائل المشروعة . المادة الأولى : توزع المنافع والمرافق والوظائف في الدولة وفي جميع المؤسسات ذات المنفعة العامة على أساس المساواة بين المسلمين والمسيحيين ، وتراعى في هذا التوزيع النوعية والعددية من حيث أهمية المناصب وعدد الموظفين فينال المسلمون نصيبهم المشروع في الحقائب الوزارية والمديريات الرئيسية وفي التمثيل الخارجي ، وفي المناصب كافة ولا سيما التوجيهية . المادة الثانية : توزع مقاعد المجلس النيابي مهما يكن عددها مناصفة بين المسلمين والمسيحيين ريثما يجري إحصاء . المادة الثالثة : يتعهد موقعو الميثاق أن يؤيدوا رجال الحكم وسواهم من المواطنين الذين يتولون منصباً عالياً ما داموا حريصين على احترام هذا الميثاق والعمل على تنفيذه ، ويحجبون ثقتهم عنهم ويعلنون معارضتهم لكل من يخالفه . المادة الرابعة : يتعهد ممثلو المسلمين في الوزارة وفي النيابة أن يكونوا أمناء لهذا الميثاق وأن يعملوا على تحقيقه ، ويتعهد رئيس الوزراء بصورة خاصة أن يضع هذه المطالب في طليعة الشروط التي يتسلم الحكم على أساسها .", "كما وأن المرشحين لهذا المنصب يتعهدون بأن لا يقبلوا الحكم إلا على هذه الأسس . وما ينطبق على رئيس الوزراء ينطبق على كل وزير مسلم في الدولة ، على أنه في حالة تخلي رئيس الوزراء عن منصبه ليأسه من تحقيق بنود هذا الميثاق يتعهد المرشحون لهذا المنصب أن لا يقبل أحد منهم بتوليه إلا على أساس إزالة الأسباب التي اقتضت اعتزاله الحكم على أساس تحقيق مطالب المسلمين . المادة الخامسة : إذا استمر الوضع الشاذ القائم بحرمان المسلمين حقوقهم المشروعة في الوظائف والمرافق ولم يبادر المسؤولون إلى إصلاح الحال بتحقيق المطالب الإسلامية فإن المسلمين يعتبرون أن هناك استنكافاً من الرئيس الأول عن تطبيق أحكام الدستور ونكولاً منه عن وعوده المتكررة لإنصاف المسلمين ، وفي هذا الحال يكون موقعو هذا الميثاق ملزمين باتخاذ جميع الوسائل والتدابير التي تضمن الوصول إلى حقوقهم الدستورية المشروعة . رئيس المجلس الإسلامي : حسين العويني . رئيس الهيئة الوطنية : الدكتور محمد خالد . رئيس اتحاد الشبيبة الإسلامية : الدكتور محمد كنيعو . رئيس الخلية الاجتماعية : عبد الله المشنوق . رئيس رابطة الأسر البيروتية : الدكتور نسيب البربير . رئيس حزب النجادة : عدنان الحكيم ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0061.png"}, {"n": 62, "paras": ["حل المسألة من منظور إسلامي", "الفصل السادس"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0062.png"}, {"n": 63, "paras": ["خلفيات الأزمة اللبنانية وحلها من منظور إسلامي", "صحيح أن للأزمة اللبنانية خلفيات وأسباباً متعددة ، محلية وعربية ودولية .. اجتماعية واقتصادية وسياسية .. كما تبين معنا .. ولكن تبقى هنالك خلفية أساسية كامنة وراء الأزمة اللبنانية ووراء كل أزمة ، وراء الحرب اللبنانية ووراء كل حرب .. هذه الخلفية تتمثل في فشل النظم الوضعية وعجزها عن تحقيق الأمن والإستقرار والكفاية والعدل والحرية للإنسان .", "لا يقال هذا الكلام عن لبنان والحرب اللبنانية فحسب وإنما يسحب هذا الكلام على دول الأرض التي تحتكم إلى شرائع ودساتير وضعية تسببت ولا تزال تتسبب بأزمات ومشاكل وحروب وكوارث ومآسي على طول المساحة التي يعيش عليها الكائن البشري .", "في كل مكان فتن وثورات ومذابح .. في كل بلد مشكلات اجتماعية واقتصادية وسياسية .. في أكثر المجتمعات العالمية ظواهر عقائدية وأخلاقية غريبة مدمرة كان آخرها كارثة ( معبد الشعب ) في غويانا بأميركا ..", "هذه الظواهر والمشاكل ، وما يلاحظ عليها من تزايد ونمو مضطرد تشكل دليلاً قاطعاً على إفلاس الإنسان وعجزه عن أن يحكم نفسه بنفسه ، أو يسير في متاهات الحياة بدون دليل أقوى وأعرف بالحياة وأقدر على حل مشاكلها منه .. والحل ليس كما يتبادر إلى ذهن البعض يكون في استبدال حكومة بأخرى ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0063.png"}, {"n": 64, "paras": ["أو حاكم بآخر .. والشواهد التاريخية في عصرنا الحاضر تقطع ببطلان هذا الاعتقاد ، إذ المجتمعات والدول في دوامات الفراغ ، كلما جاءت واحدة لعنت أختها ..", "القضية تكمن في المنهج الذي يربي الإنسان ويحكمه ويحدد نظرته للكون والإنسان والحياة ..", "فما دامت المناهج والنظم التي تربي الإنسان وتحكمه تصدر عن مفهوم مادي محض للكون والإنسان والحياة .. مناهج ألغت من حسابها المفاهيم الغيبية الميتافيزيقية وكل ما يصل الإنسان بمصدر الوجود وسبب الوجود وغاية الوجود ، فلن تفرز إلا مجتمعات ومخلوقات تعيش بلا هدف ، وتتحرك بلا قيم ، يمكنها أن تتوسل بكل وسيلة ولو كانت قذرة من أجل تحقيق اشباعاتها الغريزية .. وبذلك تتحول المجتمعات البشرية ولقد تحول الكثير منها أو كاد إلى غابات يتهارش فيها الناس ويتناطحون كالبهيمة بل أضل سبيلاً ..", "فما دامت شرائع الهوى هي الحاكمة ، وما تفتقت عنه عقول البشر من نظم وفلسفات هي السائدة .. وما دامت شعارات ( الدين لله والوطن للجميع ) و ( ما لقيصر لقيصر وما لله لله ) و ( الدين أفيون الشعوب ) و ( لا إله والحياة مادة ) هي الأكثر رواجاً وانتشاراً ، فعبثاً تحاول البشرية التفتيش عن الأمن والاستقرار والعدالة والمساواة وغيرها من الأماني والأمنيات", "إننا بكل صراحة نقول : يوم إن كان الحكم للإسلام أي لله ولشريعة الله في هذه البلاد وفي غير هذه البلاد لم يكن هنالك شيء مما نعاني منه اليوم مسلمين وغير مسلمين ..", "لم يكن هنالك غير سلطان الله وسلطان الشرع .. لم تكن هنالك محسوبيات ووساطات أو مواطنية ذات درجات .. إنما كان الجميع أمام شرع الله سواء ..", "وإذا كان بعض الحكام قد شذ عن هذه القاعدة في فترة من فترات التاريخ الإسلامي المديد فهذا ليس حجة على الإسلام وإنما حجة للإسلام على من شد وانحرف كائناً من كان ..", "كانت حقوق الأقليات في ظل الدولة الإسلامية مصونة تماماً كحقوق المسلمين ..", "وأن يكون الحكم الاسلام فهذا لا يعني أن يكون طائفياً أبداً .. إن العكس هو الصحيح .. إن الحكم بالإسلام يعني خضوع الحاكم قبل المحكوم لشرعة الله .. يعني زوال الشخصانية ، زوال الطاغوت والطغيان ، زوال التسلط ، زوال المحسوبيات والوساطات .. يعني أن يصبح الناس جميعاً سواسية كأسنان المشط الواحد ، كلهم لآدم وآدم من تراب ، إن أكرمهم عند الله أتقاهم ..", "إننا حين نطرح الإسلام كبديل ، فلإيماننا بأنه السبيل الوحيد لإنقاذ لبنان وغير لبنان ، ولإسعاد اللبنانيين وغير اللبنانيين بدليل من قوة محتواه ومن نجاح تجربته ..", "إننا لا نطرحه بفعل حسن طائفي ، لأن الدين في حقيقته طريق حب للناس وسلام بينهم وفعل الخير لهم . فمن تمسك بالدين على هذا الفهم والمنطق فقد تمسك بالحب والخير والحق والعدل ..", "الإسلام والطائفية (١)", "إن الشعوب التي حكمها الإسلام لم تعرف التعصب كما زعم الأب بطرس ضو منذ الفتح الإسلامي حتى الحروب الصليبية . فقد كان الجميع يعيشون في ظل الدولة الإسلامية بسلام وأمان ..", "وعندما كان بعض الحكام ولظروف استثنائية يحاولون هضم بعض حقوق", "(١) من رسالة الاسلام والطائفية صادرة عن الجماعة الاسلامية ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0064.png"}, {"n": 65, "paras": ["أهل الذمة كان علماء المسلمين يهبون في وجه الحكام دفاعاً عن حقوق الأقليات . وهذا الإمام الأوزاعي رضي الله عنه يبعث برسالة جريئة إلى أبي جعفر المنصور يستنكر فيها بشدة إجلاء قسم من المسيحيين عن قراهم في لبنان ، فيرجع الخليفة عن تنفيذ هذا العمل الجائر المخالف لشريعة الإسلام .", "وجاء عصر الانحطاط إلى الشرق ، كما بدأت أوروبا تنهض من كبوتها وتستيقظ من غفوتها .. وتطل بعينيها الجائعة .. على بلاد العرب والمسلمين ... وهي تترنح بين ضعف وقوة .. وتتخبط في جهل وجمود .. وبدأت الأطماع في الظهور ... وبدأ الاستعمار يميط اللثام عن وجهه تارة ... ويختفي أخرى .. وكانت الحروب الصليبية .. ولكنها فشلت .. وما زال الصليبيون يتحينون الفرص للعودة إلى الشرق .", "وجاءت الفرصة عندما دب الضعف في جسم الدولة العثمانية ، وراح الأتراك يمعنون في الظلم والاضطهاد للمسلمين والمسيحيين دون تمييز . وسواء كانت هذه الأعمال بدافع التعصب للقومية التركية ، أو بدافع حب السيطرة والسلطان ، فإنها انحراف واضح عن الإسلام لا يمكن أن يكون هو مسؤولاً عنه بأي حال من الأحوال .", "ولقد عرف الاستعمار كيف يستغل هذه المظالم ، فتقدمت فرنسة تفرض لنفسها حماية الموارنة في لبنان ، وقامت إنكلترة تدعي حماية الدروز فيه بينما كانت حماية الأرثوذكس من نصيب روسية القيصرية . وطبيعي بعد هذا أن يمتد الصراع القائم في أوروبة بين هذه الدول الاستعمارية إلى لبنان ليتخذ أبشع شكل طائفي في فتنة عام ١٨٦٠ بين الدروز والموارنة . ولو أننا تركنا التاريخ جانباً وتساءلنا : هل في الدين بدور طائفية ؟ وهل التمسك بالدين يؤدي إلى التعصب والبغضاء ؟ أولاً : تقديس الله سبحانه ، والإيمان به ، والتقرب إليه بالعبادة . ثانياً : محاربة الالحاد في جميع صوره وأشكاله . ثالثاً : الدعوة إلى التمسك بالأخلاق والفضائل الإنسانية . رابعاً : التسامح الديني القائم على الحب العميق للبشر ، والذي يقول المسيح عليه السلام فيه : « أحبوا أعداءكم ، باركوا لاعنيكم » ويقول الرسول عليه الصلاة والسلام فيه : « صل من قطعك ، وأعط من حرمك ، واعف عمن ظلمك ، وأحسن إلى من أساء إليك » .", "وإذا كان الإسلام قد انفرد عن غيره بعد ذلك بالقوانين والأنظمة فليس معنى هذا نشوب العداوة والخصومة بينهما .. طالما أن الرسول عليه الصلاة والسلام ما زال يوصي المسلمين بقوله : « من آذى ذمياً فقد آذاني .. ومن آذاني كنت خصمه يوم القيامة .. » وطالما أن قولة المسيح عليه السلام ما تزال ترن في آذان المسيحيين : « المجد لله في الأعالي ، وعلى الأرض السلام وفي الناس المسرة » . رغم الاختلافات الموجودة بين الأديان ، فإن المتوافقات الأربع التي ذكرناها آنفاً ، وهذه الدعوة الحارة إلى المحبة والسلام ، كافية حقاً كي نستخلص منها حيزاً من الحياة مشتركاً .. ومجالاً من الحضارة يتنفس فيه الجميع في إيقاع واحد حتى ولو لم يستنشقوا نفساً موحداً ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0065.png"}, {"n": 66, "paras": ["ه - حق تنفيذ ما تأمره أو تسمح به شريعته الخاصة : فالمسيحي مثلاً يستطيع أن يشرب الخمر وأن يأكل لحم الخنزير وأن يتعاطى كل الأمور المباحة في ديانته ، ولو كانت محرمة في الشرع الإسلامي . ب - الحقوق الاجتماعية : ويلخصها القانون الإسلامي المعروف : « لهم ما لنا وعليهم ما علينا » .", "١ - حق المساواة : ليس في الإسلام خرافة شعب الله المختار أو العرق النازي الممتاز .. فالناس سواسية كأسنان المشط الواحد . أ - في القيمة الاجتماعية : « يا أيها الناس إنا خلقناكم من ذكر وأنثى ، وجعلناكم شعوباً وقبائل لتعارفوا ، إن أكرمكم عند الله أتقاكم » . كما قال الرسول في خطبة الوداع : « أيها الناس إن ربكم واحد .. وإن أباكم واحد . كلكم لآدم وآدم من تراب » . ب - في تقلد الوظائف : يستطيع المسيحي أن يتقلد كل الوظائف الحكومية دون تمييز بينه وبين المسلم إلا حسب الكفاءة والقدرة .. ويستطيع حتى أن يكون وزيراً في الدولة الإسلامية كما جاء في كتاب الأحكام السلطانية للماوردي . ج - أمام القضاء : والتاريخ الإسلامي مليء بالمآثر في هذه الناحية . وهذه على سبيل المثال لا الحصر - قصة اليهودي الذي اشتكى على علي بن أبي طالب رضي الله عنه إلى أمير المؤمنين عمر بن الخطاب .. وقال عمر : إجلس يا أبا الحسن بجانب خصمك .. وظهرت علامات الغضب على وجه علي رضي الله عنه فقال له عمر بن الخطاب : أغضبت إن ساويتك بخصمك ؟ فقال علي لا . ولكني غضبت لأنك لم تسو بيني وبينه فخاطبته باسمه وخاطبتني بكنيتي ( والكنية فيها تعظيم للمخاطب ) . وقصة القبطي المصري الذي ضربه ابن عمرو بن العاص وقال له أنا ابن", "حقوق أهل الذمة في التشريع الإسلامي أ - الحقوق الشخصية :", "١ - حق الحياة : وهو مضمون لجميع المواطنين في ظل دولة الإسلام . فقاتل الذمي يقتل وإن كان مسلماً . وقاتل المسلم يقتل وإن كان ذمياً .", "٢ - حق العقيدة : « لا إكراه في الدين قد تبين الرشد من الغي » . « أفأنت تكره الناس حتى يكونوا مؤمنين » « لكم دينكم ولي دين » .", "٣ - حق العبادة : وقد كرسه الرسول عليه الصلاة والسلام حين سمح لوفد نصارى نجران أن يؤدوا صلاتهم في مسجده الشريف ، كما أصدر أبو عبيدة ابن الجراح بياناً إلى الطوائف غير المسلمة في سورية وفلسطين جاء فيه : « إن الطوائف غير المسلمة يستطيعون أن يدقوا الناقوس في أي وقت من أوقات الليل أو النهار ، إلا في الأوقات التي يؤدي فيها المسلمون صلواتهم ، وأن يرفعوا الصليب أيام أعيادهم . بل لقد ذهب المسلمون إلى أبعد من هذا فكانت دولتهم تقوم بإصلاح الكنائس ومعابد غير المسلمين على نفقتها الخاصة . ( عن مجلة إسلامية ريفيو ) .", "٤ - حق اختيار القانون الذي يحكم به : فقد جاء في كتاب الأحكام السلطانية للماوردي : « إذا رغب غير المسلمين في رفع قضاياهم إلى رؤساء دينهم فلا تعترضوا سبيلهم » . فالمسيحي يستطيع في أموره الشخصية من زواج وطلاق وميراث وغيرها أن يرجع إلى رؤساء دينه ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0066.png"}, {"n": 67, "paras": ["الأكرمين فاشتكى القبطي إلى أمير المؤمنين عمر الذي قال قولته المشهورة عند ذلك : « متى استعبدتم الناس وقد ولدتهم أمهاتهم أحراراً » ؟؟ ثم أعطاه عصاه وقال ، إضرب ابن الأكرمين .", "٢ - حق المواطنية : يظن كثير من الناس ومنهم الأب بطرس ضو أن المسيحي يعيش في ظل الدولة الإسلام وكأنه غريب أو خاضع أو مستعمر . و لكن الواقع أن المسيحي حين يرتضي لنفسه في ظل دولة الإسلام ويحمل التابعية الإسلامية يصبح مواطناً بكل ما تحمل هذه الكلمة من معنى .. يتمتع بكل حقوق المواطن المسلم ، وعليه جميع واجباته - غير العقائدية - ولقد كان الرسول عليه الصلاة والسلام يستدين من بعض رجالات اليهود وفي الصحابة من الأغنياء من يفتدي الرسول بكل ماله .. ومع ذلك كان الرسول يستدين من يهودي .. لشيء واحد .. هو أن يعلّم المسلمين أن أهل الذمة - يهود ومسيحيين - مواطنون يجب أن نتعامل معهم .. ونأخذ منهم ونعطيهم ..", "وفي هذا السبيل كانت إباحة طعام النصارى للمسلمين وإباحة زواج المسلم من كتابية : « اليوم أحل لكم الطيبات وطعام الذين أوتوا الكتاب حل لكم وطعامكم حل لهم .. والمحصنات من المؤمنات .. والمحصنات من الذين أوتوا الكتاب » .", "وليس هناك أكثر من المؤاكلة والمصاهرة داعياً لتقوية روابط المواطنية بين المسلمين والمسيحيين .", "ج - الحقوق الاقتصادية :", "١ - حق تأمين العمل : عملاً بالقانون الإسلامي لهم ما لنا وعليهم ما علينا . ومصداقاً لقول عمر رضي الله عنه ، إن اليد التي لا تجد لها عملاً في الخير تجد لها في الشر أعمالاً .", "٢ - التأمين الاجتماعي عند الفقر والمرض والجهل : وهذا هو نص المنشور الإسلامي الذي وزعه المسلمون بعد فتح العراق : « أيما شيخ عجز عن العمل ، أو أصابته آفة من الآفات ، أو كان غنياً فافتقر ، طرحت جزيته إن كان ذمياً ، وطرحت زكاته إن كان مسلماً ، واعيل هو وعياله من بيت مال المسلمين » كما أن قصة عمر مع اليهودي الذي كان يتكفف الناس ، فقال له عمر رضي الله عنه : والله ما أنصفناك إن أخذنا منك الجزية وأنت شاب ، وتركناك تتسول وأنت شيخ .. ثم فرض له راتباً من بيت المال ..", "٣ - حق التملك : والذمي يمتاز هنا عن المسلم بأنه لا يدفع الزكاة على ممتلكاته لأنها عبادة إسلامية ، طالما أنه يدفع الجزية . والواقع يشهد أن مقدار الزكاة التي تزيد نسبتها بازدياد الممتلكات أكبر بكثير من الجزية المحدودة ..", "ونحن حين نطرح الإسلام كبديل ، فليس من قبيل حل المشكلة اللبنانية فحسب ، وإنما من أجل الخروج من الخلل العام والتصدع العام الذي يتعرض له كيان هذه الأمة في كل مكان ..", "فالإسلام ليس مسؤولاً في شيء عن الواقع السيء الذي آلت إليه قضايا الأمة الاجتماعية والاقتصادية والسياسية والعسكرية .. لأنه في الواقع مبعد عن دوره القيادي والحضاري بل ومحارب عقر بلاده وأرضه ..", "ونحن حين نطرح الإسلام كبديل .. فليس عن النظام اللبناني فحسب ، وإنما عن الأنظمة التي تحكم هذه البلاد جمعاء ، لأنها جميعاً أنظمة مخالفة لفطرة الكون والإنسان والحياة ، وغير قادرة على استيعاب مشاكل الإنسان والحياة .", "ونحن ندرك أن المعارضة للحل الإسلامي والحكم الإسلامي لن تكون من جانب النصارى فحسب ، وإنما ستكون كذلك من سدنة الأفكار والنظم المادية القائمة في بلاد المسلمين ..", "وإنما جاء التركيز هنا على جانب موقف النصارى من الحكم الإسلامي لارتباط الحل بالقضية اللبنانية والنصارى فريق فيها .."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0067.png"}, {"n": 68, "paras": ["وأخيراً فلا بد من استعراض الحقائق التالية :", "١ - الكل يعلم أن الدين المسيحي ليس فيه قوانين وأنظمة للحكم والسياسة ، ومعنى هذا أن الحكم لن يكون مسيحياً في جميع الأحوال ، فهو إما أن يكون مستورداً من الخارج يعتمد على دساتير وضعية . وإما أن يكون نابعاً من الداخل عربياً إسلامياً . ولو إن إخواننا المسيحيين حين يعارضون أن يحكموا بالإسلام سيحكمون بنظام مسيحي لكان لهم الحق في ذلك . ولكن طالما أنهم في جميع الأحوال سيحكمون بدستور غير مسيحي أصبح من الضروري مراعاة الحقائق التالية : أولاً : إن الدستور الإسلامي دستور عربي يتمتع بعنصر الذاتية بينما الدساتير العلمانية غريبة عن الأمة العربية . ثانياً : إن الدستور الإسلامي دستور جربته الأمة العربية وحققت في ظلاله أعظم حضارة إنسانية . ولم تتأخر عن الركب العالمي إلا عندما تخلت عنه .. ولم يضطهد المسيحيون إلا عندما تنكر الحكام لهذا الدستور وخالفوه . ثالثاً : أن الدستور الإسلامي قد امتزج بالواقع العربي امتزاجاً كلياً خلال ثلاثة عشر قرناً حتى طبع العادات والتقاليد والشخصية العربية بطابعه الخاص . رابعاً : إن الدستور الإسلامي يضمن للمسيحيين الحقوق التي يطلبونها .. والتي يطالبون بدساتير علمانية من أجل ضمانها وقد أوضحنا منذ قليل هذه الناحية . خامساً : أن الدستور الإسلامي دستور إرتضته الأكثرية العربية المسلمة .. وكل أنظمة العالم تخضع لحكم الأكثرية .", "٢ - أما بالنسبة للجزية فجوابنا ما يلي : أولاً : إن الجزية المفروضة على المسيحيين في الحكم الإسلامي إنما هي ضريبة مقابل دفاع الدولة عنهم . وحين يريد المسيحيون أن يحاربوا مع المسلمين لحماية الوطن الذي يعيشون في ظله فإن الجزية ترفع عنهم كما حدث لقبيلة ( الجراجمة ) المسيحية التي كانت تقيم بجوار أنطاكية . وفي مقابل ذلك فإن كل مسلم يتأخر عن تأدية واجبه في الدفاع عن الوطن تفرض عليه الجزية كما تفرض على المسيحيين ، وقد أعفي الفلاحون المصريون من الخدمة العسكرية على الرغم من أنهم كانوا على الإسلام وفرضت عليهم الجزية (١) . ثانياً : إن الجزية التي يدفعها المسيحي إنما تقابل الزكاة التي يدفعها المسلم . والجزية والزكاة إنما يدفعها المسيحي والمسلم للمساهمة في نفقات التأمين الاجتماعي الذي تؤمنه الدولة الإسلامية لجميع المواطنين دون تمييز . وهذا ما أشار إليه عمر بن الخطاب حين قال لليهودي : ما أنصفناك إن أخذنا منك الجزية وأنت شاب وتركناك تتسول وأنت شيخ .", "٣ - وأما بالنسبة لرئاسة الدولة الإسلامية العليا ، فالمهم في نظر كل عاقل هو دستور الرئيس لا شخصه . وحين ترضى الأكثرية أن تحكم بالإسلام هل يعقل أن نطلب من إنسان مسيحي لا يؤمن بالإسلام أن يكون رئيساً للدولة وينفذ دستوراً لا يؤمن به ؟؟ وماذا يقول هؤلاء المعترضون لو أننا اقترحنا عليهم أن يأخذوا كارتر إلى روسية لينفذ الدستور الشرعي هناك ، وأن يحضروا بريجينف إلى الولايات المتحدة ليحكم بالنظام الرأسمالي ؟؟ كما إن بقاء رئاسة الدولة في أيدي المسلمين ممن تتوفر فيهم المؤهلات التي يفرضها الشرع الإسلامي إنما هو ضمان لتطبيق نظام الإسلام العادل على الجميع . ونذكر هنا ما قاله بطريرك أنطاكية للملك فيصل الأول أثناء ثورة ١٩١٦ : « إني أبايعك على الإسلام ، طالما أنت منفذ لتعاليم هذا الدين » .", "(١) - راجع كتاب الدعوة الى الاسلام ، تأليف سير . ن . و . أرنولد . ص . ٥٩ ."], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0068.png"}, {"n": 69, "paras": ["للمسألة اللبنانية - وإن كان صعب التحقيق والتنفيذ - فسيبقى ما عداه ترقيعات لا تزيد الطين إلا بلة إن في ذلك لذكرى ... للبنانيين مسلمين ومسيحيين ، وللعرب أجمعين ، بل وللعالمين ، لمن كان له قلب أو ألقى السمع وهو شهيد .. والله غالب على أمره ولكن أكثر الناس لا يعلمون", "خلاصة الحل من منظور إسلامي", "وأخيراً .. في ضوء الخلفيات الكامنة وراء الأزمات اللبنانية والتي غدت أصيلة في كيان لبنان غير قابلة للزوال كما قد رأينا .. وفي ضوء التجربة التي مارسها لبنان ككيان منفصل عن سوريا خلال فترة الاستقلال التي ناهزت الخمسين عاماً ، والتي أكدت فشل هذه التجربة وعدم صلاحيتها للبقاء والاستمرار ، لكونها كانت مصطنعة وغير طبيعية .. وفي ضوء الحلول المطروحة من التنظيمات المارونية ( الجبهة اللبنانية ) والتي لا تزال تدق على وتر طائفي وتنبع عن حسن طائفي وتركز على التقسيم الطائفي ، وما ينتج عن ذلك - في حال وقوعه وتحقيقه - من أزمات على كل صعيد ومن مخاطر تضاف إلى مخاطبة الوجود الإسرائيلي في فلسطين .. وفي ضوء مشروع علمنة لبنان والتي سبق أن شجبته القوى الإسلامية الرسمية والشعبية ، والذي يعتبر في مفهوم الشرع الإسلامي مرفوضاً شكلاً وأساساً .. في ضوء هذه المعطيات وغيرها .. نرى - كخطوة أولى - أن الحل الذي يمكن أن يفتت التناقضات المتأصلة في الكيان اللبنانى هو أن يندمج في كيان أكبر منه .. أن يعود إلى ما كان عليه قبل عام ١٩٢٠ .. جزءاً من بلاد الشام .. وإن كان لا يغيب عن البال ما يعترض هذا الحل من عقبات على كافة المستويات المحلية والعربية والدولية .. إن الحل إن لم يكن في حقيقته ومؤداه ومحصلته قادراً على وضع حد نهائي"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0069.png"}, {"n": 70, "paras": ["الفهرس", "الصفحة الإهداء ٥ تمهيد ٧", "الفصل الأول لبنان .. على مدار التاريخ ٩", "الفصل الثاني تركيب البنية اللبنانية ١٧", "الفصل الثالث آراء في خلفيات الحرب اللبنانية ٢٥", "الفصل الرابع خلفيات أساسية للمسألة اللبنانية ٣٧", "الفصل الخامس الحلول المطروحة للمسألة اللبنانية ٧١", "الفصل السادس حل المسألة اللبنانية من منظور إسلامي ١٢٣ الفهرس ١٣٩"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0070.png"}, {"n": 71, "paras": ["كتب للمؤلف", "١ - مشكلات الدعوة والداعية .", "٢ - الإسلام فكرة وحركة وانقلاب .", "٣ - نحو حركة إسلامية عالمية واحدة .", "٤ - حركات ومذاهب في ميزان الإسلام .", "٥ - الإسلام والجنس .", "٦ - كيف ندعو إلى الإسلام ؟", "٧ - قوارب النجاة في حياة الدعاة .", "٨ - ماذا يعني انتمائي إلى الإسلام ؟", "تحت الطبع", "١ - الشباب والتغيير الإسلامي", "٢ - الجزء الأول من [ الموسوعة الحركية ] تراجم إسلامية من القرن الرابع عشر الهجري"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0071.png"}, {"n": 72, "paras": ["تطلب جميع منشوراتنا من الشركة المتحدة للتوزيع بيروت - شارع سوريا - بناية صمدي وصالحة هاتف: ٢٩٥٥٠١ - ص.ب: ٧٤٦٠ - برقياً: بيوشران", "السعر ٦ ليرات", "Y١٥"], "img": "../../../_ocr-work/libocr/yakan-lubnaniyya/pages/0072.png"}]};
